/* ============================================
   PAGE HERO
============================================ */

.page-hero{
  padding:180px 0 110px;

  background:
  linear-gradient(
    135deg,
    #04111f,
    var(--color-midnight),
    #0d2743
  );

  color:white;

  text-align:center;
}

.page-hero .display-heading{
  color:white;

  margin-top:10px;
}

.page-description{

  max-width:760px;

  margin:28px auto;

  color:#d7e0e8;

  font-size:1.08rem;

  line-height:1.9;
}

.page-actions{

  display:flex;

  justify-content:center;

  gap:18px;

