  flex-wrap:wrap;
}

/* ============================================
   COSMIC INSIGHT CARD
============================================ */

.cosmic-card{
  position:absolute;
  top:30px;
  right:-20px;

  width:240px;

  padding:22px;

  background:rgba(8,20,35,.75);

  backdrop-filter:blur(18px);
  -webkit-backdrop-filter:blur(18px);

  border:1px solid rgba(214,166,59,.35);

  border-radius:18px;

  box-shadow:0 18px 45px rgba(0,0,0,.25);

  z-index:8;

  animation:floatCard 5s ease-in-out infinite;
}

.cosmic-icon{
  color:var(--color-gold);
  font-size:20px;
  display:block;
  margin-bottom:10px;
}

.cosmic-card h4{
  margin:0 0 18px;
  color:#fff;
  font-size:1.2rem;
  font-family:var(--font-heading),serif;
}

.cosmic-item{
  display:flex;
  justify-content:space-between;
  margin-bottom:12px;
}

.cosmic-item small{
  color:#cfd6dd;
}

.cosmic-item strong{
  color:var(--color-gold-light);
}

@keyframes floatCard{
  0%{transform:translateY(0);}
  50%{transform:translateY(-8px);}
  100%{transform:translateY(0);}
}

@media(max-width:950px){

.cosmic-card{
display:none;
}

}

/* ============================================
   BOOKING — SERVICE SELECTION
============================================ */

.booking-header {
  text-align: center;
  margin-bottom: 50px;
}

.booking-services {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.booking-service-card {
  position: relative;

  display: flex;
  flex-direction: column;
  justify-content: space-between;

  min-height: 250px;

  padding: 30px;

  text-align: left;

  background: #ffffff;

  border: 1px solid var(--color-border);
  border-radius: 22px;

  box-shadow: var(--shadow-soft);

  cursor: pointer;

  transition:
    transform 0.3s ease,
    box-shadow 0.3s ease,
    border-color 0.3s ease;
}

.booking-service-card:hover {
  transform: translateY(-6px);

  border-color: var(--color-gold-light);

  box-shadow: 0 18px 45px rgba(7, 24, 42, 0.14);
}

.booking-service-card-selected {
  position: relative;

  border-color: var(--color-gold-light);

  background:
    linear-gradient(
      135deg,
      rgba(255, 255, 255, 1),
      rgba(255, 249, 228, 0.98)
    );

  box-shadow:
    0 0 0 2px rgba(214, 166, 59, 0.28),
    0 0 18px rgba(214, 166, 59, 0.35),
    0 0 38px rgba(231, 195, 108, 0.22),
    0 18px 45px rgba(7, 24, 42, 0.14);

  animation: selectedCardGlow 2.2s ease-in-out infinite;
}

.booking-service-card-selected::before {
  content: "";

  position: absolute;

  inset: -2px;

  border-radius: 24px;

  background:
    linear-gradient(
      120deg,
      transparent 20%,
      rgba(231, 195, 108, 0.75) 40%,
      rgba(255, 255, 255, 0.95) 50%,
      rgba(231, 195, 108, 0.75) 60%,
      transparent 80%
    );

  background-size: 220% 100%;

  animation: goldenShimmer 2.8s linear infinite;

  pointer-events: none;

  z-index: 0;

  opacity: 0.7;
}

.booking-service-card-selected > * {
  position: relative;
  z-index: 1;
}

@keyframes goldenShimmer {
  0% {
    background-position: 220% 0;
  }

  100% {
    background-position: -220% 0;
  }
}

@keyframes selectedCardGlow {
  0%,
  100% {
    box-shadow:
      0 0 0 2px rgba(214, 166, 59, 0.25),
      0 0 16px rgba(214, 166, 59, 0.28),
      0 0 32px rgba(231, 195, 108, 0.16),
      0 18px 45px rgba(7, 24, 42, 0.14);
  }

  50% {
    box-shadow:
      0 0 0 2px rgba(214, 166, 59, 0.45),
      0 0 24px rgba(214, 166, 59, 0.48),
      0 0 48px rgba(231, 195, 108, 0.28),
      0 20px 48px rgba(7, 24, 42, 0.16);
  }
}

.booking-service-category {
  display: inline-block;

  margin-bottom: 14px;

  color: var(--color-gold-dark);

  font-size: 0.72rem;

  font-weight: 700;

  letter-spacing: 0.12em;

  text-transform: uppercase;
}

.booking-service-card h3 {
  margin: 0 0 12px;

  color: var(--color-midnight);

  font-family: var(--font-heading), Georgia, serif;

  font-size: 1.35rem;

  line-height: 1.3;
}

.booking-service-card p {
  margin: 0;

  color: var(--color-muted);

  line-height: 1.7;
}

.booking-service-select {
  align-self: flex-start;

  margin-top: 25px;

  color: var(--color-gold-dark);

  font-size: 0.85rem;

  font-weight: 700;
}

.booking-next {
  display: flex;

  justify-content: center;

  margin-top: 45px;
}

/* MOBILE */

@media (max-width: 950px) {

  .booking-services {
    grid-template-columns: repeat(2, 1fr);
  }

}

@media (max-width: 600px) {

  .booking-services {
    grid-template-columns: 1fr;
  }

  .booking-service-card {
    min-height: auto;
  }

}
