/* =========================================================
   ADMIN SETTINGS
   ========================================================= */

.admin-settings-page {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
}


/* =========================================================
   HEADER
   ========================================================= */

.admin-settings-header {
  margin-bottom: 32px;
}

.admin-settings-eyebrow {
  margin-bottom: 8px;

  color: var(--color-gold-dark);

  font-size: 0.68rem;

  font-weight: 700;

  letter-spacing: 0.2em;
}

.admin-settings-header h1 {
  margin: 0;

  color: var(--color-midnight);

  font-family:
    var(--font-heading),
    Georgia,
    serif;

  font-size: clamp(
    2rem,
    3vw,
    2.7rem
  );

  font-weight: 500;
}

.admin-settings-header p {
  margin: 10px 0 0;

  max-width: 600px;

  color: var(--color-muted);

  font-size: 0.9rem;

  line-height: 1.7;
}


/* =========================================================
   SETTINGS CARD
   ========================================================= */

.admin-settings-card {
  margin-bottom: 22px;

  padding: 28px 30px;

  background:
    linear-gradient(
      145deg,
      rgba(255, 255, 255, 0.96),
      rgba(250, 247, 239, 0.96)
    );

