    rgba(228, 218, 198, 0.85);

  border-radius: 20px;

  box-shadow:
    0 12px 35px
    rgba(7, 24, 42, 0.045);
}


/* =========================================================
   CARD HEADER
   ========================================================= */

.admin-settings-card-header {
  display: flex;

  align-items: center;

  gap: 16px;
}

.admin-settings-card-icon {
  width: 46px;
  height: 46px;

  flex-shrink: 0;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 13px;

  background:
    rgba(214, 166, 59, 0.1);

  border: 1px solid
    rgba(214, 166, 59, 0.16);

  font-size: 1.15rem;
}

.admin-settings-card-header h2 {
  margin: 0;

  color: var(--color-midnight);

  font-family:
    var(--font-heading),
    Georgia,
    serif;

  font-size: 1.15rem;

  font-weight: 600;
}

.admin-settings-card-header p {
  margin: 4px 0 0;

  color: var(--color-muted);

  font-size: 0.78rem;

  line-height: 1.5;
}


/* =========================================================
   DIVIDER
   ========================================================= */

.admin-settings-divider {
  width: 100%;

  height: 1px;

  margin: 24px 0;

  background:
    rgba(228, 218, 198, 0.75);
}


/* =========================================================
   INFORMATION GRID
   ========================================================= */

.admin-settings-info-grid {
  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 24px;
}

.admin-settings-info-item {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 7px;
}

.admin-settings-info-item span {
  color: #938b80;

  font-size: 0.62rem;

  font-weight: 700;

  letter-spacing: 0.13em;
}

.admin-settings-info-item strong {
  min-width: 0;

  overflow-wrap: anywhere;

  color: var(--color-midnight);

  font-size: 0.88rem;

  font-weight: 600;
}


/* =========================================================
   SECURITY ACTION
   ========================================================= */

.admin-settings-action {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 25px;
}

.admin-settings-action > div {
  min-width: 0;
}

.admin-settings-action strong {
  color: var(--color-midnight);

  font-size: 0.9rem;

  font-weight: 600;
}

.admin-settings-action p {
  margin: 6px 0 0;

  color: var(--color-muted);

  font-size: 0.78rem;

  line-height: 1.6;
}

.admin-settings-action-button {
  flex-shrink: 0;

  display: inline-flex;

  align-items: center;

  justify-content: center;

  gap: 10px;

  min-height: 44px;

  padding: 0 18px;

  border-radius: 11px;

  background:
    linear-gradient(
      135deg,
      var(--color-midnight),
      #142f4b
    );

  color: var(--color-gold-light);

  font-size: 0.76rem;

  font-weight: 600;

  text-decoration: none;

  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.admin-settings-action-button:hover {
  transform: translateY(-2px);

  box-shadow:
    0 8px 20px
    rgba(7, 24, 42, 0.15);
}

.admin-settings-action-button span {
  font-size: 1rem;
}


/* =========================================================
   ONLINE STATUS
   ========================================================= */

.admin-settings-online {
