  align-items: center;

  gap: 8px;
}

.admin-settings-online i {
  width: 8px;
  height: 8px;

  display: inline-block;

  border-radius: 50%;

  background: #4c9a62;

  box-shadow:
    0 0 0 4px
    rgba(76, 154, 98, 0.1);
