  outline: none;
}

.admin-availability-calendar-controls select:focus {
  border-color: var(--color-gold);
  box-shadow:
    0 0 0 3px rgba(214, 166, 59, 0.12);
}

.admin-availability-edit {
  padding: 0 14px;
  border: 1px solid var(--color-midnight);
  background: var(--color-midnight);
  color: var(--color-white);
  cursor: pointer;
}

.admin-availability-edit:hover:not(:disabled) {
  transform: translateY(-1px);
}

/* =========================
   QUICK GUIDE
   ========================= */

.admin-availability-quick-guide {
  display: grid;
  grid-template-columns:
    repeat(3, minmax(0, 1fr));
  gap: 12px;
  margin-top: 24px;
}

.admin-availability-quick-guide > div {
  padding: 15px 16px;
  border: 1px solid var(--color-border);
  border-radius: 14px;
  background:
    rgba(31, 38, 56, 0.025);
}

.admin-availability-quick-guide strong,
.admin-availability-quick-guide span {
  display: block;
}

.admin-availability-quick-guide strong {
  color: var(--color-midnight);
  font-size: 0.78rem;
}

.admin-availability-quick-guide span {
  margin-top: 5px;
  color: var(--color-muted);
  font-size: 0.71rem;
  line-height: 1.5;
}

/* =========================
   TOOLBAR
   ========================= */

.admin-availability-calendar-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-top: 20px;
  padding: 14px;
  border: 1px solid var(--color-border);
  border-radius: 15px;
  background: rgba(31, 38, 56, 0.025);
}

.admin-availability-view-toggle,
.admin-availability-month-controls {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.admin-availability-view-toggle button,
.admin-availability-month-controls button {
  padding: 0 12px;
  border: 1px solid var(--color-border);
  background: var(--color-white);
  color: var(--color-midnight);
  cursor: pointer;
}

.admin-availability-view-toggle button:hover,
.admin-availability-month-controls button:hover {
  border-color: var(--color-gold);
}

.admin-availability-view-toggle button.is-active {
  border-color: var(--color-midnight);
  background: var(--color-midnight);
  color: var(--color-white);
}

.admin-availability-month-controls strong {
  min-width: 145px;
  padding: 0 8px;
  text-align: center;
  color: var(--color-midnight);
  font-size: 0.82rem;
}

.admin-availability-today {
  border-color: var(--color-gold) !important;
}

/* =========================
   SAVE BUTTON
   ========================= */

.admin-availability-save {
  min-width: 145px;
  padding: 0 16px;
  border: 1px solid var(--color-gold);
  background: var(--color-gold);
  color: var(--color-midnight);
  box-shadow:
    0 8px 18px rgba(214, 166, 59, 0.18);
  cursor: pointer;
}

.admin-availability-save:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow:
    0 10px 22px rgba(214, 166, 59, 0.24);
}

.admin-availability-save:disabled,
.admin-availability-secondary-button:disabled,
.admin-availability-edit:disabled {
  opacity: 0.48;
  cursor: not-allowed;
  box-shadow: none;
}

/* =========================
   MESSAGES
   ========================= */

.admin-availability-calendar-error,
.admin-availability-calendar-success,
.admin-availability-calendar-loading {
  margin-top: 14px;
  padding: 12px 14px;
  border-radius: 12px;
  font-size: 0.78rem;
  line-height: 1.5;
}

.admin-availability-calendar-error {
  border: 1px solid rgba(184, 93, 82, 0.2);
  background: rgba(184, 93, 82, 0.08);
  color: #8d463d;
}

.admin-availability-calendar-success {
  border: 1px solid rgba(79, 138, 102, 0.2);
  background: rgba(79, 138, 102, 0.08);
  color: #356f4b;
}

.admin-availability-calendar-loading {
  border: 1px solid var(--color-border);
  background: var(--color-white);
  color: var(--color-muted);
}

/* =========================
   LEGEND
   ========================= */

.admin-availability-legend {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
  margin: 16px 2px;
  color: var(--color-muted);
  font-size: 0.71rem;
}

.admin-availability-legend span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
}

.admin-availability-legend i {
  width: 8px;
  height: 8px;
  flex: 0 0 8px;
  border-radius: 999px;
  display: inline-block;
}

.admin-availability-legend i.is-available,
.admin-availability-day-state i.is-available {
  background: #4f8a66;
}

.admin-availability-legend i.is-booked,
.admin-availability-day-state i.is-booked {
  background: #b85d52;
}

.admin-availability-legend i.is-pending {
  background: var(--color-gold);
}

.admin-availability-legend i.is-empty {
  background: var(--color-border);
}

/* =========================
   MONTH VIEW
   ========================= */

.admin-availability-month-grid {
  display: grid;
  grid-template-columns:
    repeat(7, minmax(0, 1fr));
  overflow: hidden;
  border: 1px solid var(--color-border);
  border-radius: 18px;
  background: var(--color-border);
  gap: 1px;
}

.admin-availability-weekday {
  min-width: 0;
  padding: 10px 11px;
  background:
    rgba(31, 38, 56, 0.045);
  color: var(--color-muted);
  font-size: 0.66rem;
  font-weight: 850;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.admin-availability-day {
  position: relative;
  min-height: 118px;
  width: 100%;
  padding: 11px;
  border: 0;
  background: var(--color-white);
  color: var(--color-midnight);
  text-align: left;
  cursor: pointer;
  transition:
    background 160ms ease,
    box-shadow 160ms ease;
}

.admin-availability-day:hover {
  background:
    rgba(214, 166, 59, 0.055);
}

.admin-availability-day.is-selected {
  background:
    linear-gradient(
      180deg,
      rgba(214, 166, 59, 0.11),
      rgba(255, 255, 255, 0.98)
    );
  box-shadow:
    inset 0 0 0 2px var(--color-gold);
}

.admin-availability-day.is-outside {
  opacity: 0.38;
}

.admin-availability-day-number {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 28px;
  height: 28px;
  margin-bottom: 9px;
  border-radius: 50%;
  font-size: 0.76rem;
  font-weight: 850;
}

.admin-availability-day.is-selected
  .admin-availability-day-number {
  background: var(--color-gold);
  color: var(--color-midnight);
}

.admin-availability-day-state {
  display: flex;
  gap: 6px;
  min-height: 9px;
}

.admin-availability-day-state i {
  width: 7px;
  height: 7px;
  border-radius: 999px;
}

.admin-availability-day small {
  display: block;
  margin-top: 9px;
  color: var(--color-muted);
  font-size: 0.65rem;
  line-height: 1.35;
}

.admin-availability-day .is-booked-text {
  color: #8d463d;
  font-weight: 750;
}

/* =========================
   DAY VIEW
   ========================= */

.admin-availability-day-view {
  padding: 20px;
  border: 1px solid var(--color-border);
  border-radius: 18px;
  background: var(--color-white);
}

.admin-availability-day-view-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding-bottom: 15px;
  border-bottom: 1px solid var(--color-border);
}

.admin-availability-day-view-header h3 {
  margin: 3px 0 0;
  color: var(--color-midnight);
  font-size: 1rem;
}

.admin-availability-day-view-header small {
  display: block;
  margin-top: 5px;
  color: var(--color-muted);
  font-size: 0.68rem;
}

.admin-availability-secondary-button {
  padding: 0 13px;
  border: 1px solid var(--color-border);
  background: var(--color-white);
  color: var(--color-midnight);
  cursor: pointer;
}

.admin-availability-secondary-button:hover:not(:disabled) {
  border-color: var(--color-gold);
}

.admin-availability-day-summary {
  display: flex;
  gap: 9px;
  flex-wrap: wrap;
  margin: 16px 0 14px;
}

.admin-availability-day-summary span {
  padding: 7px 10px;
  border-radius: 999px;
  background: rgba(31, 38, 56, 0.045);
  color: var(--color-muted);
  font-size: 0.68rem;
  font-weight: 750;
}

/* =========================
   TIME GRID
   ========================= */

.admin-availability-time-grid {
  display: grid;
  grid-template-columns:
    repeat(4, minmax(0, 1fr));
  gap: 8px;
  max-height: 610px;
  overflow-y: auto;
  padding: 3px;
}

.admin-availability-time-cell {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: 62px;
  padding: 10px 11px;
  border: 1px solid var(--color-border);
  border-radius: 11px;
  background: var(--color-white);
  color: var(--color-midnight);
  text-align: left;
  cursor: pointer;
  transition:
    transform 140ms ease,
    box-shadow 140ms ease,
    border-color 140ms ease,
    background 140ms ease;
}

.admin-availability-time-cell span {
  font-size: 0.74rem;
  font-weight: 850;
}

.admin-availability-time-cell small {
  color: var(--color-muted);
  font-size: 0.61rem;
  font-weight: 700;
}

.admin-availability-time-cell:hover:not(:disabled) {
  transform: translateY(-1px);
  border-color: var(--color-gold);
  box-shadow:
    0 7px 16px rgba(23, 28, 45, 0.06);
}

.admin-availability-time-cell.is-available {
  border-color: rgba(79, 138, 102, 0.3);
  background:
    rgba(79, 138, 102, 0.08);
}

.admin-availability-time-cell.is-available small {
  color: #356f4b;
}

.admin-availability-time-cell.is-draft {
  border-color: var(--color-gold);
  box-shadow:
    inset 0 0 0 1px var(--color-gold);
}

.admin-availability-time-cell.is-booked {
  border-color: rgba(184, 93, 82, 0.25);
  background:
    rgba(184, 93, 82, 0.085);
  color: #8d463d;
  cursor: not-allowed;
}

.admin-availability-time-cell.is-booked small {
  color: #8d463d;
}

/* =========================
   BOOKING CARDS
   ========================= */

.admin-availability-booking-cards {
  display: grid;
  gap: 10px;
  margin-top: 18px;
}

.admin-availability-booked-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 14px 16px;
  border: 1px solid rgba(184, 93, 82, 0.2);
  border-left: 4px solid #b85d52;
  border-radius: 13px;
  background: rgba(184, 93, 82, 0.07);
}

.admin-availability-booked-card strong,
.admin-availability-booked-card span,
.admin-availability-booked-card small {
  display: block;
}

.admin-availability-booked-card strong {
  color: #8d463d;
  font-size: 0.64rem;
  letter-spacing: 0.1em;
}

.admin-availability-booked-card span {
  margin-top: 3px;
  color: var(--color-midnight);
  font-size: 0.78rem;
  font-weight: 800;
}

.admin-availability-booked-card small {
  margin-top: 4px;
  color: var(--color-muted);
  font-size: 0.67rem;
}

.admin-availability-booking-id {
  color: var(--color-muted) !important;
  font-size: 0.64rem !important;
  font-weight: 700 !important;
  white-space: nowrap;
}

/* =========================
   UNSAVED BAR
   ========================= */

.admin-availability-unsaved-bar {
  position: sticky;
  bottom: 16px;
  z-index: 8;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-top: 18px;
  padding: 12px 14px;
  border: 1px solid var(--color-gold);
  border-radius: 14px;
  background:
    rgba(255, 255, 255, 0.96);
  box-shadow:
    0 14px 32px rgba(23, 28, 45, 0.12);
  backdrop-filter: blur(9px);
  color: var(--color-midnight);
  font-size: 0.75rem;
  font-weight: 750;
}

.admin-availability-unsaved-bar button {
  min-height: 36px;
  padding: 0 13px;
  border: 0;
  border-radius: 9px;
  background: var(--color-midnight);
  color: var(--color-white);
  font: inherit;
  font-size: 0.7rem;
  font-weight: 800;
  cursor: pointer;
}

/* =========================
   EMPTY STATE
   ========================= */

.admin-availability-empty-day {
  display: grid;
  gap: 6px;
  padding: 24px;
  border: 1px solid var(--color-border);
  border-radius: 16px;
  background: rgba(31, 38, 56, 0.025);
}

.admin-availability-empty-day strong {
  color: var(--color-midnight);
}

.admin-availability-empty-day span {
  color: var(--color-muted);
  font-size: 0.76rem;
}

/* =========================
   RESPONSIVE
   ========================= */

@media (max-width: 1000px) {
  .admin-availability-calendar-header,
  .admin-availability-calendar-toolbar {
    align-items: flex-start;
    flex-direction: column;
  }

  .admin-availability-calendar-controls {
    width: 100%;
    justify-content: flex-start;
  }

  .admin-availability-calendar-controls select {
    flex: 1;
    min-width: 0;
  }

  .admin-availability-calendar-toolbar > * {
    width: 100%;
  }

  .admin-availability-view-toggle,
  .admin-availability-month-controls {
    justify-content: flex-start;
  }
}

@media (max-width: 900px) {
  .admin-availability-quick-guide {
    grid-template-columns: 1fr;
  }

  .admin-availability-time-grid {
    grid-template-columns:
      repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 680px) {
  .admin-availability-calendar {
    padding: 18px;
    border-radius: 18px;
  }

  .admin-availability-month-grid {
    overflow-x: auto;
    grid-template-columns:
      repeat(7, minmax(100px, 1fr));
  }

  .admin-availability-weekday,
  .admin-availability-day {
    min-width: 100px;
  }

  .admin-availability-day {
    min-height: 100px;
  }

  .admin-availability-day-view {
    padding: 15px;
  }

  .admin-availability-day-view-header {
    align-items: flex-start;
    flex-direction: column;
  }

  .admin-availability-time-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
    max-height: 520px;
  }

  .admin-availability-time-cell {
    min-height: 58px;
    flex-direction: column;
    align-items: flex-start;
  }

  .admin-availability-booked-card,
  .admin-availability-unsaved-bar {
    align-items: flex-start;
    flex-direction: column;
  }

  .admin-availability-booking-id {
    white-space: normal;
  }
}

@media (max-width: 420px) {
  .admin-availability-time-grid {
    grid-template-columns: 1fr;
  }

  .admin-availability-calendar-controls,
  .admin-availability-view-toggle,
  .admin-availability-month-controls {
    width: 100%;
  }

  .admin-availability-calendar-controls select {
    width: 100%;
  }

  .admin-availability-month-controls strong {
    min-width: 120px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .admin-availability-calendar * {
    scroll-behavior: auto;
    transition: none !important;
  }
}

