/* Hero emblem */
.about-hero-emblem {
  position: relative;
  min-height: 560px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.about-emblem-outer {
  position: relative;
  width: min(510px, 100%);
  aspect-ratio: 1;
  border: 1px solid rgba(231,195,108,.48);
  border-radius: 50%;
  display: grid;
  place-items: center;
  box-shadow:
    0 0 0 24px rgba(214,166,59,.025),
    0 0 0 56px rgba(214,166,59,.015),
    0 35px 90px rgba(0,0,0,.35);
