.about-emblem-outer::before,
.about-emblem-outer::after {
  content: "";
  position: absolute;
  border: 1px solid rgba(231,195,108,.15);
  border-radius: 50%;
}

.about-emblem-outer::before { inset: 34px; }
.about-emblem-outer::after { inset: 78px; }

.about-emblem-inner {
  width: 62%;
  aspect-ratio: 1;
  border: 1px solid rgba(231,195,108,.3);
  border-radius: 50%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: radial-gradient(circle, rgba(214,166,59,.11), rgba(7,24,42,.18) 65%);
