  line-height: 1.2;
}

.about-emblem-caption {
  margin-top: 14px;
  color: rgba(231,195,108,.55);
  font-size: .48rem;
  letter-spacing: .2em;
}

.about-floating-chip {
  position: absolute;
  z-index: 4;
  padding: 11px 16px;
  border: 1px solid rgba(231,195,108,.3);
  border-radius: 999px;
  color: #f4eddd;
  background: rgba(4,17,31,.74);
