/* ---------- Motion ---------- */
@keyframes zodiacStageFloat {
  0%, 100% { transform: translateY(0) rotateZ(0deg); }
  50% { transform: translateY(-7px) rotateZ(.25deg); }
}

@keyframes zodiacRotateSlow {
  from { transform: rotateZ(0deg) translateZ(-1px); }
  to { transform: rotateZ(360deg) translateZ(-1px); }
}

@keyframes zodiacRotateMain {
  from { transform: rotateZ(360deg); }
  to { transform: rotateZ(0deg); }
}

@keyframes zodiacRotateInner {
  from { transform: rotateZ(0deg); }
  to { transform: rotateZ(360deg); }
}

@keyframes orbitPlanetOne {
  from { transform: rotate(0deg) translateX(0); }
  50% { transform: rotate(180deg) translateX(8px); }
  to { transform: rotate(360deg) translateX(0); }
}

@keyframes orbitPlanetTwo {
  from { transform: rotate(0deg) translateX(0); }
  50% { transform: rotate(180deg) translateX(-6px); }
  to { transform: rotate(360deg) translateX(0); }
}

@keyframes planetDriftOne {
  0%,100% { transform: translate(0,0); opacity: .62; }
  50% { transform: translate(4px,-5px); opacity: 1; }
}

@keyframes planetDriftTwo {
  0%,100% { transform: translate(0,0); opacity: .48; }
  50% { transform: translate(-5px,3px); opacity: .92; }
}

@keyframes planetPulse {
  0%,100% { transform: scale(.75); opacity: .45; }
  50% { transform: scale(1.45); opacity: 1; }
}

@keyframes coreHalo {
  0%,100% { opacity: .45; transform: scale(.96); }
  50% { opacity: .9; transform: scale(1.04); }
}

@keyframes lightSweep {
  0%, 55% { transform: translate(-90px, -30px) rotate(38deg); opacity: 0; }
  65% { opacity: 1; }
  85%,100% { transform: translate(220px, 170px) rotate(38deg); opacity: 0; }
}

@keyframes heroStarPulse {
  0%,100% { opacity: .25; transform: scale(.7); }
  50% { opacity: .95; transform: scale(1.45); }
}

@keyframes liveDotPulse {
  0%,100% { transform: scale(.8); opacity: .55; }
  50% { transform: scale(1.25); opacity: 1; }
}

/* ---------- Responsive ---------- */
@media (max-width: 1200px) {
  .hero-visual-live { min-height: 610px; }
  .live-zodiac-stage { left: 0; width: 420px; height: 420px; top: 104px; }
  .live-zodiac-sign { transform: rotate(var(--zodiac-angle)) translateY(-163px) rotate(calc(var(--zodiac-angle) * -1)); }
  .hero-live-question { width: min(285px, 50%); }
}

@media (max-width: 950px) {
  .hero-visual-live { min-height: 650px; margin-top: 12px; }
  .live-zodiac-stage { left: 7%; top: 105px; width: 420px; height: 420px; }
  .hero-live-question { right: 3%; width: 280px; }
  .hero-live-options { left: 2%; bottom: 100px; }
  .hero-live-guidance { left: 20%; bottom: 4px; width: 48%; }
}

@media (max-width: 650px) {
  .hero-visual-live { min-height: 690px; }
  .live-zodiac-stage { left: 50%; top: 90px; width: 335px; height: 335px; transform: translateX(-50%); }
  .zodiac-instrument { transform: rotateX(9deg) rotateY(-8deg); }
  .live-zodiac-sign { width: 34px; height: 34px; margin: -17px; font-size: 1.15rem; transform: rotate(var(--zodiac-angle)) translateY(-132px) rotate(calc(var(--zodiac-angle) * -1)); }
  .zodiac-core { width: 100px; height: 100px; margin: -50px; }
  .zodiac-core-om { font-size: 1.85rem; }
  .zodiac-core strong { font-size: .43rem; }
  .zodiac-core small { font-size: .36rem; }
  .zodiac-orbit-path-one { width: 150px; height: 68px; margin: -34px -75px; }
  .zodiac-orbit-path-two { width: 125px; height: 54px; margin: -27px -62px; }
  .hero-live-question { top: 0; left: 50%; right: auto; transform: translateX(-50%); width: min(92%, 310px); }
  .hero-live-options { left: 2%; bottom: 110px; gap: 5px; }
  .hero-live-options button { min-width: 118px; font-size: .58rem; padding: 7px 9px; }
  .hero-live-guidance { left: 1%; bottom: 0; width: 48%; padding: 11px 10px; display: block; }
  .hero-live-guidance strong { font-size: .61rem; }
  .hero-live-guidance p { font-size: .52rem; }
  .hero-live-guidance .btn { margin-top: 7px; width: 100%; font-size: .55rem; }
}

@media (prefers-reduced-motion: reduce) {
  .live-zodiac-stage,
  .zodiac-rotor-slow,
  .zodiac-rotor-main,
  .zodiac-rotor-inner,
  .zodiac-orbit-planet,
  .zodiac-planet,
  .zodiac-core-halo,
  .zodiac-light-sweep::before,
  .celestial-star,
  .hero-live-dot {
    animation: none !important;
  }
}
