  right: 28px;
  bottom: 25px;
  display: grid;
  width: 44px;
  height: 44px;
  place-items: center;
  border: 1px solid rgba(231, 195, 108, 0.72);
  border-radius: 50%;
  color: #f3cf72;
  background: rgba(3, 12, 22, 0.68);
  font-size: 1.2rem;
}

.achievements-arrow {
  position: absolute;
  top: 50%;
  z-index: 5;
  display: grid;
  width: 56px;
  height: 56px;
  place-items: center;
  transform: translateY(-50%);
  border: 1px solid rgba(231, 195, 108, 0.7);
  border-radius: 50%;
  color: #f3cf72;
  background: rgba(3, 12, 22, 0.82);
  cursor: pointer;
  font-size: 2rem;
  line-height: 1;
  transition: transform 0.25s ease, background 0.25s ease;
}

.achievements-arrow:hover {
  transform: translateY(-50%) scale(1.06);
  background: rgba(214, 166, 59, 0.18);
}

.achievements-arrow-left {
  left: 20px;
}

.achievements-arrow-right {
  right: 20px;
}

.achievements-info {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 58px 46px;
  background:
    radial-gradient(circle at 90% 8%, rgba(214, 166, 59, 0.1), transparent 35%),
    rgba(3, 12, 22, 0.94);
}

.achievements-info-number {
  color: #e7c36c;
  font-family: var(--font-heading), Georgia, serif;
  font-size: 2.25rem;
  letter-spacing: 0.04em;
}

.achievements-info-number span {
  color: rgba(250, 247, 239, 0.72);
  font-size: 1rem;
}

.achievements-info-rule {
  width: 44px;
  height: 1px;
  margin: 20px 0 32px;
  background: #d6a63b;
}

.achievements-info-eyebrow {
  margin: 0 0 12px;
  color: #e7c36c;
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.16em;
}

.achievements-info h3 {
  margin: 0;
  color: #faf7ef;
  font-family: var(--font-heading), Georgia, serif;
  font-size: clamp(2rem, 3vw, 3.1rem);
  line-height: 1.14;
}

.achievements-info-detail {
  margin: 24px 0 0;
  color: rgba(250, 247, 239, 0.7);
  line-height: 1.75;
}

.achievements-info-view,
.achievements-footer button {
  width: fit-content;
  margin-top: 38px;
  padding: 14px 20px;
  border: 1px solid #d6a63b;
  border-radius: 10px;
  color: #f6d77d;
  background: transparent;
  cursor: pointer;
  font: inherit;
  transition: background 0.25s ease, transform 0.25s ease;
}

.achievements-info-view:hover,
.achievements-footer button:hover {
  transform: translateY(-2px);
  background: rgba(214, 166, 59, 0.1);
}

.achievements-carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 22px;
  margin-top: 25px;
}

.achievements-carousel-dots {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 11px;
  flex-wrap: wrap;
}

.achievements-carousel-dot {
  width: 11px;
  height: 11px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: rgba(250, 247, 239, 0.38);
  cursor: pointer;
  transition: transform 0.25s ease, background 0.25s ease;
}

.achievements-carousel-dot.is-active {
  transform: scale(1.3);
  background: #e7c36c;
}

.achievements-carousel-status {
  color: #e7c36c;
  font-family: var(--font-heading), Georgia, serif;
  font-size: 0.95rem;
  letter-spacing: 0.08em;
}

.achievements-thumbnails {
  display: grid;
  grid-template-columns: repeat(10, minmax(0, 1fr));
  gap: 8px;
  margin-top: 25px;
}

.achievements-thumbnail {
  position: relative;
  aspect-ratio: 4 / 3;
  min-width: 0;
  padding: 0;
  overflow: hidden;
  border: 1px solid rgba(231, 195, 108, 0.32);
  border-radius: 8px;
  background: #030c16;
  cursor: pointer;
  opacity: 0.68;
  transition: opacity 0.25s ease, transform 0.25s ease, border-color 0.25s ease;
}

.achievements-thumbnail:hover {
  opacity: 0.95;
  transform: translateY(-2px);
}

.achievements-thumbnail.is-active {
  opacity: 1;
  border-color: #e7c36c;
  box-shadow: 0 0 0 2px rgba(231, 195, 108, 0.18);
}

.achievements-thumbnail-image {
  object-fit: cover;
}

.achievements-thumbnail > span {
  position: absolute;
  left: 5px;
  bottom: 4px;
  padding: 1px 4px;
  border-radius: 3px;
  color: #fff;
  background: rgba(0, 0, 0, 0.65);
  font-size: 0.7rem;
  line-height: 1.2;
}

.achievements-gallery-hint {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 9px;
  margin-top: 20px;
  color: rgba(250, 247, 239, 0.62);
  font-size: 0.82rem;
}

.achievements-gallery-hint span {
  color: #e7c36c;
  font-size: 1.25rem;
}

.achievements-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 25px;
  margin-top: 28px;
  padding: 20px 26px;
  border: 1px solid rgba(214, 166, 59, 0.34);
  border-radius: 12px;
  background: rgba(12, 16, 21, 0.55);
}

.achievements-footer > span {
  color: #e7c36c;
  font-size: 0.72rem;
  letter-spacing: 0.16em;
}

.achievements-footer button {
  margin-top: 0;
}

/* Lightbox */
.achievement-lightbox {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
  padding: 35px;
  background: rgba(1, 7, 14, 0.96);
  backdrop-filter: blur(10px);
}

.achievement-lightbox-image {
  position: relative;
  width: min(1100px, 92vw);
  height: min(76vh, 780px);
}

.achievement-image {
  object-fit: contain;
}

.achievement-lightbox-caption {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.achievement-lightbox-caption span {
  color: #e7c36c;
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.16em;
}

.achievement-lightbox-caption strong {
  margin-top: 5px;
  color: #faf7ef;
  font-family: var(--font-heading), Georgia, serif;
  font-size: 1.35rem;
}

.achievement-lightbox-caption small {
  margin-top: 5px;
  color: rgba(250, 247, 239, 0.65);
}

.achievement-lightbox-close {
  position: absolute;
  top: 22px;
  right: 25px;
  z-index: 2;
  width: 46px;
  height: 46px;
  border: 1px solid rgba(231, 195, 108, 0.6);
  border-radius: 50%;
  color: #f3cf72;
  background: rgba(3, 12, 22, 0.8);
  cursor: pointer;
  font-size: 1.8rem;
  line-height: 1;
}

@media (max-width: 900px) {
  .achievements-intro {
    grid-template-columns: 1fr;
    gap: 22px;
  }

  .achievements-showcase {
    grid-template-columns: 1fr;
  }

  .achievements-main-card,
  .achievements-main-image {
    min-height: 520px;
  }

  .achievements-info {
    padding: 42px 32px;
  }

  .achievements-thumbnails {
    grid-template-columns: repeat(5, minmax(0, 1fr));
  }
}

@media (max-width: 600px) {
  .achievements-section {
    padding: 80px 0 65px;
  }

  .achievements-shell {
    width: min(100% - 28px, 1180px);
  }

  .achievements-title {
    font-size: clamp(2.4rem, 13vw, 3.5rem);
  }

  .achievements-showcase {
    border-radius: 14px;
  }

  .achievements-main-card,
  .achievements-main-image {
    min-height: 430px;
  }

  .achievements-info {
    padding: 32px 24px;
  }

  .achievements-info h3 {
    font-size: 2rem;
  }

  .achievements-arrow {
    width: 46px;
    height: 46px;
  }

  .achievements-arrow-left {
    left: 12px;
  }

  .achievements-arrow-right {
    right: 12px;
  }

  .achievements-thumbnails {
    grid-template-columns: repeat(5, minmax(0, 1fr));
    gap: 5px;
  }

  .achievements-gallery-hint {
    font-size: 0.75rem;
  }

  .achievements-footer {
    flex-direction: column;
    align-items: stretch;
    text-align: center;
  }

  .achievements-footer button {
    width: 100%;
  }

  .achievement-lightbox {
    padding: 18px;
  }

  .achievement-lightbox-image {
    height: 70vh;
  }
}

@media (prefers-reduced-motion: reduce) {
  .achievements-main-photo,
  .achievements-arrow,
  .achievements-thumbnail,
  .achievements-carousel-dot,
  .achievements-info-view,
  .achievements-footer button {
    transition: none;
  }
}


/* =========================================================
   HOMEPAGE SERVICES — PREMIUM SERVICE CARDS
   UI-only enhancement. Booking/API data and routes unchanged.
   ========================================================= */

.service-home-card {
  min-height: 390px;
