    radial-gradient(circle at 100% 0%, rgba(214, 166, 59, 0.075), transparent 34%),
    var(--color-white);
  border-radius: 24px;
}

.service-home-card::after {
  content: "✦";
  position: absolute;
  right: 22px;
  bottom: 58px;
  color: rgba(214, 166, 59, 0.055);
  font-family: Georgia, serif;
  font-size: 7rem;
  line-height: 1;
  pointer-events: none;
}

.service-home-card:hover {
  transform: translateY(-8px);
  border-color: rgba(214, 166, 59, 0.62);
  box-shadow: 0 24px 52px rgba(7, 24, 42, 0.13);
}

.service-home-top {
  margin-bottom: 25px;
}

.service-home-symbol {
  width: 48px;
  height: 48px;
  background: linear-gradient(145deg, rgba(231, 195, 108, 0.18), rgba(214, 166, 59, 0.06));
  border-color: rgba(214, 166, 59, 0.5);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.45);
