}

.service-home-number {
  color: var(--color-gold-dark);
  opacity: 0.72;
}

.service-home-category {
  margin-bottom: 10px;
  padding: 5px 9px;
  border: 1px solid rgba(214, 166, 59, 0.22);
  border-radius: 999px;
  background: rgba(214, 166, 59, 0.055);
  font-size: 0.64rem;
  letter-spacing: 0.13em;
}

.service-home-card h3 {
  max-width: 90%;
  margin-bottom: 12px;
  font-size: clamp(1.35rem, 1.7vw, 1.6rem);
}

.service-home-description {
  position: relative;
  z-index: 1;
  min-height: 70px;
  margin: 0;
  color: var(--color-muted);
