}

.service-home-price {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.service-home-price-label {
  color: var(--color-muted);
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.1em;
