}

.service-home-bottom .service-home-link {
  width: auto;
  min-width: 126px;
  margin-top: 0;
  padding: 11px 13px;
  border: 1px solid rgba(214, 166, 59, 0.42);
  border-radius: 999px;
  background: rgba(214, 166, 59, 0.08);
  color: var(--color-midnight);
  font-size: 0.76rem;
  text-align: center;
}

.service-home-bottom .service-home-link > span:first-child {
  color: inherit;
  font-size: inherit;
  transform: none;
}

.service-home-bottom .service-home-link > span:last-child {
  color: var(--color-gold-dark);
  font-size: 0.95rem;
}

.service-home-bottom .service-home-link:hover {
  background: linear-gradient(135deg, var(--color-gold-light), var(--color-gold));
