    min-height: 360px;
    padding: 26px 23px 22px;
  }

  .service-home-description {
    min-height: 0;
  }
}

@media (max-width: 480px) {
  .service-home-bottom {
    align-items: stretch;
    flex-direction: column;
    gap: 14px;
  }

  .service-home-bottom .service-home-link {
    width: 100%;
  }
}
/* ============================================
   SHOP — COMING SOON
   Visible-only launch placeholder.
   No shop/cart/product functionality.
   ============================================ */

.shop-coming-soon-page {
  background: var(--color-ivory);
}

.shop-coming-soon-hero {
  position: relative;
  min-height: 690px;
  padding: 150px 0 110px;
  overflow: hidden;
  display: flex;
  align-items: center;
  text-align: center;
  color: var(--color-white);
  background:
    radial-gradient(circle at 50% 42%, rgba(214, 166, 59, 0.13), transparent 28%),
    radial-gradient(circle at 18% 20%, rgba(35, 73, 108, 0.55), transparent 30%),
    linear-gradient(135deg, #04111f 0%, var(--color-midnight) 52%, #0c2742 100%);
}

.shop-coming-soon-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image:
    radial-gradient(circle at 20% 30%, rgba(255,255,255,.55) 0 1px, transparent 1.5px),
    radial-gradient(circle at 75% 22%, rgba(255,255,255,.45) 0 1px, transparent 1.5px),
    radial-gradient(circle at 88% 68%, rgba(255,255,255,.4) 0 1px, transparent 1.5px),
    radial-gradient(circle at 12% 78%, rgba(255,255,255,.35) 0 1px, transparent 1.5px);
  background-size: 230px 190px, 310px 250px, 270px 220px, 350px 280px;
  opacity: .55;
}

.shop-stars {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: .32;
  background-image: radial-gradient(circle, rgba(231,195,108,.8) 0 1px, transparent 1.5px);
  background-size: 170px 170px;
}

.shop-orbit {
  position: absolute;
  border: 1px solid rgba(214, 166, 59, .14);
  border-radius: 50%;
  pointer-events: none;
}

.shop-orbit-one {
  width: 680px;
  height: 680px;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%) rotate(18deg);
}

.shop-orbit-two {
  width: 920px;
  height: 420px;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%) rotate(-20deg);
}

.shop-hero-content {
  position: relative;
  z-index: 1;
  max-width: 900px;
}

.shop-eyebrow,
.shop-final-eyebrow {
  margin: 0 0 20px;
  color: var(--color-gold-light);
  font-size: .76rem;
  font-weight: 700;
  letter-spacing: .2em;
  text-transform: uppercase;
}

.shop-emblem {
  width: 74px;
  height: 74px;
  margin: 0 auto 24px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(231, 195, 108, .6);
  border-radius: 50%;
  color: var(--color-gold-light);
  font-family: Georgia, serif;
  font-size: 2rem;
  box-shadow: 0 0 55px rgba(214, 166, 59, .12);
}

.shop-hero-content h1 {
  margin: 0;
  color: var(--color-white);
  font-family: var(--font-heading), Georgia, serif;
