   ============================================ */

.services-page {
  overflow: hidden;
  background: var(--color-ivory);
}

.services-page-hero {
  position: relative;
  min-height: 680px;
  display: flex;
  align-items: center;
  overflow: hidden;
  padding: 150px 0 110px;
  background:
    radial-gradient(circle at 78% 28%, rgba(214,166,59,.13), transparent 25%),
    radial-gradient(circle at 12% 85%, rgba(31,79,117,.34), transparent 30%),
    linear-gradient(135deg, #04111f 0%, var(--color-midnight) 55%, #0d2945 100%);
  color: var(--color-white);
}

.services-page-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(255,255,255,.035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,.035) 1px, transparent 1px);
  background-size: 58px 58px;
  mask-image: linear-gradient(to bottom, rgba(0,0,0,.8), transparent 88%);
  pointer-events: none;
}

.services-page-hero-orbit {
  position: absolute;
  border: 1px solid rgba(214,166,59,.13);
  border-radius: 50%;
  pointer-events: none;
}

.services-page-hero-orbit-one {
  width: 620px;
  height: 620px;
  right: -250px;
  top: -180px;
}

.services-page-hero-orbit-two {
  width: 390px;
  height: 390px;
  left: -250px;
  bottom: -230px;
}

.services-page-hero-inner {
  position: relative;
  z-index: 1;
  text-align: center;
}

.services-page-eyebrow {
  color: var(--color-gold-light);
}

.services-page-title {
  max-width: 980px;
  margin: 16px auto 0;
  color: #fff;
  font-family: var(--font-heading), Georgia, serif;
  font-size: clamp(3rem, 6vw, 5.8rem);
  font-weight: 500;
  line-height: 1.02;
  letter-spacing: -.045em;
}

.services-page-title span {
  color: var(--color-gold-light);
}

.services-page-lead {
  max-width: 760px;
  margin: 28px auto 0;
  color: #d7e0e8;
  font-size: 1.08rem;
  line-height: 1.9;
}

.services-page-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  flex-wrap: wrap;
  margin-top: 38px;
}

.services-page-hero-link {
  color: #fff;
  font-weight: 600;
  transition: color 180ms ease, transform 180ms ease;
}

.services-page-hero-link:hover {
  color: var(--color-gold-light);
