/* Value */
.services-value-section {
  background: #fff;
}

.services-value-grid {
  display: grid;
  grid-template-columns: minmax(0, .9fr) minmax(0, 1.1fr);
  gap: 90px;
  align-items: start;
}

.services-value-heading .section-heading {
  margin: 10px 0 0;
}

.services-value-copy > p {
  max-width: 650px;
  margin: 0;
  color: var(--color-muted);
  font-size: 1.05rem;
  line-height: 1.85;
}

.services-value-points {
  display: grid;
  gap: 0;
  margin-top: 34px;
  border-top: 1px solid var(--color-border);
}

.services-value-points > div {
  display: grid;
  grid-template-columns: 48px 1fr;
  gap: 12px 18px;
  padding: 22px 0;
  border-bottom: 1px solid var(--color-border);
}

.services-value-points span {
  grid-row: span 2;
  color: var(--color-gold-dark);
  font-size: .74rem;
  font-weight: 800;
  letter-spacing: .1em;
}

.services-value-points strong {
  color: var(--color-midnight);
  font-family: var(--font-heading), Georgia, serif;
  font-size: 1.18rem;
  font-weight: 600;
}

.services-value-points p {
  margin: 0;
  color: var(--color-muted);
  font-size: .92rem;
  line-height: 1.65;
}

/* Shared section intro */
.services-section-intro {
  max-width: 760px;
  margin: 0 auto;
  text-align: center;
}

.services-section-intro .section-heading {
  margin: 9px 0 15px;
}

.services-section-intro > p {
  max-width: 700px;
  margin: 0 auto;
  color: var(--color-muted);
  line-height: 1.8;
}

/* Find guidance */
.services-guidance-section {
  background:
    radial-gradient(circle at 50% 0, rgba(214,166,59,.07), transparent 35%),
    var(--color-ivory);
}

.guidance-grid {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 18px;
  margin-top: 54px;
}

.guidance-card {
  grid-column: span 2;
