/* =========================================================
   ADMIN PORTAL — GLOBAL FORM FIELD SYSTEM
   ---------------------------------------------------------
   Final field-styling layer for admin pages.
   Scoped to .admin-shell so public website forms are untouched.
   ========================================================= */

/* =========================
   FIELD WRAPPERS
   ========================= */

.admin-shell label {
  color: var(--color-midnight);
}

.admin-shell label > span,
.admin-shell .admin-field-label,
.admin-shell .admin-form-label {
  display: block;
  margin-bottom: 7px;
  color: var(--color-midnight);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  line-height: 1.35;
}


/* =========================
   TEXT / EMAIL / PASSWORD /
   NUMBER / TEL / DATE / TIME
   ========================= */

.admin-shell input:not([type="checkbox"]):not([type="radio"]),
.admin-shell textarea,
.admin-shell select {
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  min-height: 46px;

  padding: 11px 13px;

  border: 1px solid var(--color-border);
  border-radius: 10px;

  outline: none;

  background: var(--color-white);
  color: var(--color-midnight);

  font: inherit;
  font-size: 0.86rem;
  line-height: 1.35;

  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.8);

  transition:
    border-color 180ms ease,
    background-color 180ms ease,
    box-shadow 180ms ease,
    color 180ms ease,
    transform 180ms ease;
}


/* =========================
   TEXTAREA
   ========================= */

.admin-shell textarea {
  min-height: 110px;
  resize: vertical;
  padding: 12px 13px;
}


/* =========================
   SELECT
   ========================= */

.admin-shell select {
  appearance: auto;
  cursor: pointer;
  padding-right: 36px;
}


/* =========================
   PLACEHOLDERS
   ========================= */

.admin-shell input::placeholder,
.admin-shell textarea::placeholder {
  color: #a9a298;
  opacity: 1;
}


/* =========================
   HOVER
   ========================= */

.admin-shell
  input:not([type="checkbox"]):not([type="radio"]):hover:not(:disabled):not([readonly]),
.admin-shell
  textarea:hover:not(:disabled):not([readonly]),
.admin-shell
  select:hover:not(:disabled) {
  border-color: rgba(214, 166, 59, 0.52);
}


/* =========================
   FOCUS
   ========================= */

.admin-shell
  input:not([type="checkbox"]):not([type="radio"]):focus,
.admin-shell
  textarea:focus,
.admin-shell
  select:focus {
  border-color: var(--color-gold);

  background: #fffdfa;

  box-shadow:
    0 0 0 3px rgba(214, 166, 59, 0.12),
    0 5px 16px rgba(7, 24, 42, 0.045);
}


/* =========================
   FOCUS VISIBLE
   ========================= */

.admin-shell
  input:not([type="checkbox"]):not([type="radio"]):focus-visible,
.admin-shell
  textarea:focus-visible,
.admin-shell
  select:focus-visible {
  border-color: var(--color-gold);

  box-shadow:
    0 0 0 3px rgba(214, 166, 59, 0.14),
    0 5px 16px rgba(7, 24, 42, 0.05);
}


/* =========================
   DISABLED
   ========================= */

.admin-shell
  input:not([type="checkbox"]):not([type="radio"]):disabled,
.admin-shell
  textarea:disabled,
.admin-shell
  select:disabled {
  cursor: not-allowed;

  background: #f4f2ee;
  border-color: #dedad3;

  color: #8e8a84;

  opacity: 0.8;

  box-shadow: none;
}


/* =========================
   READONLY
   ========================= */

.admin-shell
  input:not([type="checkbox"]):not([type="radio"])[readonly],
.admin-shell
  textarea[readonly] {
  background: #f8f6f2;
  color: #5f5a53;
}


/* =========================
   AUTOFILL
   ========================= */

.admin-shell
  input:-webkit-autofill,
.admin-shell
  input:-webkit-autofill:hover,
.admin-shell
  input:-webkit-autofill:focus {
  -webkit-text-fill-color: var(--color-midnight);

  box-shadow:
    0 0 0 1000px #fffdfa inset,
    0 0 0 3px rgba(214, 166, 59, 0.08);

  transition:
    background-color 9999s ease-in-out 0s;
}


/* =========================
   INVALID FIELDS
   ========================= */

.admin-shell
  input:not([type="checkbox"]):not([type="radio"]).is-invalid,
.admin-shell
  textarea.is-invalid,
.admin-shell
  select.is-invalid,
.admin-shell
  input:not([type="checkbox"]):not([type="radio"])[aria-invalid="true"],
.admin-shell
  textarea[aria-invalid="true"],
.admin-shell
  select[aria-invalid="true"] {
  border-color: #c84a43;

  background: #fffafa;

  box-shadow:
    0 0 0 3px rgba(200, 74, 67, 0.08);
}


/* =========================
   VALID FIELDS
   ========================= */

.admin-shell
  input:not([type="checkbox"]):not([type="radio"]).is-valid,
.admin-shell
  textarea.is-valid,
.admin-shell
  select.is-valid,
.admin-shell
  input:not([type="checkbox"]):not([type="radio"])[aria-invalid="false"],
.admin-shell
  textarea[aria-invalid="false"],
.admin-shell
  select[aria-invalid="false"] {
  border-color: #6b9e7b;
}


/* =========================
   FIELD HELP TEXT
   ========================= */

.admin-shell .admin-field-help,
.admin-shell .admin-form-help,
.admin-shell .field-help {
  display: block;

  margin-top: 6px;

  color: var(--color-muted);

  font-size: 0.72rem;
  line-height: 1.55;
}


/* =========================
   FIELD ERROR TEXT
   ========================= */

.admin-shell .admin-field-error,
.admin-shell .admin-form-error,
.admin-shell .field-error {
  display: block;

  margin-top: 6px;

  color: #b42318;

  font-size: 0.72rem;
  font-weight: 600;
  line-height: 1.5;
}


/* =========================
   REQUIRED MARKER
   ========================= */

.admin-shell .required,
.admin-shell .admin-required {
  color: #b42318;
}


/* =========================
   CHECKBOX / RADIO
   ========================= */

.admin-shell
  input[type="checkbox"],
.admin-shell
  input[type="radio"] {
  width: 16px;
  height: 16px;

  margin: 0;

  accent-color: var(--color-gold);

  cursor: pointer;
}

.admin-shell
  input[type="checkbox"]:disabled,
.admin-shell
  input[type="radio"]:disabled {
  cursor: not-allowed;
}


/* =========================
   CHECKBOX / RADIO LABEL ROW
   ========================= */

.admin-shell
  label:has(input[type="checkbox"]),
.admin-shell
  label:has(input[type="radio"]) {
  display: flex;
  align-items: center;

  gap: 9px;

  cursor: pointer;
}

.admin-shell
  label:has(input[type="checkbox"]:disabled),
.admin-shell
  label:has(input[type="radio"]:disabled) {
  cursor: not-allowed;
}


/* =========================
   ADMIN SEARCH FIELDS
   ========================= */

.admin-shell
  .admin-search-input,
.admin-shell
  .admin-consultants-search,
.admin-shell
  input[type="search"] {
  min-height: 44px;
  border-radius: 11px;
}


/* =========================
   ADMIN SETTINGS FIELDS
   ========================= */

.admin-shell
  .admin-settings-card
  input:not([type="checkbox"]):not([type="radio"]),
.admin-shell
  .admin-settings-card
  textarea,
.admin-shell
  .admin-settings-card
  select {
  min-height: 48px;
  border-radius: 11px;
}


/* =========================
   ADMIN CONSULTANT FIELDS
   ========================= */

.admin-shell
  .admin-consultant-form-card
  input:not([type="checkbox"]):not([type="radio"]),
.admin-shell
  .admin-consultant-form-card
  textarea,
.admin-shell
  .admin-consultant-form-card
  select {
  min-height: 46px;
  border-radius: 10px;
}


/* =========================
   CONSULTANT AVAILABILITY
   ========================= */

.admin-shell
  .admin-consultant-availability-add
  input,
.admin-shell
  .admin-consultant-time-add
  input,
.admin-shell
  .admin-consultant-availability-add
  select,
.admin-shell
