}

@keyframes feedbackFilterLine {
from {
width: 4px;
opacity: 0;
}

to {
width: 14px;
opacity: 1;
}
}

/* ---------- Search ---------- */

.admin-feedback-page .admin-search-input {
min-height: 42px;
