opacity: 0;
transform: translateY(25px);
}

to {
opacity: 1;
transform: translateY(0);
}
}

@media (prefers-reduced-motion: reduce) {
.queries-page,
.queries-refresh,
.queries-table tbody tr,
.query-overlay,
.query-panel,
.query-panel-close,
.queries-page-button,
.query-reply-button {
animation: none !important;
transition: none !important;
}
}
/* =========================================================
   ADMIN — CUSTOMER FEEDBACK
   Premium light / ivory / navy / gold moderation interface
   ========================================================= */

.admin-feedback-page {
  width: 100%;
  max-width: 1500px;
  margin: 0 auto;
  animation: feedbackPageEnter 420ms ease both;
}

/* ---------- Header ---------- */

.admin-feedback-page .admin-page-header,
.feedback-page-header {
  margin-bottom: 26px;
}

.feedback-page-title {
  color: var(--color-midnight, #07182a);
  font-family: inherit;
}

.feedback-page-description {
  color: var(--color-muted, #6c747b);
}

/* ---------- Toolbar ---------- */

.feedback-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 20px;
}

.feedback-filters {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.feedback-filter-button {
  appearance: none;
  border: 1px solid var(--color-border, #e4dac6);
  background: rgba(255, 255, 255, 0.86);
  color: var(--color-muted, #6c747b);
  min-height: 40px;
  padding: 0 15px;
  border-radius: 999px;
  font: inherit;
  font-size: 0.78rem;
  font-weight: 750;
  letter-spacing: 0.02em;
  cursor: pointer;
  transition:
    color 180ms ease,
    background 180ms ease,
    border-color 180ms ease,
    transform 180ms ease,
    box-shadow 180ms ease;
}

.feedback-filter-button:hover {
  color: var(--color-midnight, #07182a);
  border-color: rgba(214, 166, 59, 0.5);
  transform: translateY(-1px);
}

.feedback-filter-button.active {
  color: #fff;
  background: var(--color-midnight, #07182a);
  border-color: var(--color-midnight, #07182a);
  box-shadow: 0 8px 20px rgba(7, 24, 42, 0.12);
}

.feedback-search {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: min(100%, 340px);
}

.feedback-search .admin-search-input {
  flex: 1;
}

/* ---------- Main table/card ---------- */

.feedback-table-card {
  overflow: hidden;
  background: rgba(255, 255, 255, 0.94);
  border: 1px solid var(--color-border, #e4dac6);
  border-radius: 20px;
  box-shadow:
    0 16px 45px rgba(7, 24, 42, 0.07),
    0 2px 8px rgba(7, 24, 42, 0.035);
}

.feedback-table-wrapper {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.feedback-table {
  width: 100%;
  min-width: 900px;
  border-collapse: collapse;
}

.feedback-table th {
  padding: 14px 18px;
  text-align: left;
  color: #7a766e;
  background: #faf7ef;
  border-bottom: 1px solid var(--color-border, #e4dac6);
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  white-space: nowrap;
}

.feedback-table td {
  padding: 17px 18px;
  color: var(--color-midnight, #07182a);
  border-bottom: 1px solid rgba(228, 218, 198, 0.72);
  vertical-align: middle;
  font-size: 0.82rem;
}

.feedback-table tbody tr {
  transition:
    background 180ms ease,
    transform 180ms ease;
}

.feedback-table tbody tr:hover {
  background: rgba(250, 247, 239, 0.72);
}

.feedback-table tbody tr:last-child td {
  border-bottom: 0;
}

/* ---------- Customer ---------- */

.feedback-customer {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 180px;
}

.feedback-customer-avatar {
  width: 36px;
  height: 36px;
  flex: 0 0 36px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: var(--color-midnight, #07182a);
  background:
    linear-gradient(
      145deg,
      rgba(231, 195, 108, 0.42),
      rgba(214, 166, 59, 0.14)
    );
  border: 1px solid rgba(214, 166, 59, 0.35);
  font-size: 0.76rem;
  font-weight: 850;
}

.feedback-customer-name {
  display: block;
  color: var(--color-midnight, #07182a);
  font-weight: 750;
  line-height: 1.25;
}

.feedback-customer-email {
  display: block;
  margin-top: 3px;
  color: #7b7f82;
  font-size: 0.7rem;
  line-height: 1.3;
}

/* ---------- Rating ---------- */

.feedback-rating {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  white-space: nowrap;
}

.feedback-rating-star {
  color: var(--color-gold, #d6a63b);
  font-size: 0.9rem;
}

.feedback-rating-number {
  margin-left: 6px;
  color: var(--color-midnight, #07182a);
  font-size: 0.75rem;
  font-weight: 800;
}

/* ---------- Message preview ---------- */

.feedback-message-preview {
  display: block;
  max-width: 330px;
  overflow: hidden;
  color: #626a70;
  line-height: 1.55;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ---------- Service / verified ---------- */

.feedback-service {
  color: var(--color-midnight, #07182a);
  font-weight: 650;
}

.feedback-verified {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin-top: 5px;
  color: #8a6519;
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

/* ---------- Status ---------- */

.feedback-status {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 0 10px;
  border-radius: 999px;
  font-size: 0.65rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  white-space: nowrap;
}

.feedback-status-pending {
  color: #85631a;
  background: rgba(214, 166, 59, 0.13);
  border: 1px solid rgba(214, 166, 59, 0.25);
}

.feedback-status-approved {
  color: #286347;
  background: rgba(65, 145, 101, 0.1);
  border: 1px solid rgba(65, 145, 101, 0.2);
}

.feedback-status-rejected {
  color: #8b3d3d;
  background: rgba(180, 77, 77, 0.08);
  border: 1px solid rgba(180, 77, 77, 0.18);
}

/* ---------- Row action ---------- */

.feedback-view-button {
  appearance: none;
  border: 1px solid var(--color-border, #e4dac6);
  background: #fff;
  color: var(--color-midnight, #07182a);
  min-height: 34px;
  padding: 0 12px;
  border-radius: 9px;
  font: inherit;
  font-size: 0.7rem;
  font-weight: 800;
  cursor: pointer;
  transition:
    background 180ms ease,
    color 180ms ease,
    border-color 180ms ease,
    transform 180ms ease;
}

.feedback-view-button:hover {
  color: #fff;
  background: var(--color-midnight, #07182a);
  border-color: var(--color-midnight, #07182a);
  transform: translateY(-1px);
}

/* ---------- Empty / loading ---------- */

.feedback-empty {
  padding: 72px 24px;
  text-align: center;
}

.feedback-empty-title {
  margin: 0;
  color: var(--color-midnight, #07182a);
  font-size: 1.1rem;
  font-weight: 800;
}

.feedback-empty-text {
  max-width: 420px;
  margin: 8px auto 0;
  color: #7a7f83;
  font-size: 0.82rem;
  line-height: 1.65;
}

.feedback-loading {
  padding: 60px 20px;
  text-align: center;
  color: #777d82;
  font-size: 0.8rem;
}

/* ---------- Pagination ---------- */

.feedback-pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 18px;
  border-top: 1px solid var(--color-border, #e4dac6);
  background: #fffdf8;
}

.feedback-pagination-info {
  color: #7b8084;
  font-size: 0.72rem;
}

.feedback-pagination-controls {
  display: flex;
  align-items: center;
  gap: 6px;
}

.feedback-page-button {
  appearance: none;
  min-width: 34px;
  height: 34px;
  padding: 0 9px;
  border: 1px solid var(--color-border, #e4dac6);
  border-radius: 8px;
  background: #fff;
  color: var(--color-midnight, #07182a);
  font: inherit;
  font-size: 0.7rem;
  font-weight: 800;
  cursor: pointer;
  transition: all 180ms ease;
}

.feedback-page-button:hover:not(:disabled) {
  border-color: var(--color-gold, #d6a63b);
  transform: translateY(-1px);
}

.feedback-page-button.active {
  color: #fff;
  background: var(--color-midnight, #07182a);
  border-color: var(--color-midnight, #07182a);
}

.feedback-page-button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* =========================================================
   FEEDBACK REVIEW DRAWER / MODAL
   ========================================================= */

.feedback-overlay {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: flex;
  justify-content: flex-end;
  background: rgba(7, 24, 42, 0.42);
  backdrop-filter: blur(7px);
  -webkit-backdrop-filter: blur(7px);
  animation: feedbackOverlayEnter 220ms ease both;
}

.feedback-modal,
.feedback-panel {
  width: min(620px, 100%);
  height: 100%;
  overflow-y: auto;
  background:
    linear-gradient(
      180deg,
      #fffdf9 0%,
      #faf7ef 100%
    );
  border-left: 1px solid rgba(214, 166, 59, 0.24);
  box-shadow: -22px 0 65px rgba(7, 24, 42, 0.16);
  animation: feedbackDrawerEnter 360ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.feedback-modal-header,
.feedback-panel-header {
  position: sticky;
  top: 0;
  z-index: 2;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  padding: 25px 28px 20px;
  background: rgba(255, 253, 249, 0.94);
  border-bottom: 1px solid var(--color-border, #e4dac6);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

.feedback-modal-kicker {
  display: block;
  margin-bottom: 7px;
  color: var(--color-gold-dark, #ad7c1d);
  font-size: 0.63rem;
  font-weight: 850;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.feedback-modal-title {
  margin: 0;
  color: var(--color-midnight, #07182a);
  font-size: 1.35rem;
  line-height: 1.2;
  font-weight: 850;
}

.feedback-modal-close {
  appearance: none;
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: grid;
  place-items: center;
  border: 1px solid var(--color-border, #e4dac6);
  border-radius: 10px;
  background: #fff;
  color: var(--color-midnight, #07182a);
  font-size: 1.1rem;
  cursor: pointer;
  transition: all 180ms ease;
}

.feedback-modal-close:hover {
  color: #fff;
  background: var(--color-midnight, #07182a);
  border-color: var(--color-midnight, #07182a);
  transform: rotate(3deg);
}

.feedback-modal-body,
.feedback-panel-body {
  display: flex;
  flex-direction: column;
  gap: 22px;
  padding: 26px 28px 34px;
}

/* ---------- Detail identity ---------- */

.feedback-detail-identity {
  padding: 20px;
  border-radius: 16px;
  background: #fff;
  border: 1px solid var(--color-border, #e4dac6);
  box-shadow: 0 8px 24px rgba(7, 24, 42, 0.045);
}

.feedback-detail-name {
  margin: 0;
  color: var(--color-midnight, #07182a);
  font-size: 1.05rem;
  font-weight: 850;
}

.feedback-detail-email {
  margin: 4px 0 0;
  color: #747b80;
  font-size: 0.75rem;
}

.feedback-detail-id {
  display: inline-block;
  margin-top: 12px;
  color: var(--color-gold-dark, #ad7c1d);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.67rem;
  font-weight: 700;
}

/* ---------- Meta cards ---------- */

.feedback-meta-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.feedback-meta-card {
  min-width: 0;
  padding: 15px 16px;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.84);
  border: 1px solid var(--color-border, #e4dac6);
}

.feedback-meta-label {
  display: block;
  margin-bottom: 6px;
  color: #7b807f;
  font-size: 0.62rem;
  font-weight: 850;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.feedback-meta-value {
  display: block;
  color: var(--color-midnight, #07182a);
  font-size: 0.78rem;
  font-weight: 700;
  overflow-wrap: anywhere;
}

/* ---------- Full feedback ---------- */

.feedback-message-card {
  padding: 20px;
  border-radius: 16px;
  background: #fff;
  border: 1px solid var(--color-border, #e4dac6);
}

.feedback-message-card-label {
  display: block;
  margin-bottom: 10px;
  color: var(--color-gold-dark, #ad7c1d);
  font-size: 0.64rem;
  font-weight: 850;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.feedback-message {
  margin: 0;
  color: #39434b;
  font-size: 0.88rem;
  line-height: 1.8;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

/* ---------- Moderation note ---------- */

.feedback-admin-note-label {
  display: block;
  margin-bottom: 8px;
  color: var(--color-midnight, #07182a);
  font-size: 0.76rem;
  font-weight: 800;
}

.feedback-admin-note {
  width: 100%;
  min-height: 110px;
  resize: vertical;
  padding: 12px 14px;
}

/* ---------- Modal actions ---------- */

.feedback-modal-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 9px;
  padding-top: 4px;
}

.feedback-modal-actions button {
  min-height: 40px;
}

/* ---------- Error ---------- */

.feedback-modal-error,
.feedback-action-error {
  padding: 11px 13px;
  border-radius: 10px;
  color: #8b3d3d;
  background: rgba(180, 77, 77, 0.07);
  border: 1px solid rgba(180, 77, 77, 0.17);
  font-size: 0.74rem;
  line-height: 1.5;
  animation: feedbackStatusEnter 220ms ease both;
}

/* ---------- Scrollbar ---------- */

.feedback-modal::-webkit-scrollbar,
.feedback-panel::-webkit-scrollbar {
  width: 7px;
}

.feedback-modal::-webkit-scrollbar-thumb,
.feedback-panel::-webkit-scrollbar-thumb {
  background: rgba(122, 118, 110, 0.28);
  border-radius: 999px;
}

.feedback-modal::-webkit-scrollbar-track,
.feedback-panel::-webkit-scrollbar-track {
  background: transparent;
}

/* =========================================================
   ANIMATIONS
   ========================================================= */

@keyframes feedbackPageEnter {
  from {
    opacity: 0;
    transform: translateY(8px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes feedbackOverlayEnter {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

@keyframes feedbackDrawerEnter {
  from {
    opacity: 0;
    transform: translateX(35px);
  }

  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes feedbackStatusEnter {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 900px) {
  .feedback-toolbar {
    align-items: stretch;
  }

  .feedback-filters {
    width: 100%;
  }

  .feedback-search {
    width: 100%;
  }

  .feedback-table-card {
    border-radius: 16px;
  }

  .feedback-modal,
  .feedback-panel {
    width: min(560px, 100%);
  }
}

@media (max-width: 640px) {
  .admin-feedback-page {
    max-width: none;
  }

  .feedback-toolbar {
    gap: 11px;
  }

  .feedback-filter-button {
    min-height: 38px;
    padding-inline: 12px;
    font-size: 0.7rem;
  }

  .feedback-pagination {
    align-items: flex-start;
    flex-direction: column;
  }

  .feedback-pagination-controls {
    width: 100%;
    justify-content: space-between;
  }

  .feedback-overlay {
    align-items: flex-end;
  }

  .feedback-modal,
  .feedback-panel {
    width: 100%;
    height: min(92dvh, 850px);
    max-height: 92dvh;
    border-left: 0;
    border-top: 1px solid rgba(214, 166, 59, 0.25);
    border-radius: 22px 22px 0 0;
    animation: feedbackSheetEnter 360ms cubic-bezier(0.22, 1, 0.36, 1) both;
  }

  .feedback-modal-header,
  .feedback-panel-header {
    padding: 20px 20px 17px;
  }

  .feedback-modal-body,
  .feedback-panel-body {
    padding: 21px 20px 28px;
  }

  .feedback-meta-grid {
    grid-template-columns: 1fr;
  }

  .feedback-modal-title {
    font-size: 1.18rem;
  }
}

@media (max-width: 420px) {
  .feedback-filters {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .feedback-filter-button {
    width: 100%;
  }

  .feedback-search {
    min-width: 0;
  }

  .feedback-modal-actions {
    display: grid;
    grid-template-columns: 1fr;
  }

  .feedback-modal-actions button {
    width: 100%;
  }
}

@keyframes feedbackSheetEnter {
  from {
    opacity: 0;
    transform: translateY(45px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .admin-feedback-page,
  .feedback-overlay,
  .feedback-modal,
  .feedback-panel,
  .feedback-status-enter {
    animation: none !important;
  }

  .feedback-filter-button,
  .feedback-view-button,
  .feedback-page-button,
  .feedback-modal-close {
    transition: none !important;
  }
}
/* =========================================================
   ADMIN QUERIES — PREMIUM LIGHT ADMIN UI
   ========================================================= */

.admin-queries-page {
  width: 100%;
  animation: adminQueriesPageEnter 0.45s ease both;
}

.admin-queries-header {
  margin-bottom: 24px;
}

.admin-queries-title {
  margin: 0;
  color: var(--color-midnight);
  font-size: clamp(1.65rem, 2.4vw, 2.15rem);
  font-weight: 800;
  letter-spacing: -0.035em;
  line-height: 1.15;
}

.admin-queries-description {
  max-width: 720px;
  margin: 8px 0 0;
  color: var(--color-muted);
  font-size: 0.94rem;
  line-height: 1.65;
}

/* ---------------------------------------------------------
   TOOLBAR
   --------------------------------------------------------- */

.queries-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 18px;
}

.queries-filters {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.queries-filter-button {
  min-height: 38px;
  padding: 0 14px;
  border: 1px solid var(--color-border);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.78);
  color: var(--color-charcoal);
  font-size: 0.82rem;
  font-weight: 700;
  cursor: pointer;
  transition:
    background 0.2s ease,
    border-color 0.2s ease,
    color 0.2s ease,
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.queries-filter-button:hover {
  border-color: rgba(214, 166, 59, 0.45);
  background: var(--color-ivory);
  transform: translateY(-1px);
}

.queries-filter-button.active {
  border-color: var(--color-gold);
  background: rgba(214, 166, 59, 0.12);
  color: var(--color-midnight);
  box-shadow: 0 5px 16px rgba(214, 166, 59, 0.1);
}

.queries-search {
  width: min(100%, 320px);
  min-height: 42px;
  padding: 0 14px;
  border: 1px solid var(--color-border);
  border-radius: 11px;
  outline: none;
  background: #fff;
  color: var(--color-midnight);
  font-size: 0.87rem;
  transition:
    border-color 0.2s ease,
    box-shadow 0.2s ease;
}

.queries-search::placeholder {
  color: var(--color-muted);
}

.queries-search:focus {
  border-color: rgba(214, 166, 59, 0.72);
  box-shadow: 0 0 0 4px rgba(214, 166, 59, 0.1);
}

/* ---------------------------------------------------------
   TABLE
   --------------------------------------------------------- */

.queries-table-card {
  overflow: hidden;
  border: 1px solid rgba(13, 34, 56, 0.09);
  border-radius: 18px;
  background: #fff;
  box-shadow:
    0 14px 42px rgba(7, 24, 42, 0.07),
    0 2px 8px rgba(7, 24, 42, 0.025);
}

.queries-table-wrapper {
  width: 100%;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.queries-table {
  width: 100%;
  min-width: 920px;
  border-collapse: collapse;
}

.queries-table thead {
  background: rgba(250, 247, 239, 0.72);
}

.queries-table th {
  padding: 14px 17px;
  border-bottom: 1px solid var(--color-border);
  color: var(--color-muted);
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.075em;
  line-height: 1.2;
  text-align: left;
  text-transform: uppercase;
  white-space: nowrap;
}

.queries-table td {
  padding: 16px 17px;
  border-bottom: 1px solid rgba(13, 34, 56, 0.065);
  color: var(--color-charcoal);
  font-size: 0.83rem;
  vertical-align: middle;
}

.queries-table tbody tr {
  transition:
    background 0.2s ease,
    box-shadow 0.2s ease;
}

.queries-table tbody tr:hover {
  background: rgba(250, 247, 239, 0.48);
}

.queries-table tbody tr:last-child td {
  border-bottom: 0;
}

/* ---------------------------------------------------------
   CUSTOMER
   --------------------------------------------------------- */

.query-customer {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 175px;
}

.query-customer-avatar {
  display: grid;
  flex: 0 0 36px;
  width: 36px;
  height: 36px;
  place-items: center;
  border: 1px solid rgba(214, 166, 59, 0.3);
  border-radius: 50%;
  background: linear-gradient(
    145deg,
    rgba(214, 166, 59, 0.17),
    rgba(231, 195, 108, 0.08)
  );
  color: var(--color-midnight);
  font-size: 0.78rem;
  font-weight: 800;
}

.query-customer-info {
  min-width: 0;
}

.query-customer-name {
  overflow: hidden;
  color: var(--color-midnight);
  font-weight: 750;
  line-height: 1.35;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.query-customer-email {
  overflow: hidden;
  max-width: 210px;
  margin-top: 2px;
  color: var(--color-muted);
  font-size: 0.74rem;
  line-height: 1.4;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ---------------------------------------------------------
   SUBJECT / MESSAGE
   --------------------------------------------------------- */

.query-subject {
  display: block;
  max-width: 230px;
  overflow: hidden;
  color: var(--color-midnight);
  font-weight: 750;
  line-height: 1.4;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.query-message-preview {
  display: -webkit-box;
  max-width: 280px;
  overflow: hidden;
  color: var(--color-muted);
  font-size: 0.76rem;
  line-height: 1.55;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

/* ---------------------------------------------------------
   CATEGORY
   --------------------------------------------------------- */

.query-category {
  display: inline-flex;
  align-items: center;
  min-height: 27px;
  padding: 4px 9px;
  border: 1px solid rgba(13, 34, 56, 0.1);
  border-radius: 8px;
  background: rgba(13, 34, 56, 0.035);
  color: var(--color-navy);
  font-size: 0.7rem;
  font-weight: 750;
  white-space: nowrap;
}

/* ---------------------------------------------------------
   STATUS / PRIORITY
   --------------------------------------------------------- */

.query-status-badge,
.query-priority-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 27px;
  padding: 4px 9px;
  border-radius: 999px;
  font-size: 0.69rem;
  font-weight: 800;
  line-height: 1;
  white-space: nowrap;
}

.query-status-badge.status-new {
  border: 1px solid rgba(37, 99, 235, 0.18);
  background: rgba(37, 99, 235, 0.08);
  color: #1d4ed8;
}

.query-status-badge.status-in_progress {
  border: 1px solid rgba(214, 166, 59, 0.22);
  background: rgba(214, 166, 59, 0.1);
  color: #8a6514;
}

.query-status-badge.status-resolved {
  border: 1px solid rgba(22, 101, 52, 0.17);
  background: rgba(22, 101, 52, 0.08);
  color: #166534;
}

.query-status-badge.status-closed {
  border: 1px solid rgba(100, 116, 139, 0.2);
  background: rgba(100, 116, 139, 0.08);
  color: #475569;
}

.query-priority-badge.priority-normal {
  border: 1px solid rgba(100, 116, 139, 0.18);
  background: rgba(100, 116, 139, 0.07);
  color: #475569;
}

.query-priority-badge.priority-high {
  border: 1px solid rgba(180, 83, 9, 0.18);
  background: rgba(180, 83, 9, 0.08);
  color: #9a3412;
}

.query-priority-badge.priority-urgent {
  border: 1px solid rgba(185, 28, 28, 0.18);
  background: rgba(185, 28, 28, 0.08);
  color: #b91c1c;
}

/* ---------------------------------------------------------
   VIEW BUTTON
   --------------------------------------------------------- */

.query-view-button {
  min-height: 34px;
  padding: 0 12px;
  border: 1px solid rgba(13, 34, 56, 0.12);
  border-radius: 9px;
  background: #fff;
  color: var(--color-navy);
  font-size: 0.74rem;
  font-weight: 800;
  cursor: pointer;
  transition:
    background 0.2s ease,
    border-color 0.2s ease,
    color 0.2s ease,
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.query-view-button:hover {
  border-color: rgba(214, 166, 59, 0.45);
  background: var(--color-ivory);
  color: var(--color-midnight);
  transform: translateY(-1px);
  box-shadow: 0 5px 14px rgba(7, 24, 42, 0.07);
}

/* ---------------------------------------------------------
   EMPTY / LOADING
   --------------------------------------------------------- */

.queries-empty-state,
.queries-loading-state {
  display: flex;
  min-height: 250px;
  align-items: center;
  justify-content: center;
  padding: 32px;
  color: var(--color-muted);
  font-size: 0.86rem;
  text-align: center;
}

.queries-loading-state {
  animation: queriesPulse 1.4s ease-in-out infinite;
}

/* ---------------------------------------------------------
   PAGINATION
   --------------------------------------------------------- */

.queries-pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 14px 17px;
  border-top: 1px solid rgba(13, 34, 56, 0.065);
}

.queries-pagination-info {
  color: var(--color-muted);
  font-size: 0.76rem;
}

.queries-pagination-actions {
  display: flex;
  align-items: center;
  gap: 7px;
}

.queries-pagination-button {
  min-width: 34px;
  height: 34px;
  padding: 0 9px;
  border: 1px solid var(--color-border);
  border-radius: 8px;
  background: #fff;
  color: var(--color-navy);
  font-size: 0.75rem;
  font-weight: 750;
  cursor: pointer;
  transition:
    background 0.2s ease,
    border-color 0.2s ease,
    opacity 0.2s ease;
}

.queries-pagination-button:hover:not(:disabled) {
  border-color: rgba(214, 166, 59, 0.4);
  background: var(--color-ivory);
}

.queries-pagination-button:disabled {
  cursor: not-allowed;
  opacity: 0.42;
}

/* ---------------------------------------------------------
   DETAIL / REPLY DRAWER
   --------------------------------------------------------- */

.queries-overlay {
  position: fixed;
  z-index: 1000;
  inset: 0;
  display: flex;
  justify-content: flex-end;
  background: rgba(7, 24, 42, 0.42);
  backdrop-filter: blur(5px);
  -webkit-backdrop-filter: blur(5px);
  animation: queriesOverlayEnter 0.22s ease both;
}

.queries-drawer {
  display: flex;
  width: min(100%, 590px);
  height: 100%;
  flex-direction: column;
  overflow: hidden;
  background: var(--color-ivory);
  border-left: 1px solid rgba(13, 34, 56, 0.1);
  box-shadow: -18px 0 55px rgba(7, 24, 42, 0.16);
  animation: queriesDrawerEnter 0.32s cubic-bezier(0.22, 1, 0.36, 1) both;
}

.queries-drawer-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 22px 24px;
  border-bottom: 1px solid rgba(13, 34, 56, 0.09);
  background: rgba(255, 255, 255, 0.76);
}

.queries-drawer-heading {
  min-width: 0;
}

.queries-drawer-title {
  margin: 0;
  color: var(--color-midnight);
  font-size: 1.08rem;
  font-weight: 800;
  line-height: 1.35;
}

.queries-drawer-subtitle {
  margin: 5px 0 0;
  color: var(--color-muted);
  font-size: 0.76rem;
}

.queries-drawer-close {
  display: grid;
  flex: 0 0 34px;
  width: 34px;
  height: 34px;
  place-items: center;
  border: 1px solid rgba(13, 34, 56, 0.1);
  border-radius: 9px;
  background: #fff;
  color: var(--color-navy);
  font-size: 1rem;
  cursor: pointer;
  transition:
    background 0.2s ease,
    border-color 0.2s ease,
    transform 0.2s ease;
}

.queries-drawer-close:hover {
  border-color: rgba(214, 166, 59, 0.45);
  background: var(--color-ivory);
  transform: rotate(2deg);
}

.queries-drawer-body {
  flex: 1;
  overflow-y: auto;
  padding: 22px 24px 30px;
}

/* ---------------------------------------------------------
   QUERY DETAIL
   --------------------------------------------------------- */

.query-detail-identity {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
}

.query-detail-avatar {
  display: grid;
  flex: 0 0 44px;
  width: 44px;
  height: 44px;
  place-items: center;
  border: 1px solid rgba(214, 166, 59, 0.3);
  border-radius: 50%;
  background: rgba(214, 166, 59, 0.1);
  color: var(--color-midnight);
  font-weight: 850;
}

.query-detail-name {
  margin: 0;
  color: var(--color-midnight);
  font-size: 0.95rem;
  font-weight: 800;
}

.query-detail-email {
  margin: 3px 0 0;
  color: var(--color-muted);
  font-size: 0.75rem;
}

.query-detail-meta-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 20px;
}

.query-detail-meta-card {
  padding: 12px 13px;
  border: 1px solid rgba(13, 34, 56, 0.08);
  border-radius: 11px;
  background: rgba(255, 255, 255, 0.72);
}

.query-detail-meta-label {
  display: block;
  margin-bottom: 5px;
  color: var(--color-muted);
  font-size: 0.65rem;
  font-weight: 800;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.query-detail-meta-value {
  color: var(--color-midnight);
  font-size: 0.78rem;
  font-weight: 750;
  line-height: 1.45;
}

.query-detail-message {
  margin-bottom: 22px;
  padding: 16px;
  border: 1px solid rgba(13, 34, 56, 0.08);
  border-radius: 13px;
  background: #fff;
}

.query-detail-message-label {
  margin: 0 0 8px;
  color: var(--color-muted);
  font-size: 0.67rem;
  font-weight: 800;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.query-detail-message-text {
  margin: 0;
  color: var(--color-charcoal);
  font-size: 0.84rem;
  line-height: 1.72;
  white-space: pre-wrap;
}

/* ---------------------------------------------------------
   CONVERSATION
   --------------------------------------------------------- */

.query-conversation {
  display: flex;
  flex-direction: column;
  gap: 11px;
  margin-bottom: 22px;
}

.query-conversation-message {
  max-width: 88%;
  padding: 12px 14px;
  border: 1px solid rgba(13, 34, 56, 0.08);
  border-radius: 13px;
  background: #fff;
}

.query-conversation-message.customer {
  align-self: flex-start;
}

.query-conversation-message.admin {
  align-self: flex-end;
  border-color: rgba(214, 166, 59, 0.2);
  background: rgba(214, 166, 59, 0.08);
}

.query-conversation-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 5px;
}

.query-conversation-sender {
  color: var(--color-midnight);
  font-size: 0.68rem;
  font-weight: 800;
}

.query-conversation-time {
  color: var(--color-muted);
  font-size: 0.62rem;
}

.query-conversation-text {
  margin: 0;
  color: var(--color-charcoal);
  font-size: 0.78rem;
  line-height: 1.62;
  white-space: pre-wrap;
}

/* ---------------------------------------------------------
   REPLY
   --------------------------------------------------------- */

.query-reply-section {
  padding-top: 18px;
  border-top: 1px solid rgba(13, 34, 56, 0.09);
}

.query-reply-label {
  display: block;
  margin-bottom: 8px;
  color: var(--color-midnight);
  font-size: 0.75rem;
  font-weight: 800;
}

.query-reply-textarea {
  width: 100%;
  min-height: 135px;
  resize: vertical;
  padding: 13px 14px;
  border: 1px solid var(--color-border);
  border-radius: 11px;
  outline: none;
  background: #fff;
  color: var(--color-charcoal);
  font: inherit;
  font-size: 0.82rem;
  line-height: 1.6;
  transition:
    border-color 0.2s ease,
    box-shadow 0.2s ease;
}

.query-reply-textarea::placeholder {
  color: var(--color-muted);
}

.query-reply-textarea:focus {
  border-color: rgba(214, 166, 59, 0.72);
  box-shadow: 0 0 0 4px rgba(214, 166, 59, 0.1);
}

.query-reply-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 9px;
  margin-top: 11px;
}

.query-reply-button {
  min-height: 40px;
  padding: 0 17px;
  border: 1px solid var(--color-gold-dark);
  border-radius: 9px;
  background: var(--color-gold);
  color: var(--color-midnight);
  font-size: 0.76rem;
  font-weight: 850;
  cursor: pointer;
  box-shadow: 0 6px 16px rgba(214, 166, 59, 0.16);
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease,
    background 0.2s ease;
}

.query-reply-button:hover:not(:disabled) {
  background: var(--color-gold-light);
  transform: translateY(-1px);
  box-shadow: 0 9px 20px rgba(214, 166, 59, 0.2);
}

.query-reply-button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

/* ---------------------------------------------------------
   DRAWER ERROR / STATUS
   --------------------------------------------------------- */

.query-action-error {
  margin-top: 10px;
  padding: 10px 12px;
  border: 1px solid rgba(185, 28, 28, 0.16);
  border-radius: 9px;
  background: rgba(185, 28, 28, 0.06);
  color: #b91c1c;
  font-size: 0.73rem;
  line-height: 1.5;
  animation: queriesStatusEnter 0.25s ease both;
}

.query-action-success {
  margin-top: 10px;
  padding: 10px 12px;
  border: 1px solid rgba(22, 101, 52, 0.16);
  border-radius: 9px;
  background: rgba(22, 101, 52, 0.06);
  color: #166534;
  font-size: 0.73rem;
  line-height: 1.5;
  animation: queriesStatusEnter 0.25s ease both;
}

/* ---------------------------------------------------------
   ANIMATIONS
   --------------------------------------------------------- */

@keyframes adminQueriesPageEnter {
  from {
    opacity: 0;
    transform: translateY(7px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes queriesOverlayEnter {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

@keyframes queriesDrawerEnter {
  from {
    opacity: 0;
    transform: translateX(28px);
  }

  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes queriesStatusEnter {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes queriesPulse {
  0%,
  100% {
    opacity: 0.55;
  }

  50% {
    opacity: 1;
  }
}

/* ---------------------------------------------------------
   RESPONSIVE
   --------------------------------------------------------- */

@media (max-width: 900px) {
  .queries-toolbar {
    align-items: stretch;
  }

  .queries-search {
    width: 100%;
    max-width: 100%;
  }

  .queries-filters {
    width: 100%;
  }

  .queries-filter-button {
    flex: 1 1 auto;
  }

  .queries-drawer {
    width: min(100%, 560px);
  }
}

@media (max-width: 640px) {
  .admin-queries-header {
    margin-bottom: 18px;
  }

  .queries-toolbar {
    gap: 11px;
  }

  .queries-filters {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .queries-filter-button {
    width: 100%;
  }

  .queries-table-card {
    border-radius: 14px;
  }

  .queries-pagination {
    align-items: flex-start;
    flex-direction: column;
  }

  .queries-pagination-actions {
    width: 100%;
    justify-content: flex-end;
  }

  .queries-drawer {
    width: 100%;
    border-left: 0;
  }

  .queries-drawer-header {
    padding: 18px;
  }

  .queries-drawer-body {
    padding: 18px 18px 26px;
  }

  .query-detail-meta-grid {
    grid-template-columns: 1fr;
  }

  .query-conversation-message {
    max-width: 94%;
  }
}

@media (max-width: 420px) {
  .queries-filters {
    grid-template-columns: 1fr;
  }

  .queries-drawer-title {
    font-size: 0.98rem;
  }

  .query-detail-message {
    padding: 13px;
  }

  .query-reply-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .query-reply-button {
    width: 100%;
  }
}

@media (prefers-reduced-motion: reduce) {
  .admin-queries-page,
  .queries-overlay,
  .queries-drawer,
  .query-action-error,
  .query-action-success,
  .queries-loading-state {
    animation: none !important;
  }

  .queries-filter-button,
  .query-view-button,
  .queries-drawer-close,
  .query-reply-button {
    transition: none !important;
  }
}
/* =========================================================
   GLOBAL LANGUAGE SWITCHER — NAVBAR
   ========================================================= */

.navbar-language {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;

  flex-shrink: 0;

  white-space: nowrap;
}

.navbar-language > span {
  color: rgba(255, 255, 255, 0.28);
  font-size: 0.78rem;
  user-select: none;
}

.navbar-language-option {
  appearance: none;
  -webkit-appearance: none;

  border: 0;
  outline: 0;

  background: transparent;

  padding: 4px 2px;
  margin: 0;

  color: rgba(255, 255, 255, 0.58);

  font-family: var(--font-body, sans-serif);
  font-size: 0.76rem;
  font-weight: 600;

  line-height: 1;
  white-space: nowrap;

  cursor: pointer;

  transition:
    color 180ms ease,
    opacity 180ms ease,
    transform 180ms ease;
}

.navbar-language-option:hover {
  color: var(--color-gold-light);
  transform: translateY(-1px);
}

.navbar-language-option.is-active {
  color: var(--color-gold-light);
}

