  color: var(--color-gold-light);
  font-weight: 600;
}

.navbar-links > a.is-active::after {
  width: 100%;
  height: 2px;

  background:
    linear-gradient(
      90deg,
      transparent 0%,
      var(--color-gold) 18%,
      var(--color-gold-light) 50%,
      var(--color-gold) 82%,
      transparent 100%
    );

  box-shadow:
    0 0 8px
    rgba(214, 166, 59, 0.35);
}

.navbar-links > a.is-active:hover {
  color: var(--color-gold-light);
  transform: none;
}


/* =========================================================
   MOBILE NAVBAR — ACTIVE PAGE
   ========================================================= */

.navbar-mobile-links > a.is-active {
  color: #8f681e !important;

  background:
    linear-gradient(
      90deg,
      rgba(201, 166, 94, 0.16),
      rgba(201, 166, 94, 0.055)
    );

  border-bottom-color:
    rgba(201, 166, 94, 0.42);

  position: relative;

  font-weight: 700;
}

.navbar-mobile-links > a.is-active::before {
  content: "";

  position: absolute;

  left: 0;
  top: 9px;
  bottom: 9px;

  width: 3px;

  border-radius: 999px;

  background:
    linear-gradient(
      180deg,
      var(--color-gold-light),
      var(--color-gold)
    );

  box-shadow:
    0 0 8px
    rgba(201, 166, 94, 0.35);
}

.navbar-mobile-links > a.is-active span:last-child {
  color: var(--color-gold);
  transform: translateX(2px);
}


/* =========================================================
   ACCESSIBILITY — KEYBOARD FOCUS
   ========================================================= */

.navbar-links > a.is-active:focus-visible,
.navbar-mobile-links > a.is-active:focus-visible {
  outline:
    2px solid
    rgba(201, 166, 94, 0.65);

  outline-offset: 2px;
}
@import "tailwindcss";

html {
  scroll-behavior: auto;
  scroll-padding-top: 96px;
}

/* ============================================
   AKSHAANSHH JYOTISH — GLOBAL DESIGN SYSTEM
   ============================================ */

:root {
  /* Primary brand colours */
  --color-midnight: #07182a;
  --color-navy: #0d2238;
  --color-navy-soft: #142f4b;

  /* Gold accents */
  --color-gold: #d6a63b;
  --color-gold-light: #e7c36c;
  --color-gold-dark: #ad7c1d;

  /* Warm neutral surfaces */
  --color-ivory: #faf7ef;
  --color-cream: #f4eddd;
  --color-white: #ffffff;

  /* Text */
  --color-charcoal: #292929;
  --color-muted: #6f6a61;

  /* Borders */
  --color-border: #e4dac6;

  /* Layout */
--container-width: 1440px;

  /* Shape */
  --radius-small: 8px;
  --radius-medium: 16px;
  --radius-large: 28px;

  /* Effects */
  --shadow-soft: 0 10px 40px rgba(7, 24, 42, 0.08);
  --shadow-card: 0 12px 35px rgba(7, 24, 42, 0.1);
}

/* ============================================
   BASE
   ============================================ */

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--color-ivory);
  color: var(--color-charcoal);
  font-family: var(--font-body), Arial, sans-serif;
  line-height: 1.6;

  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
textarea,
select {
  font: inherit;
}

button {
  cursor: pointer;
}

/* ============================================
   SHARED LAYOUT
   ============================================ */

.site-container {
  width: min(100% - 40px, var(--container-width));
  margin-inline: auto;
}

.section {
  padding: 96px 0;
}

.section-small {
  padding: 64px 0;
}

/* ============================================
   TYPOGRAPHY
   ============================================ */

.eyebrow {
  color: var(--color-gold-dark);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.display-heading {
  color: var(--color-midnight);
  font-family: var(--font-heading), Georgia, serif;
  font-size: clamp(2.6rem, 6vw, 5.2rem);
  font-weight: 500;
  line-height: 1.05;
  letter-spacing: -0.03em;
}

.section-heading {
  color: var(--color-midnight);
  font-family: var(--font-heading), Georgia, serif;  font-size: clamp(2rem, 4vw, 3.4rem);
  font-weight: 500;
  line-height: 1.15;
}

/* ============================================
   BUTTONS
   ============================================ */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;

  min-height: 48px;
  padding: 0 22px;

  border: 1px solid transparent;
  border-radius: var(--radius-small);

  font-size: 0.92rem;
  font-weight: 600;

  transition:
    transform 180ms ease,
    background-color 180ms ease,
    border-color 180ms ease,
    box-shadow 180ms ease;
}

.btn:hover {
  transform: translateY(-2px);
}

.btn-primary {
  background: linear-gradient(
    135deg,
    var(--color-gold-light),
    var(--color-gold)
  );

  color: #17130b;

  box-shadow: 0 8px 24px rgba(214, 166, 59, 0.22);
}

.btn-primary:hover {
  box-shadow: 0 12px 30px rgba(214, 166, 59, 0.32);
}

.btn-secondary {
  background: var(--color-midnight);
  color: var(--color-white);
}

.btn-outline {
  background: transparent;
  border-color: var(--color-border);
  color: #ffffff;
}

/* ============================================
   CARDS
   ============================================ */

.surface-card {
  background: rgba(255, 255, 255, 0.55);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-medium);
  box-shadow: var(--shadow-soft);
}

/* ============================================
   RESPONSIVE
   ============================================ */

@media (max-width: 768px) {
  .site-container {
    width: min(100% - 28px, var(--container-width));
  }

  .section {
    padding: 72px 0;
  }

  .section-small {
    padding: 48px 0;
  }
}

/* ============================================
   NAVIGATION
   ============================================ */

.navbar {
  position: fixed;
  top: 0;
  left: 0;
  z-index: 1000;

  width: 100%;

  background: transparent;

  border-bottom: 1px solid transparent;

  transition:
    background 0.35s ease,
    backdrop-filter 0.35s ease,
    border-color 0.35s ease,
    box-shadow 0.35s ease;
}

.navbar-scrolled {
  background: rgba(7, 24, 42, 0.78);

  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);

  border-bottom: 1px solid rgba(255, 255, 255, 0.08);

  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.18);
}

.navbar-inner {
  min-height: 88px;

  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}

.navbar-brand {
  display: flex;
  align-items: center;
  flex-shrink: 0;
}

.navbar-logo {
  width: auto;
  height: 58px;
  aspect-ratio: 180 / 70;
  object-fit: contain;

  transition: transform .3s ease;
}

.navbar-brand:hover .navbar-logo {
  transform: scale(1.04);
}

.navbar-links {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 32px;

  margin-left: auto;
}

.navbar-links a {
  position: relative;

  color: rgba(255, 255, 255, 0.88);

  font-size: 0.86rem;
  font-weight: 500;

  transition:
    color .25s ease,
    transform .25s ease;
}

.navbar-links a:hover {
  color: var(--color-gold-light);
  transform: translateY(-2px);
}

.navbar-links a::after {
  content: "";

  position: absolute;
  left: 0;
  bottom: -8px;

  width: 0;
  height: 1px;

  background: var(--color-gold);

  transition: width 180ms ease;
}

.navbar-links a:hover::after {
  width: 100%;
}

.navbar-book {
  flex-shrink: 0;
}

/* Temporary tablet/mobile navigation */

@media (max-width: 900px) {
  .navbar-links {
    display: none;
  }

  .navbar-inner {
    min-height: 78px;
  }
}

@media (max-width: 520px) {
  .navbar-logo {
    height: 48px;
  }

  .navbar-book {
    padding-inline: 14px;
    font-size: 0.78rem;
  }

  .navbar-book span {
    display: none;
  }
}

/* ============================================
   HERO
   ============================================ */

.hero {
  position: relative;
  overflow: hidden;

  min-height: 760px;
  padding-top: 120px;

  display: flex;
  align-items: center;

  background:
    radial-gradient(
      circle at 75% 38%,
      rgba(35, 73, 108, 0.65),
      transparent 30%
    ),
    linear-gradient(
      135deg,
      #04111f 0%,
      var(--color-midnight) 48%,
      #0c2742 100%
    );

  color: white;
}

.hero::after {
  content: "";

  position: absolute;
  left: 0;
  right: 0;
  bottom: -1px;

  height: 70px;

  background: var(--color-ivory);
  clip-path: ellipse(58% 35% at 50% 100%);
}

.hero-grid {
  position: relative;
  z-index: 3;

  display: grid;
  grid-template-columns: 1.1fr 0.9fr;

  align-items: center;

  gap: 100px;

  padding-bottom: 70px;
}

/* LEFT HERO CONTENT */

.hero-content {
  max-width: 760px;
}

.hero-eyebrow {
  color: var(--color-gold-light);
  margin-bottom: 18px;
}

.hero-title {
  margin: 0;

  color: white;

  font-size: clamp(4.2rem, 6vw, 6.4rem);

  line-height: 1.02;

  letter-spacing: -0.04em;
}

.hero-title span {
  color: var(--color-gold-light);
}

.hero-description {
  max-width: 700px;

  margin: 34px 0 42px;

  color: #d7e0e8;

  font-size: 1.12rem;

  line-height: 1.9;
}

.hero-actions {
  display: flex;

  gap: 18px;

  margin-top: 8px;
}

.hero-secondary {
  color: white;

  border: 1px solid rgba(255, 255, 255, 0.25);
  background: rgba(255, 255, 255, 0.04);
}

.hero-secondary:hover {
  border-color: rgba(255, 255, 255, 0.5);
  background: rgba(255, 255, 255, 0.08);
}

/* TRUST POINTS */

.hero-trust {
  display: flex;
  flex-wrap: wrap;

  margin-top: 54px;
}

.hero-trust > div {
  display: flex;
  flex-direction: column;

  min-width: 145px;
  padding: 0 24px;

  border-right: 1px solid rgba(255, 255, 255, 0.15);
}

.hero-trust > div:first-child {
  padding-left: 0;
}

.hero-trust > div:last-child {
  border-right: 0;
}

.hero-trust strong {
  color: white;
  font-size: 0.83rem;
}

.hero-trust span {
  margin-top: 3px;

  color: rgba(255, 255, 255, 0.58);

  font-size: 0.73rem;
}

/* ============================================
   HERO CONSULTANT VISUAL
   ============================================ */

.hero-visual {
  position: relative;

  min-height: 570px;

  display: flex;
  align-items: flex-end;
  justify-content: center;
}

.hero-image-wrapper {
  position: relative;

  z-index: 3;

  width: min(100%, 640px);

  display: flex;

  align-items: flex-end;

  justify-content: center;
}

.hero-image{
  width:100%;
  height:auto;

  object-fit:contain;

  filter:
    drop-shadow(0 35px 60px rgba(0,0,0,.35));

  transition:
    transform .5s ease,
    filter .5s ease;
}

.hero-image:hover{
  transform:scale(1.02);
}

/* ZODIAC CIRCLE */

.hero-zodiac {
  position: absolute;
  z-index: 1;

  top: 30px;
  left: 50%;

  width: 470px;
  height: 470px;

  transform: translateX(-50%);

  border: 1px solid rgba(214, 166, 59, 0.38);
  border-radius: 50%;

  display: flex;
  align-items: center;
  justify-content: center;
}

.hero-zodiac::before,
.hero-zodiac::after {
  content: "";

  position: absolute;

  border: 1px solid rgba(214, 166, 59, 0.18);
  border-radius: 50%;
}

.hero-zodiac::before {
  inset: 35px;
}

.hero-zodiac::after {
  inset: 75px;
}

.hero-zodiac span {
  color: rgba(231, 195, 108, 0.55);
  font-size: 2rem;
}

/* CONSULTANT LABEL */

.consultant-label {
  position: absolute;

  z-index: 5;

  left: 50%;

  bottom: -8px;

  width: min(92%, 420px);

  transform: translateX(-50%);

  padding: 18px 30px;

  text-align: center;

  background: rgba(5,20,35,.95);

  border: 1px solid var(--color-gold);

  border-radius: 999px;

  box-shadow: 0 20px 45px rgba(0,0,0,.28);
}

.consultant-label strong,
.consultant-label span {
  display: block;
}

.consultant-label strong {
  color: white;

  font-family: var(--font-heading), Georgia, serif;
  font-size: 1.1rem;
}

.consultant-label span {
  margin-top: 2px;

  color: var(--color-gold-light);
  font-size: 0.68rem;
}

/* ============================================
   DECORATIVE ORBITS
   ============================================ */

.hero-orbit {
  position: absolute;

  border: 1px solid rgba(214, 166, 59, 0.08);
  border-radius: 50%;

  pointer-events: none;
}

.hero-orbit-one {
  width: 700px;
  height: 700px;

  top: -350px;
  right: -250px;
}

.hero-orbit-two {
  width: 480px;
  height: 480px;

  left: -300px;
  bottom: -300px;
}

/* ============================================
   SERVICES INTRO
   ============================================ */

.services-intro {
  text-align: center;
}

.services-intro .section-heading {
  margin: 8px 0 14px;
}

.services-intro > p:last-child {
  max-width: 650px;
  margin: auto;

  color: var(--color-muted);
}

/* ============================================
   RESPONSIVE HERO
   ============================================ */

@media (max-width: 950px) {
  .hero {
    padding-top: 130px;
  }

  .hero-grid {
    grid-template-columns: 1fr;
    gap: 20px;

    text-align: center;
  }

  .hero-content {
    max-width: 760px;
    margin: auto;
  }

  .hero-description {
    margin-left: auto;
    margin-right: auto;
  }

  .hero-actions {
    justify-content: center;
  }

.hero-trust {
  display:flex;

  margin-top:60px;
}

  .hero-visual {
    min-height: 520px;
    margin-top: 20px;
  }
}

@media (max-width: 600px) {
  .hero {
    padding-top: 110px;
  }

  .hero-grid {
    padding-bottom: 90px;
  }

  .hero-title {
    font-size: clamp(2.8rem, 13vw, 4rem);
  }

  .hero-description {
    font-size: 0.92rem;
  }

  .hero-actions {
    flex-direction: column;
  }

  .hero-actions .btn {
    width: 100%;
  }

  .hero-trust {
    gap: 18px;
    margin-top: 40px;
  }

  .hero-trust > div {
    min-width: 0;
    padding: 0 12px;

    border: 0;
  }

  .hero-zodiac {
    width: 340px;
    height: 340px;
  }

  .hero-visual {
    min-height: 430px;
  }
}

/* =========================================================
   HOMEPAGE — CLEAN COMPONENT SYSTEM
   Matches the current Home component tree.
   ========================================================= */

/* ---------- Trust ---------- */

.trust-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 22px;
  margin-top: 42px;
}

.trust-card {
  position: relative;
  min-height: 190px;
  padding: 30px 28px;
  overflow: hidden;
  background:
    radial-gradient(circle at 100% 0%, rgba(214, 166, 59, 0.08), transparent 42%),
    var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: 20px;
  box-shadow: var(--shadow-soft);
  transition:
    transform 260ms ease,
    border-color 260ms ease,
    box-shadow 260ms ease;
}

.trust-card::before {
  content: "";
  position: absolute;
  inset: 0 auto auto 0;
  width: 100%;
  height: 2px;
  background: linear-gradient(
    90deg,
    transparent,
    var(--color-gold),
    transparent
  );
  opacity: 0.55;
}

.trust-card:hover {
  transform: translateY(-6px);
  border-color: rgba(214, 166, 59, 0.55);
  box-shadow: 0 18px 42px rgba(7, 24, 42, 0.12);
}

.trust-card h3 {
  margin: 0 0 12px;
  color: var(--color-midnight);
  font-family: var(--font-heading), Georgia, serif;
  font-size: 1.35rem;
  font-weight: 500;
  line-height: 1.25;
}

.trust-card p {
  margin: 0;
  color: var(--color-muted);
  font-size: 0.92rem;
  line-height: 1.75;
}

/* ---------- Services ---------- */

.services-section {
  position: relative;
  padding: 105px 0;
  background:
    linear-gradient(
      180deg,
      rgba(244, 237, 221, 0.55),
      rgba(250, 247, 239, 0)
    );
}

.services-heading {
  max-width: 760px;
  margin-inline: auto;
  text-align: center;
}

.services-heading .eyebrow {
  display: inline-block;
  margin-bottom: 12px;
}

.services-heading h2 {
  margin: 0;
}

.services-heading > p {
  max-width: 680px;
  margin: 18px auto 0;
  color: var(--color-muted);
  line-height: 1.8;
}

.services-home-grid {
  margin-top: 46px;
}

.service-home-card {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 330px;
  padding: 29px 28px 25px;
  overflow: hidden;
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: 22px;
  box-shadow: 0 10px 30px rgba(7, 24, 42, 0.055);
  transition:
    transform 260ms ease,
    border-color 260ms ease,
    box-shadow 260ms ease;
}

.service-home-card::before {
  content: "";
  position: absolute;
  inset: 0 0 auto;
  height: 3px;
  background: linear-gradient(
    90deg,
    transparent,
    var(--color-gold),
    transparent
  );
  opacity: 0.7;
}

.service-home-card:hover {
  transform: translateY(-7px);
  border-color: rgba(214, 166, 59, 0.5);
  box-shadow: 0 20px 42px rgba(7, 24, 42, 0.11);
}

.service-home-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 22px;
}

.service-home-symbol {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border: 1px solid rgba(214, 166, 59, 0.35);
  border-radius: 50%;
  color: var(--color-gold-dark);
  background: rgba(214, 166, 59, 0.07);
  font-family: var(--font-heading), Georgia, serif;
  font-size: 1.05rem;
}

.service-home-number {
  color: rgba(7, 24, 42, 0.28);
  font-family: var(--font-heading), Georgia, serif;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.12em;
}

.service-home-category {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  margin-bottom: 9px;
  color: var(--color-gold-dark);
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.service-home-card h3 {
  margin: 0 0 11px;
  color: var(--color-midnight);
  font-family: var(--font-heading), Georgia, serif;
  font-size: 1.42rem;
  font-weight: 500;
  line-height: 1.28;
}

.service-home-card > p {
  margin: 0;
  color: var(--color-muted);
  font-size: 0.9rem;
  line-height: 1.72;
}

.service-home-details {
  display: flex;
  flex-wrap: wrap;
  gap: 7px 14px;
  margin-top: auto;
  padding-top: 19px;
  color: var(--color-muted);
  font-size: 0.74rem;
  line-height: 1.5;
}

.service-home-details span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.service-home-details span + span::before {
  content: "•";
  color: var(--color-gold);
}

.service-home-link {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
  margin-top: 17px;
  padding-top: 16px;
  border-top: 1px solid rgba(228, 218, 198, 0.78);
  color: var(--color-midnight);
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  transition:
    color 180ms ease,
    gap 180ms ease;
}

.service-home-link span {
  color: var(--color-gold-dark);
  font-size: 1rem;
  transition: transform 180ms ease;
}

.service-home-link:hover {
  color: var(--color-gold-dark);
}

.service-home-link:hover span {
  transform: translateX(4px);
}

.services-home-loading,
.services-home-error,
.services-home-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 12px;
  min-height: 180px;
  margin-top: 42px;
  padding: 32px 24px;
  text-align: center;
  background: rgba(255, 255, 255, 0.72);
  border: 1px solid var(--color-border);
  border-radius: 20px;
  color: var(--color-muted);
}

.services-home-loading p,
.services-home-error p,
.services-home-empty p {
  margin: 0;
}

.services-home-spinner {
  width: 28px;
  height: 28px;
  border: 2px solid rgba(214, 166, 59, 0.22);
  border-top-color: var(--color-gold);
  border-radius: 50%;
  animation: homepageSpinner 800ms linear infinite;
}

@keyframes homepageSpinner {
  to {
    transform: rotate(360deg);
  }
}

.services-home-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 28px;
  margin-top: 56px;
  padding: 25px 28px;
  background: rgba(255, 255, 255, 0.7);
  border: 1px solid var(--color-border);
  border-radius: 20px;
}

.services-home-cta-copy {
  min-width: 0;
}

.services-home-cta-copy strong {
  display: block;
  margin-bottom: 5px;
  color: var(--color-midnight);
  font-family: var(--font-heading), Georgia, serif;
  font-size: 1.12rem;
  font-weight: 500;
}

.services-home-cta-copy p {
  margin: 0;
  color: var(--color-muted);
  font-size: 0.88rem;
  line-height: 1.65;
}

.service-home-view-all {
  flex: 0 0 auto;
  min-width: 190px;
  border-radius: 999px;
}

/* ---------- Process ---------- */

.process-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 20px;
  margin-top: 44px;
}

.process-card {
  position: relative;
  min-width: 0;
  padding: 30px 25px;
  text-align: center;
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: 20px;
  box-shadow: var(--shadow-soft);
  transition:
    transform 260ms ease,
    border-color 260ms ease,
    box-shadow 260ms ease;
}

.process-card:hover {
  transform: translateY(-6px);
  border-color: rgba(214, 166, 59, 0.55);
  box-shadow: 0 18px 42px rgba(7, 24, 42, 0.12);
}

.process-number {
  display: grid;
  width: 64px;
  height: 64px;
  margin: 0 auto 21px;
  place-items: center;
  border: 1px solid rgba(214, 166, 59, 0.5);
  border-radius: 50%;
  background:
    radial-gradient(circle, rgba(214, 166, 59, 0.2), rgba(214, 166, 59, 0.05));
  color: var(--color-gold-dark);
  font-family: var(--font-heading), Georgia, serif;
  font-size: 1.15rem;
  font-weight: 700;
}

.process-card h3 {
  margin: 0 0 11px;
  color: var(--color-midnight);
  font-family: var(--font-heading), Georgia, serif;
  font-size: 1.18rem;
  font-weight: 500;
  line-height: 1.35;
}

.process-card p {
  margin: 0;
  color: var(--color-muted);
  font-size: 0.88rem;
  line-height: 1.72;
}

/* ---------- Testimonials ---------- */

.testimonial-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 22px;
  margin-top: 44px;
}

.testimonial-card {
  position: relative;
  padding: 34px 30px;
  text-align: left;
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: 22px;
  box-shadow: var(--shadow-soft);
  transition:
    transform 260ms ease,
    border-color 260ms ease,
    box-shadow 260ms ease;
}

.testimonial-card::before {
  content: "“";
  position: absolute;
  top: 10px;
  right: 22px;
  color: rgba(214, 166, 59, 0.12);
  font-family: Georgia, serif;
  font-size: 5.5rem;
  line-height: 1;
}

.testimonial-card:hover {
  transform: translateY(-6px);
  border-color: rgba(214, 166, 59, 0.52);
  box-shadow: 0 18px 42px rgba(7, 24, 42, 0.12);
}

.testimonial-rating {
  margin-bottom: 17px;
  color: var(--color-gold);
  font-size: 1rem;
  letter-spacing: 4px;
}

.testimonial-review {
  margin: 0 0 24px;
  color: var(--color-muted);
  font-size: 0.94rem;
  font-style: italic;
  line-height: 1.82;
}

.testimonial-card h3 {
  margin: 0 0 4px;
  color: var(--color-midnight);
  font-family: var(--font-heading), Georgia, serif;
  font-size: 1.05rem;
  font-weight: 600;
}

.testimonial-card span {
  color: var(--color-gold-dark);
  font-size: 0.78rem;
  font-weight: 600;
}

/* ---------- FAQ ---------- */

.faq-container {
  display: flex;
  flex-direction: column;
  gap: 12px;
  max-width: 900px;
  margin: 44px auto 0;
}

.faq-card {
  overflow: hidden;
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: 16px;
  box-shadow: 0 7px 24px rgba(7, 24, 42, 0.045);
  transition:
    border-color 220ms ease,
    box-shadow 220ms ease;
}

.faq-card:hover {
  border-color: rgba(214, 166, 59, 0.48);
  box-shadow: 0 12px 30px rgba(7, 24, 42, 0.07);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 21px 23px;
  border: 0;
  background: transparent;
  color: var(--color-midnight);
  font-size: 0.98rem;
  font-weight: 650;
  text-align: left;
}

.faq-question:focus-visible,
.faq-card button:focus-visible {
  outline: 2px solid var(--color-gold);
  outline-offset: -2px;
}

.faq-icon {
  flex: 0 0 auto;
  display: grid;
  width: 30px;
  height: 30px;
  place-items: center;
  border: 1px solid rgba(214, 166, 59, 0.42);
  border-radius: 50%;
  color: var(--color-gold-dark);
  font-size: 1.1rem;
  font-weight: 600;
}

.faq-answer {
  padding: 0 23px 21px;
}

.faq-answer p {
  max-width: 780px;
  margin: 0;
  color: var(--color-muted);
  font-size: 0.9rem;
  line-height: 1.78;
}

/* ---------- Final CTA ---------- */

.cta-box {
  position: relative;
  overflow: hidden;
  padding: 82px 42px;
  text-align: center;
  border: 1px solid rgba(231, 195, 108, 0.28);
  border-radius: 30px;
  background:
    radial-gradient(circle at 15% 10%, rgba(231, 195, 108, 0.11), transparent 28%),
    radial-gradient(circle at 85% 85%, rgba(35, 73, 108, 0.3), transparent 35%),
    linear-gradient(135deg, var(--color-midnight), var(--color-navy));
  color: var(--color-white);
  box-shadow: 0 25px 60px rgba(7, 24, 42, 0.17);
}

.cta-box::before {
  content: "";
  position: absolute;
  width: 340px;
  height: 340px;
  top: -220px;
  right: -130px;
  border: 1px solid rgba(231, 195, 108, 0.1);
  border-radius: 50%;
  pointer-events: none;
}

.cta-box > * {
  position: relative;
  z-index: 1;
}

.cta-box .eyebrow {
  color: var(--color-gold-light);
}

.cta-box .section-heading {
  max-width: 800px;
  margin: 12px auto 22px;
  color: var(--color-white);
}

.cta-description {
  max-width: 700px;
  margin: 0 auto;
  color: rgba(255, 255, 255, 0.72);
  font-size: 1rem;
  line-height: 1.82;
}

.cta-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 34px;
}

/* ---------- Homepage responsive ---------- */

@media (max-width: 1050px) {
  .trust-grid,
  .testimonial-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .process-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .services-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .services-section {
    padding: 82px 0;
  }

  .trust-grid,
  .testimonial-grid,
  .process-grid {
    grid-template-columns: 1fr;
    gap: 16px;
  }

  .trust-card,
  .process-card,
  .testimonial-card {
    min-height: 0;
  }

  .services-grid {
    grid-template-columns: 1fr;
    gap: 16px;
    margin-top: 34px;
  }

  .service-home-card {
    min-height: 0;
    padding: 25px 23px;
  }

  .services-home-footer {
    flex-direction: column;
    align-items: stretch;
    margin-top: 42px;
    padding: 23px 21px;
    text-align: center;
  }

  .service-home-view-all {
    width: 100%;
  }

  .cta-box {
    padding: 60px 24px;
    border-radius: 24px;
  }

  .cta-actions {
    flex-direction: column;
  }

  .cta-actions .btn {
    width: 100%;
  }
}

@media (max-width: 420px) {
  .trust-card,
  .process-card,
  .testimonial-card {
    padding: 25px 21px;
  }

  .faq-question {
    padding: 18px 18px;
    font-size: 0.92rem;
  }

  .faq-answer {
    padding: 0 18px 18px;
  }

  .service-home-details {
    gap: 6px 10px;
  }

  .service-home-details span {
    font-size: 0.7rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .trust-card,
  .service-home-card,
  .process-card,
  .testimonial-card,
  .faq-card,
  .service-home-link,
  .service-home-link span,
  .services-home-spinner,
  .cta-box {
    transition: none !important;
    animation: none !important;
  }
}
