   ========================================================= */

.admin-settings-page {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
}


/* =========================================================
   HEADER
   ========================================================= */

.admin-settings-header {
  margin-bottom: 32px;
}

.admin-settings-eyebrow {
  margin-bottom: 8px;

  color: var(--color-gold-dark);

  font-size: 0.68rem;

  font-weight: 700;

  letter-spacing: 0.2em;
}

.admin-settings-header h1 {
  margin: 0;

  color: var(--color-midnight);

  font-family:
    var(--font-heading),
    Georgia,
