  font-size: 0.62rem;

  font-weight: 700;

  letter-spacing: 0.13em;
}

.admin-settings-info-item strong {
  min-width: 0;

  overflow-wrap: anywhere;

  color: var(--color-midnight);

  font-size: 0.88rem;

  font-weight: 600;
