   SMALL MOBILE
   ========================================================= */

@media (max-width: 380px) {

  .admin-settings-card {
    padding: 19px 15px;
  }

  .admin-settings-header h1 {
    font-size: 1.9rem;
  }

}

/* =========================================================
   BOOKING — GUIDED FLOW UI / UX PATCH
   ========================================================= */

.booking-flow-section {
  position: relative;
  max-width: 1180px;
  margin: 0 auto;
  padding: 64px 0;
  scroll-margin-top: 104px;
}

/* Compact, non-intrusive step indicator. */
.booking-flow-progress {
  position: sticky;
  top: 92px;
  z-index: 30;
  max-width: 980px;
  margin: 0 auto 18px;
  padding: 10px 14px;
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 6px;
  background: rgba(250, 247, 239, 0.94);
  border: 1px solid rgba(228, 218, 198, 0.9);
  border-radius: 16px;
  box-shadow: 0 10px 28px rgba(7, 24, 42, 0.07);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.booking-flow-progress-item {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 7px 5px;
  color: #aaa39a;
  font-size: 0.69rem;
  font-weight: 700;
  white-space: nowrap;
  transition: color 0.2s ease, background-color 0.2s ease;
}

.booking-flow-progress-item span {
  width: 24px;
  height: 24px;
  flex: 0 0 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  border: 1px solid rgba(164, 154, 139, 0.35);
  background: #f4efe4;
  color: #999287;
  font-size: 0.67rem;
}

.booking-flow-progress-item small {
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: 0.69rem;
  font-weight: 700;
}

.booking-flow-progress-item.is-active {
  color: var(--color-midnight);
}

.booking-flow-progress-item.is-active span {
  border-color: var(--color-gold);
  background: linear-gradient(135deg, var(--color-gold-light), var(--color-gold));
  color: var(--color-midnight);
  box-shadow: 0 4px 12px rgba(214, 166, 59, 0.2);
}

/* Assigned consultant card. */
.booking-assignment-card {
  max-width: 620px;
  margin: 36px auto 0;
  padding: 22px 26px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  column-gap: 22px;
  row-gap: 6px;
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: 18px;
  box-shadow: var(--shadow-soft);
}

.booking-assignment-card .booking-summary-label {
  grid-column: 1 / -1;
  margin: 0 0 2px;
  color: var(--color-gold-dark);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.booking-assignment-card strong {
  color: var(--color-midnight);
  font-family: var(--font-heading), Georgia, serif;
  font-size: 1.3rem;
  line-height: 1.2;
}

.booking-assignment-card span {
  display: block;
  color: var(--color-muted);
  font-size: 0.82rem;
}

.booking-assignment-card small {
  align-self: end;
  color: var(--color-gold-dark);
  font-size: 0.78rem;
  font-weight: 700;
  text-align: right;
  white-space: nowrap;
}

/* Loading / error / empty states. */
.booking-loading {
  max-width: 720px;
  margin: 28px auto;
  padding: 22px 24px;
  text-align: center;
  color: var(--color-muted);
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: 16px;
  box-shadow: var(--shadow-soft);
}

.booking-loading::before {
  content: "";
  display: inline-block;
  width: 17px;
  height: 17px;
  margin-right: 9px;
  vertical-align: -3px;
  border: 2px solid rgba(214, 166, 59, 0.2);
  border-top-color: var(--color-gold);
  border-radius: 50%;
  animation: bookingUiSpinner 0.8s linear infinite;
}

.booking-error {
  max-width: 760px;
  margin: 28px auto;
  padding: 26px;
  text-align: center;
  background: rgba(174, 75, 61, 0.045);
  border: 1px solid rgba(174, 75, 61, 0.2);
  border-radius: 18px;
}

.booking-error p {
  margin: 0 0 10px;
  color: var(--color-muted);
}

.booking-error p:first-child {
  color: var(--color-midnight);
  font-weight: 700;
}

.booking-error .btn {
  margin-top: 6px;
}

.booking-empty-state {
  max-width: 720px;
  margin: 34px auto;
  padding: 44px 26px;
  text-align: center;
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: 22px;
  box-shadow: var(--shadow-soft);
}

.booking-empty-state h3 {
  margin: 0 0 10px;
  color: var(--color-midnight);
  font-family: var(--font-heading), Georgia, serif;
  font-size: 1.45rem;
}

.booking-empty-state p {
  max-width: 560px;
  margin: 0 auto;
  color: var(--color-muted);
  line-height: 1.7;
}

/* Transition state classes used by the selectors. */
.booking-service-card-selecting,
.booking-mode-card-selecting,
.booking-date-option-selecting,
.booking-time-option-selecting {
  pointer-events: none;
  opacity: 0.74;
  transform: scale(0.99);
}

.booking-service-card:disabled,
.booking-mode-card:disabled,
.booking-date-option:disabled,
.booking-time-option:disabled {
  cursor: wait;
}

/* Cleaner next-action area. */
.booking-next {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
  margin-top: 36px;
}

/* Secure-payment overlay. */
.booking-payment-status {
  position: fixed;
  inset: 0;
  z-index: 5000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: rgba(7, 24, 42, 0.52);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}

.booking-payment-status-card {
  width: min(100%, 430px);
  padding: 32px 28px;
  text-align: center;
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: 22px;
  box-shadow: 0 25px 70px rgba(7, 24, 42, 0.28);
}

.booking-payment-status-card strong {
  display: block;
  color: var(--color-midnight);
  font-family: var(--font-heading), Georgia, serif;
  font-size: 1.3rem;
}

.booking-payment-status-card p {
  margin: 9px 0 0;
  color: var(--color-muted);
  line-height: 1.65;
  font-size: 0.88rem;
}

.booking-payment-spinner {
  width: 36px;
  height: 36px;
  display: block;
  margin: 0 auto 17px;
  border: 3px solid rgba(214, 166, 59, 0.2);
  border-top-color: var(--color-gold);
  border-radius: 50%;
  animation: bookingUiSpinner 0.8s linear infinite;
}

/* Review step additions. */
.booking-summary-meta {
  display: inline-block;
  margin-top: 5px;
  color: var(--color-gold-dark);
  font-size: 0.74rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.booking-summary-payment-note {
  margin-top: 24px;
  padding: 17px 19px;
  background: rgba(214, 166, 59, 0.07);
  border: 1px solid rgba(214, 166, 59, 0.18);
  border-radius: 14px;
}

.booking-summary-payment-note strong {
  color: var(--color-midnight);
  font-size: 0.87rem;
}

.booking-summary-payment-note p {
  margin: 5px 0 0;
  color: var(--color-muted);
  font-size: 0.81rem;
  line-height: 1.65;
}

.booking-summary-processing {
  margin: 11px 0 0;
  text-align: center;
  color: var(--color-muted);
  font-size: 0.81rem;
}

.booking-summary-action .btn:disabled {
  cursor: wait;
  transform: none;
  opacity: 0.65;
  box-shadow: none;
}

@keyframes bookingUiSpinner {
  to {
    transform: rotate(360deg);
  }
}

/* Guided booking spacing on smaller screens. */
@media (max-width: 900px) {
  .booking-flow-progress {
    top: 78px;
    display: flex;
    justify-content: flex-start;
    gap: 5px;
    overflow-x: auto;
    scrollbar-width: none;
  }

  .booking-flow-progress::-webkit-scrollbar {
    display: none;
  }

  .booking-flow-progress-item {
    flex: 0 0 auto;
    min-width: 86px;
  }

  .booking-flow-section {
    padding: 56px 0;
    scroll-margin-top: 86px;
  }
}

@media (max-width: 600px) {
  .booking-flow-progress {
    border-radius: 14px;
  }

  .booking-flow-progress-item {
    min-width: 78px;
    flex-direction: column;
    gap: 4px;
  }

  .booking-flow-progress-item small {
    font-size: 0.62rem;
  }

  .booking-assignment-card {
    grid-template-columns: 1fr;
    padding: 21px;
  }

  .booking-assignment-card small {
    grid-column: 1;
    text-align: left;
  }

  .booking-payment-status-card {
    padding: 28px 21px;
  }

  .booking-next {
    flex-direction: column;
    width: 100%;
  }

  .booking-next .btn {
    width: min(100%, 360px);
  }
}

@media (max-width: 430px) {
  .booking-flow-section {
    padding: 46px 0;
  }

  .booking-assignment-card strong {
    font-size: 1.15rem;
  }
}


/* =========================================================
   BOOKING — RESPONSIVE / MOBILE-FIRST REFINEMENT
   Final responsive layer for the guided booking experience.
   ========================================================= */

.booking-flow-section {
  width: min(100%, 1180px);
  box-sizing: border-box;
  padding-inline: 20px;
}

.booking-flow-progress {
  box-sizing: border-box;
  width: min(calc(100% - 40px), 980px);
}

.booking-service-card,
.booking-mode-card,
.booking-date-option,
.booking-time-option,
.booking-form-group input,
.booking-form-group select,
.booking-form-group textarea,
.booking-summary-action .btn,
.booking-next .btn {
  -webkit-tap-highlight-color: transparent;
}

.booking-service-card,
.booking-mode-card,
.booking-date-option,
.booking-time-option,
.btn {
  touch-action: manipulation;
}

.booking-service-card:focus-visible,
.booking-mode-card:focus-visible,
.booking-date-option:focus-visible,
.booking-time-option:focus-visible,
.booking-next .btn:focus-visible,
.booking-summary-action .btn:focus-visible {
