/* =========================================================
   BOOKING — CUSTOMER VALIDATION
   ========================================================= */

.booking-field-error {
  margin: 4px 0 0;

  color: #a24e42;

  font-size: 0.76rem;

  line-height: 1.45;

  font-weight: 600;
}

.booking-input-invalid {
  border-color: #b75b4f !important;

  background:
    rgba(174, 75, 61, 0.035) !important;

  box-shadow:
    0 0 0 3px
    rgba(174, 75, 61, 0.08) !important;
}

.booking-input-invalid:focus {
  border-color: #a24e42 !important;

  box-shadow:
    0 0 0 3px
    rgba(174, 75, 61, 0.12) !important;
}

.booking-form-help {
  display: block;

  margin-top: 4px;

  color: var(--color-muted);

  font-size: 0.74rem;

  line-height: 1.5;
}

.booking-next .booking-form-help {
  width: 100%;

  max-width: 620px;

  margin: 8px auto 0;

  text-align: center;
}

/* Improve disabled review action without changing
   the site's existing button language. */

.booking-next .btn:disabled {
  cursor: not-allowed;

  opacity: 0.58;

  transform: none;

  box-shadow: none;
}

/* Keep validation readable on smaller screens. */

@media (max-width: 600px) {
  .booking-field-error {
    font-size: 0.74rem;
  }

  .booking-form-help {
    font-size: 0.72rem;
  }
}

/* Respect reduced-motion users. */

@media (prefers-reduced-motion: reduce) {
  .booking-input-invalid,
  .booking-input-invalid:focus {
    transition: none;
  }
}


