/* =========================================================
   ADMIN CONSULTANT AVAILABILITY CALENDAR
   Matches ConsultantAvailabilityCalendar.tsx
   ========================================================= */

.admin-availability-calendar {
  margin-top: 28px;
  padding: 28px;
  border: 1px solid var(--color-border);
  border-radius: 22px;
  background: var(--color-surface);
  box-shadow: 0 18px 40px rgba(23, 28, 45, 0.06);
}

.admin-availability-calendar-header,
.admin-availability-calendar-toolbar,
.admin-availability-day-view-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
}

.admin-availability-calendar-header h2,
.admin-availability-calendar-header h3,
.admin-availability-day-view-header h3 {
  margin: 0;
}

.admin-availability-calendar-header p {
  margin: 7px 0 0;
  color: var(--color-muted);
  max-width: 650px;
}

.admin-consultants-eyebrow {
  display: inline-block;
  margin-bottom: 6px;
  font-size: 0.72rem;
  letter-spacing: 0.16em;
  font-weight: 800;
  color: var(--color-gold-dark);
}

.admin-availability-calendar-controls,
.admin-availability-view-toggle,
.admin-availability-month-controls,
.admin-availability-legend {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.admin-availability-calendar-controls button,
.admin-availability-calendar-controls select,
.admin-availability-view-toggle button,
.admin-availability-month-controls button,
.admin-availability-edit {
  min-height: 40px;
  border: 1px solid var(--color-border);
  border-radius: 10px;
  background: var(--color-white);
  padding: 0 12px;
  color: var(--color-midnight);
  font: inherit;
  cursor: pointer;
  transition:
    border-color 160ms ease,
    background 160ms ease,
    transform 160ms ease;
}

.admin-availability-calendar-controls select {
  min-width: 190px;
}

.admin-availability-calendar-controls button:hover,
.admin-availability-view-toggle button:hover,
.admin-availability-month-controls button:hover,
.admin-availability-edit:hover {
  border-color: var(--color-gold);
}

.admin-availability-view-toggle button.is-active {
  background: var(--color-midnight);
  color: var(--color-white);
  border-color: var(--color-midnight);
}

.admin-availability-edit {
  background: var(--color-gold);
  border-color: var(--color-gold);
  color: var(--color-midnight);
  font-weight: 800;
}

.admin-availability-edit:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.admin-availability-calendar-toolbar {
  margin-top: 22px;
  padding-top: 18px;
  border-top: 1px solid var(--color-border);
}

.admin-availability-legend {
  margin: 18px 0;
  color: var(--color-muted);
  font-size: 0.78rem;
}

.admin-availability-legend span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
}

.admin-availability-legend i,
.admin-availability-day-state i {
  width: 9px;
  height: 9px;
  display: inline-block;
  flex: 0 0 9px;
  border-radius: 999px;
}

.admin-availability-legend i.is-available,
.admin-availability-day-state i.is-available {
  background: #4f8a66;
}

.admin-availability-legend i.is-booked,
.admin-availability-day-state i.is-booked {
  background: #b85d52;
}

.admin-availability-legend i.is-empty {
  background: var(--color-border);
}

.admin-availability-calendar-loading,
.admin-availability-calendar-error,
.admin-availability-empty-day {
  padding: 14px 16px;
  border-radius: 12px;
  margin-top: 14px;
}

.admin-availability-calendar-loading {
  background: rgba(214, 166, 59, 0.08);
}

.admin-availability-calendar-error {
  background: rgba(184, 93, 82, 0.08);
  color: #8d463d;
}

.admin-availability-empty-day {
  display: grid;
  gap: 5px;
  background: rgba(31, 38, 56, 0.04);
  color: var(--color-muted);
}

.admin-availability-empty-day strong {
  color: var(--color-midnight);
}

.admin-availability-month-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  border-top: 1px solid var(--color-border);
  border-left: 1px solid var(--color-border);
  overflow: hidden;
  border-radius: 16px;
}

.admin-availability-weekday {
  min-width: 0;
  padding: 10px 12px;
  background: rgba(31, 38, 56, 0.035);
  border-right: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
  color: var(--color-muted);
  font-size: 0.72rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.admin-availability-day {
  position: relative;
  min-height: 112px;
  width: 100%;
  padding: 11px;
  text-align: left;
  border: 0;
  border-right: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
  background: var(--color-white);
  color: var(--color-midnight);
  cursor: pointer;
}

.admin-availability-day:hover,
.admin-availability-day.is-selected {
  background: rgba(214, 166, 59, 0.07);
}

.admin-availability-day.is-outside {
  opacity: 0.42;
}

.admin-availability-day-number {
  display: block;
  margin-bottom: 9px;
  font-weight: 800;
}

.admin-availability-day-state {
  display: flex;
  gap: 6px;
  min-height: 10px;
}

.admin-availability-day-state i.is-available {
  box-shadow: 0 0 0 3px rgba(79, 138, 102, 0.08);
}

.admin-availability-day-state i.is-booked {
  box-shadow: 0 0 0 3px rgba(184, 93, 82, 0.08);
}

.admin-availability-day .is-booked-text {
  display: block;
  margin-top: 8px;
  color: #8d463d;
  font-size: 0.68rem;
  font-weight: 800;
}

.admin-availability-day-view {
  margin-top: 18px;
  padding: 20px;
  border: 1px solid var(--color-border);
  border-radius: 16px;
  background: var(--color-white);
}

.admin-availability-day-view-header {
  padding-bottom: 16px;
  border-bottom: 1px solid var(--color-border);
}

.admin-availability-timeline {
  display: grid;
  gap: 10px;
  margin-top: 16px;
}

.admin-availability-timeline-row {
  display: grid;
  grid-template-columns: 82px minmax(0, 1fr);
  gap: 14px;
  align-items: stretch;
}

.admin-availability-timeline-time {
  padding-top: 12px;
  color: var(--color-muted);
  font-size: 0.78rem;
  font-weight: 800;
  text-align: right;
}

.admin-availability-timeline-slot {
  min-width: 0;
}

.admin-availability-free-card,
.admin-availability-booked-card {
  min-height: 58px;
  padding: 12px 14px;
  border-radius: 12px;
  border: 1px solid var(--color-border);
}

.admin-availability-free-card {
  background: rgba(79, 138, 102, 0.07);
  border-left: 4px solid #4f8a66;
}

.admin-availability-booked-card {
  background: rgba(184, 93, 82, 0.08);
  border-left: 4px solid #b85d52;
}

.admin-availability-free-card strong,
.admin-availability-booked-card strong,
.admin-availability-free-card span,
.admin-availability-booked-card span,
.admin-availability-free-card small,
.admin-availability-booked-card small {
  display: block;
}

.admin-availability-free-card strong {
  color: #356f4b;
}

.admin-availability-booked-card strong {
  color: #8d463d;
}

.admin-availability-free-card span,
.admin-availability-booked-card span {
  margin-top: 3px;
  font-size: 0.78rem;
}

.admin-availability-free-card small,
.admin-availability-booked-card small {
  margin-top: 5px;
  color: var(--color-muted);
  font-size: 0.68rem;
}

@media (max-width: 960px) {
  .admin-availability-calendar-header,
  .admin-availability-calendar-toolbar,
  .admin-availability-day-view-header {
    align-items: flex-start;
    flex-direction: column;
  }

  .admin-availability-calendar-controls,
  .admin-availability-view-toggle,
  .admin-availability-month-controls {
    width: 100%;
  }

  .admin-availability-calendar-controls select {
    width: 100%;
  }
