@media (max-width: 720px) {
  .admin-availability-calendar {
    padding: 18px;
    border-radius: 16px;
  }

  .admin-availability-month-grid {
    overflow-x: auto;
    grid-template-columns: repeat(7, minmax(100px, 1fr));
