  text-align: left;
  cursor: pointer;
}

.admin-availability-day:hover {
  background: rgba(214, 166, 59, 0.055);
}

.admin-availability-day.is-selected {
  background:
    linear-gradient(
      180deg,
      rgba(214, 166, 59, 0.11),
      rgba(255, 255, 255, 0.98)
    );
  box-shadow:
    inset 0 0 0 2px var(--color-gold);
}

.admin-availability-day.is-outside {
  opacity: 0.38;
}

.admin-availability-day-number {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 28px;
  height: 28px;
  margin-bottom: 9px;
  border-radius: 50%;
  font-size: 0.76rem;
  font-weight: 850;
}

.admin-availability-day.is-selected
  .admin-availability-day-number {
  background: var(--color-gold);
}

.admin-availability-day-state {
  display: flex;
  gap: 6px;
  min-height: 9px;
}

.admin-availability-day-state i {
  width: 7px;
  height: 7px;
  border-radius: 999px;
}

.admin-availability-day small {
  display: block;
  margin-top: 8px;
  color: var(--color-muted);
  font-size: 0.63rem;
  line-height: 1.35;
}

.admin-availability-day .is-booked-text {
  color: #8d463d;
  font-weight: 750;
}

.admin-availability-day-view {
  padding: 20px;
  border: 1px solid var(--color-border);
  border-radius: 18px;
  background: var(--color-white);
}

.admin-availability-day-view-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding-bottom: 15px;
  border-bottom: 1px solid var(--color-border);
}

.admin-availability-day-view-header h3 {
  margin: 4px 0 0;
  color: var(--color-midnight);
  font-size: 1rem;
}

.admin-availability-day-view-header small {
  display: block;
  margin-top: 5px;
  color: var(--color-muted);
  font-size: 0.68rem;
}

.admin-availability-secondary-button {
  padding: 0 13px;
  border: 1px solid var(--color-border);
  background: var(--color-white);
  color: var(--color-midnight);
  cursor: pointer;
}

.admin-availability-selection-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 14px;
  padding: 12px 14px;
  border: 1px solid rgba(214, 166, 59, 0.35);
  border-radius: 12px;
  background: rgba(214, 166, 59, 0.08);
  color: var(--color-midnight);
  font-size: 0.75rem;
  font-weight: 750;
}

.admin-availability-selection-banner button {
  padding: 0 12px;
  border: 1px solid var(--color-midnight);
  background: var(--color-midnight);
  color: var(--color-white);
  cursor: pointer;
}

.admin-availability-window-list {
  display: grid;
  gap: 9px;
  margin: 16px 0;
}

.admin-availability-window-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 13px 14px;
  border: 1px solid rgba(79, 138, 102, 0.26);
  border-left: 4px solid #4f8a66;
  border-radius: 13px;
  background: rgba(79, 138, 102, 0.07);
}

.admin-availability-window-card strong,
.admin-availability-window-card span {
  display: block;
}

.admin-availability-window-card strong {
  color: #356f4b;
  font-size: 0.78rem;
}

.admin-availability-window-card span {
  margin-top: 4px;
  color: var(--color-muted);
  font-size: 0.68rem;
}

.admin-availability-window-card button {
  min-height: 34px;
  padding: 0 11px;
  border: 1px solid rgba(184, 93, 82, 0.22);
  border-radius: 9px;
  background: rgba(184, 93, 82, 0.06);
  color: #8d463d;
  font: inherit;
  font-size: 0.68rem;
  font-weight: 800;
  cursor: pointer;
}

.admin-availability-time-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  max-height: 590px;
  overflow-y: auto;
  padding: 3px;
}

.admin-availability-time-cell {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: 60px;
  padding: 10px 11px;
  border: 1px solid var(--color-border);
  border-radius: 11px;
  background: var(--color-white);
  color: var(--color-midnight);
  text-align: left;
  cursor: pointer;
}

.admin-availability-time-cell span,
.admin-availability-time-cell small {
  display: block;
}

.admin-availability-time-cell span {
  font-size: 0.73rem;
  font-weight: 850;
}

.admin-availability-time-cell small {
  color: var(--color-muted);
  font-size: 0.61rem;
  font-weight: 700;
}

.admin-availability-time-cell.is-available {
  border-color: rgba(79, 138, 102, 0.3);
  background: rgba(79, 138, 102, 0.08);
}

.admin-availability-time-cell.is-booked {
  border-color: rgba(184, 93, 82, 0.25);
  background: rgba(184, 93, 82, 0.085);
  color: #8d463d;
  cursor: not-allowed;
}

.admin-availability-time-cell.is-held {
  border-color: rgba(154, 122, 45, 0.28);
  background: rgba(154, 122, 45, 0.09);
  color: #7d641f;
  cursor: not-allowed;
}

.admin-availability-time-cell.is-selected-range {
  border-color: var(--color-gold);
  background: rgba(214, 166, 59, 0.18);
  box-shadow: inset 0 0 0 1px var(--color-gold);
}

.admin-availability-booking-cards {
  display: grid;
  gap: 10px;
  margin-top: 18px;
}

.admin-availability-booked-card,
.admin-availability-hold-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 14px 16px;
  border-radius: 13px;
}

.admin-availability-booked-card {
  border: 1px solid rgba(184, 93, 82, 0.2);
  border-left: 4px solid #b85d52;
  background: rgba(184, 93, 82, 0.07);
}

.admin-availability-hold-card {
  border: 1px solid rgba(154, 122, 45, 0.22);
  border-left: 4px solid #9a7a2d;
  background: rgba(154, 122, 45, 0.07);
}

.admin-availability-booked-card strong,
.admin-availability-hold-card strong,
.admin-availability-booked-card span,
.admin-availability-hold-card span,
.admin-availability-booked-card small,
.admin-availability-hold-card small {
  display: block;
}

.admin-availability-booked-card strong {
  color: #8d463d;
  font-size: 0.62rem;
  letter-spacing: 0.1em;
}

.admin-availability-hold-card strong {
  color: #7d641f;
  font-size: 0.62rem;
  letter-spacing: 0.1em;
}

.admin-availability-booked-card span,
.admin-availability-hold-card span {
  margin-top: 3px;
  color: var(--color-midnight);
  font-size: 0.77rem;
  font-weight: 800;
}

.admin-availability-booked-card small,
.admin-availability-hold-card small {
  margin-top: 4px;
  color: var(--color-muted);
  font-size: 0.67rem;
}

.admin-availability-booking-id {
  color: var(--color-muted) !important;
  font-size: 0.63rem !important;
  white-space: nowrap;
}

.admin-availability-empty-day {
  padding: 22px;
  border: 1px solid var(--color-border);
  border-radius: 14px;
  background: rgba(31, 38, 56, 0.025);
  color: var(--color-muted);
  font-size: 0.76rem;
}

.admin-availability-unsaved-bar {
  position: sticky;
  bottom: 16px;
  z-index: 8;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-top: 18px;
  padding: 12px 14px;
  border: 1px solid var(--color-gold);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.96);
  box-shadow:
    0 14px 32px rgba(23, 28, 45, 0.12);
  backdrop-filter: blur(9px);
  color: var(--color-midnight);
  font-size: 0.74rem;
  font-weight: 750;
}

.admin-availability-unsaved-bar button {
  min-height: 36px;
  padding: 0 13px;
  border: 0;
  border-radius: 9px;
  background: var(--color-midnight);
  color: var(--color-white);
  font: inherit;
  font-size: 0.69rem;
  font-weight: 800;
  cursor: pointer;
}

.admin-consultant-calendar-management-note {
  display: grid;
  gap: 7px;
  margin-top: 15px;
  padding: 15px 17px;
  border: 1px solid rgba(214, 166, 59, 0.25);
  border-radius: 14px;
  background: rgba(214, 166, 59, 0.06);
}

.admin-consultant-calendar-management-note strong {
  color: var(--color-midnight);
  font-size: 0.8rem;
}

.admin-consultant-calendar-management-note span {
  color: var(--color-muted);
  font-size: 0.72rem;
  line-height: 1.5;
}

.admin-consultant-calendar-management-note button {
  justify-self: start;
  min-height: 36px;
  margin-top: 2px;
  padding: 0 12px;
  border: 1px solid var(--color-border);
  border-radius: 9px;
  background: var(--color-white);
  color: var(--color-midnight);
  font: inherit;
  font-size: 0.69rem;
  font-weight: 800;
  cursor: pointer;
}

.admin-consultant-availability-summary {
  display: grid;
  gap: 8px;
  margin-top: 14px;
}

.admin-consultant-availability-summary-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 10px 12px;
  border: 1px solid var(--color-border);
  border-radius: 10px;
  background: rgba(31, 38, 56, 0.025);
}

.admin-consultant-availability-summary-item strong,
.admin-consultant-availability-summary-item span {
  font-size: 0.72rem;
}

.admin-consultant-availability-summary-item strong {
  color: var(--color-midnight);
}

.admin-consultant-availability-summary-item span {
  color: var(--color-muted);
  text-align: right;
}

@media (max-width: 1020px) {
  .admin-availability-calendar-header,
  .admin-availability-calendar-toolbar {
    align-items: flex-start;
    flex-direction: column;
  }

  .admin-availability-calendar-toolbar > *,
  .admin-availability-calendar-controls {
    width: 100%;
  }

  .admin-availability-calendar-controls {
    justify-content: flex-start;
  }
}

@media (max-width: 900px) {
  .admin-availability-time-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 680px) {
  .admin-availability-calendar {
    padding: 18px;
    border-radius: 18px;
  }

  .admin-availability-month-grid {
    overflow-x: auto;
    grid-template-columns: repeat(7, minmax(100px, 1fr));
  }

  .admin-availability-weekday,
  .admin-availability-day {
    min-width: 100px;
  }

  .admin-availability-day {
    min-height: 100px;
  }

  .admin-availability-day-view {
    padding: 15px;
  }

  .admin-availability-day-view-header {
    align-items: flex-start;
    flex-direction: column;
  }

  .admin-availability-time-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    max-height: 520px;
  }

  .admin-availability-time-cell {
    min-height: 58px;
    flex-direction: column;
    align-items: flex-start;
  }

  .admin-availability-selection-banner,
  .admin-availability-window-card,
  .admin-availability-booked-card,
  .admin-availability-hold-card,
  .admin-availability-unsaved-bar,
  .admin-consultant-availability-summary-item {
    align-items: flex-start;
    flex-direction: column;
  }

  .admin-consultant-availability-summary-item span {
    text-align: left;
  }
}

@media (max-width: 420px) {
  .admin-availability-time-grid {
    grid-template-columns: 1fr;
  }

  .admin-availability-calendar-controls select {
    width: 100%;
  }
}

/* =========================================================
   AVAILABILITY TIME DISPLAY — AM/PM
   ========================================================= */

.admin-availability-time-cell span {
  white-space: nowrap;
}

.admin-availability-time-cell small {
  white-space: nowrap;
}

.booking-time-option,
.booking-time-option span {
  white-space: nowrap;
}

@media (max-width: 480px) {
  .admin-availability-time-cell {
    gap: 5px;
  }

  .admin-availability-time-cell span {
    font-size: 0.72rem;
  }

  .admin-availability-time-cell small {
    font-size: 0.58rem;
  }
}
/* =========================================================
   REPLACE DAY AVAILABILITY ACTIONS
   ========================================================= */

.admin-availability-day-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.admin-availability-replace-day-button {
  min-height: 42px;
  padding: 0 16px;
  border: 1px solid var(--color-gold);
  border-radius: 11px;
  background: var(--color-gold);
  color: var(--color-midnight);
  font: inherit;
  font-size: 0.75rem;
  font-weight: 850;
  cursor: pointer;
  box-shadow:
    0 8px 20px rgba(214, 166, 59, 0.2);
  transition:
    transform 160ms ease,
    box-shadow 160ms ease,
    background 160ms ease;
}

.admin-availability-replace-day-button:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow:
    0 11px 25px rgba(214, 166, 59, 0.28);
}

.admin-availability-replace-day-button:focus-visible {
  outline: none;
  box-shadow:
    0 0 0 3px rgba(214, 166, 59, 0.2),
    0 8px 20px rgba(214, 166, 59, 0.2);
}

.admin-availability-replace-day-button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.admin-availability-selection-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.admin-availability-selection-banner > div {
  display: grid;
  gap: 4px;
}

.admin-availability-selection-banner strong {
  color: var(--color-midnight);
}

.admin-availability-selection-banner span {
  color: var(--color-muted);
  font-size: 0.7rem;
}

@media (max-width: 680px) {
  .admin-availability-day-actions,
  .admin-availability-selection-banner {
    width: 100%;
    align-items: stretch;
    flex-direction: column;
  }

  .admin-availability-replace-day-button {
    width: 100%;
  }
}
/* =========================================================
   ACCOUNT DROPDOWN
   ========================================================= */

.navbar-account {
  position: relative;
  display: flex;
  align-items: center;
}

.navbar-account-trigger {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-width: 145px;
  height: 58px;
  cursor: pointer;
}

.navbar-account-menu {
  position: absolute;
  top: calc(100% + 10px);
  right: 0;

  width: 220px;
  padding: 8px;

  background: #ffffff;
  border: 1px solid rgba(214, 166, 59, 0.35);
  border-radius: 14px;

  box-shadow:
    0 18px 45px rgba(0, 0, 0, 0.18),
    0 4px 14px rgba(0, 0, 0, 0.08);

  z-index: 9999;

  display: flex;
  flex-direction: column;

  animation: navbarAccountMenuIn 0.18s ease-out;
}

.navbar-account-menu a {
  display: flex;
  align-items: center;

  width: 100%;
  min-height: 46px;
  padding: 11px 14px;

  box-sizing: border-box;

  color: #07182a !important;
  background: transparent;

  text-decoration: none;
  font-size: 15px;
  font-weight: 600;

  border-radius: 9px;

  transition:
    background-color 0.18s ease,
    color 0.18s ease,
    transform 0.18s ease;
}

.navbar-account-menu button {
  display: flex;
  align-items: center;

  width: 100%;
  min-height: 46px;
  padding: 11px 14px;

  box-sizing: border-box;

  color: #07182a !important;
  background: transparent;

  border: none;
  border-radius: 9px;

  font: inherit;
  font-size: 15px;
  font-weight: 600;

  text-align: left;
  cursor: pointer;

  transition:
    background-color 0.18s ease,
    color 0.18s ease,
    transform 0.18s ease;
}

.navbar-account-menu a:hover,
.navbar-account-menu button:hover:not(:disabled) {
  background: #faf7ef;
  color: #ad7c1d !important;
  transform: translateX(2px);
}

.navbar-account-menu button:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.navbar-account-menu a + a,
.navbar-account-menu a + button,
.navbar-account-menu button + a,
.navbar-account-menu button + button {
  margin-top: 2px;
}

@keyframes navbarAccountMenuIn {
  from {
    opacity: 0;
    transform: translateY(-6px) scale(0.98);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@media (max-width: 768px) {
  .navbar-account-menu {
    right: -10px;
    width: 205px;
  }

  .navbar-account-trigger {
    min-width: 125px;
  }
}
/* =========================================================
   GUEST BOOKING TRACKING PAGE
   ========================================================= */

.guest-track-card {
  width: min(100%, 1080px);
  margin: 0 auto;

  overflow: hidden;

  background: #fffdf9;
  border: 1px solid #e4dac6;
  border-radius: 22px;

  box-shadow:
    0 24px 60px rgba(7, 24, 42, 0.08),
    0 4px 16px rgba(7, 24, 42, 0.04);
}

/* Header inside tracking card */

.guest-track-card .booking-header {
  padding: 42px 48px 34px;
  text-align: center;
}

.guest-track-card .booking-header .eyebrow {
  margin-bottom: 12px;

  color: #ad7c1d;

  font-size: 12px;
  font-weight: 800;
  letter-spacing: 2.5px;
  text-transform: uppercase;
}

.guest-track-card .booking-header .section-heading {
  margin: 0 auto 14px;

  color: #07182a;

  font-size: clamp(34px, 4vw, 52px);
  line-height: 1.08;
}

.guest-track-card .booking-header .section-description {
  max-width: 700px;
  margin: 0 auto;

  color: #6f6a61;

  font-size: 16px;
  line-height: 1.65;
}

/* Divider */

.guest-track-card .booking-summary-divider {
  width: 100%;
  height: 1px;

  margin: 0;

  background: #e8decd;
}

/* =========================================================
   REQUEST FORM
   ========================================================= */

.guest-track-form {
  display: grid;

  grid-template-columns:
    minmax(0, 1fr)
    minmax(0, 1fr);

  gap: 22px;

  padding: 34px 42px 38px;
}

/* Every form label becomes a proper field */

.guest-track-form > label {
  display: flex;
  flex-direction: column;
  gap: 9px;

  min-width: 0;

  color: #07182a;

  font-size: 14px;
  font-weight: 700;
  line-height: 1.4;
}

/* Inputs */

.guest-track-form > label input {
  width: 100%;
  height: 56px;

  box-sizing: border-box;

  padding: 0 16px;

  border: 1px solid #d8cebc;
  border-radius: 11px;

  background: #ffffff;

  color: #07182a;

  font-family: inherit;
  font-size: 15px;

  outline: none;

  transition:
    border-color 0.2s ease,
    box-shadow 0.2s ease,
    background-color 0.2s ease,
    transform 0.2s ease;
}

.guest-track-form > label input::placeholder {
  color: #9a9389;
}

.guest-track-form > label input:hover {
  border-color: #c9baa2;
}

.guest-track-form > label input:focus {
  border-color: #d6a63b;

  background: #fffefa;

  box-shadow:
    0 0 0 4px rgba(214, 166, 59, 0.13);

  transform: translateY(-1px);
}

/* =========================================================
   PRIMARY FORM BUTTON
   ========================================================= */

.guest-track-form > button.btn-primary {
  grid-column: 1 / -1;

  justify-self: center;

  min-width: 250px;
  min-height: 54px;

  padding: 0 28px;

  border-radius: 11px;

  font-weight: 700;

  box-shadow:
    0 10px 24px rgba(214, 166, 59, 0.20);

  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease,
    background-color 0.2s ease;
}

.guest-track-form > button.btn-primary:hover:not(:disabled) {
  transform: translateY(-2px);

  box-shadow:
    0 15px 30px rgba(214, 166, 59, 0.28);
}

/* Error/help messages should span the form */

.guest-track-form .booking-error,
.guest-track-form .booking-form-help {
  grid-column: 1 / -1;

  margin: -4px 0 0;
}

/* =========================================================
   OTP STEP
   ========================================================= */

.guest-track-otp-label {
  grid-column: 1 / -1;

  text-align: center;

  color: #6f6a61;

  font-size: 15px;
  font-weight: 600;
}

.guest-track-otp-input {
  grid-column: 1 / -1;

  width: min(100%, 330px);
  height: 68px;

  margin: 0 auto;

  padding: 0 20px;

  box-sizing: border-box;

  border: 1px solid #d6a63b;
  border-radius: 14px;

  background: #ffffff;

  color: #07182a;

  font-size: 30px;
  font-weight: 800;
  letter-spacing: 10px;

  text-align: center;

  outline: none;

  box-shadow:
    0 8px 24px rgba(7, 24, 42, 0.06);
}

.guest-track-otp-input:focus {
  box-shadow:
    0 0 0 4px rgba(214, 166, 59, 0.14),
    0 10px 28px rgba(7, 24, 42, 0.08);
}

/* =========================================================
   RESULT
   ========================================================= */

.guest-track-result {
  padding-bottom: 40px;
}

.guest-track-result > .booking-header {
  padding-bottom: 30px;
}

.guest-track-result
  .booking-summary-section {
  padding: 28px 42px 10px;
}

.guest-track-result
  .booking-summary-grid {
  display: grid;

  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 20px;

  padding: 26px 42px;
}

.guest-track-result
  .booking-summary-item {
  min-width: 0;
}

.guest-track-result
  .booking-summary-item span {
  display: block;

  margin-bottom: 7px;

  color: #847b6e;

  font-size: 13px;
  font-weight: 600;
}

.guest-track-result
  .booking-summary-item strong {
  color: #07182a;

  font-size: 16px;
  line-height: 1.45;
}

.guest-track-result
  .booking-summary-service {
  margin: 6px 0 0;

  color: #07182a;

  font-size: 24px;
  line-height: 1.3;
}

.guest-track-result
  .booking-form-help {
  margin: 0 42px;
}

/* Result buttons */

.guest-track-result .booking-next {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;

  gap: 14px;

  padding: 28px 42px 0;
}

/* =========================================================
   ACCOUNT BUTTON FINAL POLISH
   ========================================================= */

.navbar-account-trigger {
  position: relative;

  min-width: 150px;
  height: 58px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  gap: 9px;

  padding: 0 22px;

  border: 1px solid rgba(255, 255, 255, 0.68);
  border-radius: 12px;

  background:
    linear-gradient(
      180deg,
      rgba(255, 255, 255, 0.055),
      rgba(255, 255, 255, 0.025)
    );

  color: #ffffff !important;

  font-size: 16px;
  font-weight: 700;

  cursor: pointer;

  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.06);

  transition:
    color 0.2s ease,
    background 0.2s ease,
    border-color 0.2s ease,
    box-shadow 0.2s ease,
    transform 0.2s ease;
}

.navbar-account-trigger:hover {
  border-color: #d6a63b;

  background:
    linear-gradient(
      180deg,
      rgba(214, 166, 59, 0.16),
      rgba(214, 166, 59, 0.07)
    );

  color: #f7d77a !important;

  box-shadow:
    0 0 0 1px rgba(214, 166, 59, 0.15),
    0 10px 26px rgba(0, 0, 0, 0.16);

  transform: translateY(-1px);
}

.navbar-account-trigger[aria-expanded="true"] {
  border-color: #d6a63b;

  background:
    linear-gradient(
      180deg,
      rgba(214, 166, 59, 0.18),
      rgba(214, 166, 59, 0.08)
    );

  color: #f7d77a !important;

  box-shadow:
    0 0 0 1px rgba(214, 166, 59, 0.18),
    0 12px 28px rgba(0, 0, 0, 0.18);
}

.navbar-account-trigger span {
  display: inline-flex;

  font-size: 13px;

  transition:
    transform 0.2s ease;
}

.navbar-account-trigger[aria-expanded="true"] span {
  transform: rotate(180deg);
}

