/* =========================================================
   SHARED AVAILABILITY CALENDAR — STEP 1
   Presentational shell only. Existing admin/client data flow
   remains outside this component.
   ========================================================= */

.shared-availability-calendar {
  margin-top: 28px;
  padding: 30px;
  border: 1px solid var(--color-border);
  border-radius: 24px;
  background: linear-gradient(
    180deg,
    var(--color-white) 0%,
    rgba(31, 38, 56, 0.018) 100%
  );
  box-shadow: 0 18px 42px rgba(23, 28, 45, 0.07);
}

.shared-availability-calendar-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.shared-availability-view-toggle,
.shared-availability-month-controls {
  display: flex;
  align-items: center;
  gap: 8px;
}

.shared-availability-view-toggle button,
.shared-availability-month-controls button {
  min-height: 38px;
  padding: 0 12px;
  border: 1px solid var(--color-border);
  border-radius: 9px;
  background: var(--color-white);
  color: var(--color-midnight);
  font: inherit;
  font-size: 0.72rem;
  font-weight: 800;
  cursor: pointer;
}

.shared-availability-view-toggle button.is-active {
  background: var(--color-midnight);
  color: var(--color-white);
  border-color: var(--color-midnight);
}

.shared-availability-month-controls strong {
  min-width: 150px;
  text-align: center;
  color: var(--color-midnight);
  font-size: 0.9rem;
}

.shared-availability-today {
  background: var(--color-gold) !important;
  border-color: var(--color-gold) !important;
  color: var(--color-midnight) !important;
}

.shared-availability-legend {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
  margin: 18px 2px;
  color: var(--color-muted);
  font-size: 0.71rem;
}

.shared-availability-legend span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
}

.shared-availability-legend i,
.shared-availability-day-state i {
  width: 8px;
  height: 8px;
  flex: 0 0 8px;
  border-radius: 999px;
  display: inline-block;
}

.shared-availability-legend i.is-available,
.shared-availability-day-state i.is-available {
  background: #4f8a66;
}

.shared-availability-legend i.is-booked,
.shared-availability-day-state i.is-booked {
  background: #b85d52;
}

.shared-availability-legend i.is-hold,
.shared-availability-day-state i.is-hold {
  background: #9a7a2d;
}

.shared-availability-legend i.is-selected {
  background: var(--color-gold);
}

.shared-availability-legend i.is-empty {
  background: var(--color-border);
}

.shared-availability-message {
  margin-top: 14px;
  padding: 12px 14px;
  border-radius: 12px;
  font-size: 0.78rem;
  line-height: 1.5;
}

.shared-availability-loading {
  border: 1px solid var(--color-border);
  background: var(--color-white);
  color: var(--color-muted);
}

.shared-availability-error {
  border: 1px solid rgba(184, 93, 82, 0.2);
  background: rgba(184, 93, 82, 0.08);
  color: #8d463d;
}

.shared-availability-empty,
.shared-availability-empty-day {
  border: 1px solid var(--color-border);
  background: rgba(31, 38, 56, 0.025);
  color: var(--color-muted);
}

.shared-availability-month-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  overflow: hidden;
  border: 1px solid var(--color-border);
  border-radius: 18px;
  background: var(--color-border);
  gap: 1px;
}

.shared-availability-weekday {
  min-width: 0;
  padding: 10px 11px;
  background: rgba(31, 38, 56, 0.045);
  color: var(--color-muted);
  font-size: 0.66rem;
  font-weight: 850;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.shared-availability-day {
  position: relative;
  min-height: 112px;
  width: 100%;
  padding: 11px;
  border: 0;
  background: var(--color-white);
  color: var(--color-midnight);
  text-align: left;
  cursor: pointer;
  transition: background 160ms ease, box-shadow 160ms ease;
}

.shared-availability-day:hover:not(:disabled) {
  background: rgba(214, 166, 59, 0.055);
}

.shared-availability-day.is-selected {
  background: linear-gradient(
    180deg,
    rgba(214, 166, 59, 0.11),
    rgba(255, 255, 255, 0.98)
  );
  box-shadow: inset 0 0 0 2px var(--color-gold);
}

.shared-availability-day.is-outside {
  opacity: 0.38;
}

.shared-availability-day:focus-visible,
.shared-availability-time-cell:focus-visible,
.shared-availability-view-toggle button:focus-visible,
.shared-availability-month-controls button:focus-visible {
  outline: 3px solid rgba(214, 166, 59, 0.35);
  outline-offset: 2px;
}

.shared-availability-day-number {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 28px;
  height: 28px;
  margin-bottom: 9px;
  border-radius: 50%;
  font-size: 0.76rem;
  font-weight: 850;
}

.shared-availability-day.is-selected .shared-availability-day-number {
  background: var(--color-gold);
  color: var(--color-midnight);
}

.shared-availability-day-state {
  display: flex;
  gap: 6px;
  min-height: 8px;
}

.shared-availability-day small {
  display: block;
  margin-top: 9px;
  color: var(--color-muted);
  font-size: 0.65rem;
  line-height: 1.35;
}

.shared-availability-day-view {
  margin-top: 18px;
  padding: 20px;
  border: 1px solid var(--color-border);
  border-radius: 16px;
  background: var(--color-white);
}

.shared-availability-day-view-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--color-border);
}

.shared-availability-day-view-header h3 {
  margin: 5px 0 4px;
  color: var(--color-midnight);
  font-size: 1.05rem;
}

.shared-availability-day-view-header small {
  color: var(--color-muted);
}

.shared-availability-eyebrow {
  color: var(--color-gold-dark);
  font-size: 0.68rem;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.shared-availability-day-action {
  min-height: 38px;
  padding: 0 13px;
  border: 1px solid var(--color-border);
  border-radius: 9px;
  background: var(--color-white);
  color: var(--color-midnight);
  font: inherit;
  font-size: 0.7rem;
  font-weight: 800;
  cursor: pointer;
}

.shared-availability-time-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(120px, 1fr));
  gap: 10px;
  margin-top: 18px;
  max-height: 560px;
  overflow-y: auto;
}

.shared-availability-time-cell {
  min-height: 58px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 10px 12px;
  border: 1px solid var(--color-border);
  border-radius: 11px;
  background: var(--color-white);
  color: var(--color-midnight);
  font: inherit;
  font-size: 0.75rem;
  font-weight: 750;
  text-align: left;
  cursor: pointer;
}

.shared-availability-time-cell small {
  color: var(--color-muted);
  font-size: 0.62rem;
}

.shared-availability-time-cell.is-available {
  border-color: rgba(79, 138, 102, 0.26);
  background: rgba(79, 138, 102, 0.07);
}

.shared-availability-time-cell.is-booked {
  border-color: rgba(184, 93, 82, 0.23);
  background: rgba(184, 93, 82, 0.07);
  color: #8d463d;
  cursor: not-allowed;
}

.shared-availability-time-cell.is-hold {
  border-color: rgba(154, 122, 45, 0.24);
  background: rgba(154, 122, 45, 0.07);
  cursor: not-allowed;
}

.shared-availability-time-cell.is-selected,
.shared-availability-time-cell.is-draft {
  border-color: var(--color-gold);
  background: rgba(214, 166, 59, 0.10);
}

.shared-availability-time-cell:disabled {
  opacity: 0.65;
}

@media (max-width: 960px) {
  .shared-availability-calendar-toolbar,
  .shared-availability-day-view-header {
    align-items: flex-start;
    flex-direction: column;
  }

  .shared-availability-view-toggle,
  .shared-availability-month-controls {
    width: 100%;
  }

  .shared-availability-month-controls strong {
    flex: 1;
  }
}

@media (max-width: 720px) {
  .shared-availability-calendar {
    padding: 18px;
    border-radius: 18px;
  }

  .shared-availability-month-grid {
    overflow-x: auto;
    grid-template-columns: repeat(7, minmax(100px, 1fr));
  }

  .shared-availability-weekday,
  .shared-availability-day {
    min-width: 100px;
  }

  .shared-availability-day {
    min-height: 96px;
  }

  .shared-availability-time-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 420px) {
  .shared-availability-time-grid {
    grid-template-columns: 1fr;
  }

  .shared-availability-view-toggle,
  .shared-availability-month-controls {
    flex-wrap: wrap;
  }
}

@media (prefers-reduced-motion: reduce) {
  .shared-availability-calendar * {
    transition: none !important;
  }
}
