.admin-availability-bulk-note {
  margin: 0;
  color: var(--color-muted);
  font-size: 0.69rem;
  line-height: 1.5;
}

@media (max-width: 720px) {
  .admin-availability-bulk-form {
    grid-template-columns: 1fr;
