  display: grid;
  grid-template-columns: 1.2fr 1fr 1fr;
  gap: 12px;
}

.admin-availability-form-grid label {
  display: grid;
  gap: 7px;
  min-width: 0;
}

.admin-availability-form-grid label > span {
  color: var(--color-midnight);
  font-size: 0.77rem;
  font-weight: 800;
}

.admin-availability-form-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 14px;
}

.admin-availability-form-actions > span {
  color: var(--color-muted);
  font-size: 0.78rem;
}

.admin-availability-primary-button,
.admin-availability-save-button,
.admin-availability-secondary-button,
.admin-availability-danger-button,
.admin-availability-text-button,
.admin-availability-calendar-nav button {
  min-height: 42px;
  border-radius: 10px;
  border: 1px solid var(--color-border);
  padding: 0 14px;
  font: inherit;
  font-weight: 800;
  cursor: pointer;
  transition: transform 150ms ease, box-shadow 150ms ease, background 150ms ease;
}

.admin-availability-primary-button,
.admin-availability-save-button {
  border-color: var(--color-gold);
  background: var(--color-gold);
  color: var(--color-midnight);
  box-shadow: 0 10px 24px rgba(214, 166, 59, 0.18);
}

.admin-availability-secondary-button {
  background: var(--color-white);
  color: var(--color-midnight);
}

.admin-availability-text-button {
  min-height: 36px;
  padding: 0 10px;
  border-color: transparent;
  background: transparent;
  color: var(--color-midnight);
}

.admin-availability-danger-button {
  min-height: 36px;
  padding: 0 10px;
  border-color: rgba(184, 93, 82, 0.2);
  background: rgba(184, 93, 82, 0.06);
  color: #8d463d;
}

.admin-availability-primary-button:hover,
.admin-availability-save-button:hover,
.admin-availability-secondary-button:hover,
.admin-availability-danger-button:hover {
  transform: translateY(-1px);
}

.admin-availability-primary-button:disabled,
.admin-availability-save-button:disabled,
.admin-availability-secondary-button:disabled,
.admin-availability-danger-button:disabled,
.admin-availability-text-button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

.admin-availability-repeat {
  display: grid;
  gap: 14px;
}

.admin-availability-repeat small {
  color: var(--color-muted);
  font-size: 0.75rem;
}

.admin-availability-weekdays {
  margin: 0;
  padding: 0;
  border: 0;
}

.admin-availability-weekdays legend {
  margin-bottom: 8px;
  color: var(--color-midnight);
  font-size: 0.77rem;
  font-weight: 800;
}

.admin-availability-weekdays > div {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 7px;
}

.admin-availability-weekdays label {
  position: relative;
  min-width: 0;
}

.admin-availability-weekdays input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.admin-availability-weekdays label span {
  display: grid;
  min-height: 42px;
  place-items: center;
  border: 1px solid var(--color-border);
  border-radius: 10px;
  background: var(--color-white);
  color: var(--color-midnight);
  font-size: 0.75rem;
  font-weight: 800;
  cursor: pointer;
}

.admin-availability-weekdays label.is-selected span {
  border-color: var(--color-gold);
  background: rgba(214, 166, 59, 0.1);
  box-shadow: inset 0 0 0 1px var(--color-gold);
}

.admin-availability-window-list {
  display: grid;
  gap: 9px;
}

.admin-availability-window-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 13px;
  border: 1px solid var(--color-border);
  border-radius: 12px;
  background: var(--color-white);
}

.admin-availability-window-row > div:first-child {
  min-width: 0;
}

.admin-availability-window-row strong,
.admin-availability-window-row span {
  display: block;
}

.admin-availability-window-row strong {
  color: var(--color-midnight);
  font-size: 0.88rem;
}

.admin-availability-window-row span {
  margin-top: 3px;
  color: var(--color-muted);
  font-size: 0.75rem;
}

.admin-availability-window-row > div:last-child {
  display: flex;
  align-items: center;
  gap: 2px;
  flex-shrink: 0;
}

.admin-availability-save-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-top: 16px;
  padding-top: 14px;
  border-top: 1px solid var(--color-border);
}

.admin-availability-save-row strong,
.admin-availability-save-row span {
  display: block;
}

.admin-availability-save-row strong {
  color: var(--color-midnight);
  font-size: 0.83rem;
}

.admin-availability-save-row span {
  margin-top: 3px;
  color: var(--color-muted);
  font-size: 0.73rem;
}

.admin-availability-manager-message {
  margin-top: 14px;
  padding: 11px 13px;
  border-radius: 11px;
  font-size: 0.82rem;
}

.admin-availability-manager-message.is-error {
  color: #8d463d;
  background: rgba(184, 93, 82, 0.08);
  border: 1px solid rgba(184, 93, 82, 0.16);
}

.admin-availability-manager-message.is-success {
  color: #356f4b;
  background: rgba(79, 138, 102, 0.08);
  border: 1px solid rgba(79, 138, 102, 0.16);
}

.admin-availability-empty {
  display: grid;
  gap: 4px;
  padding: 16px;
  border-radius: 12px;
  background: rgba(31, 38, 56, 0.035);
  color: var(--color-muted);
  font-size: 0.78rem;
  line-height: 1.5;
}

.admin-availability-empty strong {
  color: var(--color-midnight);
}

.admin-availability-empty.compact {
  margin-top: 10px;
}

.admin-availability-loading-skeleton {
  display: grid;
  gap: 9px;
}

.admin-availability-loading-skeleton span {
  display: block;
  height: 58px;
  border-radius: 12px;
  background: linear-gradient(90deg, rgba(31, 38, 56, 0.05), rgba(31, 38, 56, 0.1), rgba(31, 38, 56, 0.05));
  background-size: 200% 100%;
  animation: adminAvailabilityShimmer 1.2s ease-in-out infinite;
}

@keyframes adminAvailabilityShimmer {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

.admin-availability-calendar-nav {
  display: flex;
  gap: 5px;
}

.admin-availability-calendar-nav button {
  min-width: 38px;
  padding: 0;
  background: var(--color-white);
  color: var(--color-midnight);
}

.admin-availability-calendar-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 5px;
  margin-top: 8px;
}

.admin-availability-calendar-grid > span {
  padding: 5px 0;
  color: var(--color-muted);
  font-size: 0.62rem;
  font-weight: 850;
  text-align: center;
  text-transform: uppercase;
}

.admin-availability-calendar-grid button {
  position: relative;
  min-width: 0;
  min-height: 42px;
  border: 1px solid transparent;
  border-radius: 10px;
  background: var(--color-white);
  color: var(--color-midnight);
  font: inherit;
  font-size: 0.72rem;
  cursor: pointer;
}

.admin-availability-calendar-grid button:hover {
  border-color: var(--color-border);
}

.admin-availability-calendar-grid button.is-outside {
  opacity: 0.3;
}

.admin-availability-calendar-grid button.is-selected {
  border-color: var(--color-gold);
  background: rgba(214, 166, 59, 0.1);
}

.admin-availability-calendar-grid button span {
  position: absolute;
  left: 50%;
  bottom: 5px;
  width: 5px;
  height: 5px;
  transform: translateX(-50%);
  border-radius: 50%;
  background: transparent;
}

.admin-availability-calendar-grid button.has-availability span {
  background: #4f8a66;
  box-shadow: 8px 0 0 #b85d52, -8px 0 0 transparent;
}

.admin-availability-calendar-grid button.has-booking:not(.has-availability) span {
  background: #b85d52;
}

.admin-availability-calendar-grid button.has-hold span {
  box-shadow: 8px 0 0 #b08a2e;
}

.admin-availability-calendar-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 13px;
  margin-top: 14px;
  color: var(--color-muted);
  font-size: 0.68rem;
}

.admin-availability-calendar-legend span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.admin-availability-calendar-legend i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
}

.admin-availability-calendar-legend .is-available { background: #4f8a66; }
.admin-availability-calendar-legend .is-booked { background: #b85d52; }
.admin-availability-calendar-legend .is-held { background: #b08a2e; }

.admin-availability-day-summary {
  display: grid;
  gap: 12px;
}

.admin-availability-summary-stat {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 12px 13px;
  border-radius: 12px;
  background: rgba(214, 166, 59, 0.08);
}

.admin-availability-summary-stat strong {
  color: var(--color-midnight);
  font-size: 1.2rem;
}

.admin-availability-summary-stat span {
  color: var(--color-muted);
  font-size: 0.73rem;
}

.admin-availability-activity-list {
  display: grid;
  gap: 8px;
}

.admin-availability-activity-list > strong {
  color: var(--color-midnight);
  font-size: 0.75rem;
}

.admin-availability-activity {
  display: grid;
  gap: 2px;
  padding: 10px 11px;
  border-radius: 10px;
  border-left: 3px solid;
  background: var(--color-white);
  border-top: 1px solid var(--color-border);
  border-right: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
}

.admin-availability-activity span {
  font-size: 0.75rem;
  font-weight: 800;
}

.admin-availability-activity small {
  color: var(--color-muted);
  font-size: 0.68rem;
}

.admin-availability-activity.is-booked { border-left-color: #b85d52; }
.admin-availability-activity.is-held { border-left-color: #b08a2e; }

.admin-consultant-calendar-management-note {
  display: grid;
  gap: 7px;
  padding: 13px;
  border: 1px solid var(--color-border);
  border-radius: 12px;
  background: rgba(31, 38, 56, 0.03);
}

.admin-consultant-calendar-management-note strong {
  color: var(--color-midnight);
  font-size: 0.8rem;
}

.admin-consultant-calendar-management-note span {
  color: var(--color-muted);
  font-size: 0.74rem;
  line-height: 1.5;
}

.admin-consultant-calendar-management-note button {
  justify-self: start;
  min-height: 36px;
  border: 0;
  padding: 0;
  background: transparent;
  color: var(--color-midnight);
  font: inherit;
  font-size: 0.75rem;
  font-weight: 800;
  cursor: pointer;
}

@media (max-width: 980px) {
  .admin-availability-manager-layout {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 720px) {
  .admin-availability-manager {
    margin: 18px 0 24px;
    padding: 14px;
    border-radius: 17px;
  }

  .admin-availability-manager-header,
  .admin-availability-card-header,
  .admin-availability-save-row,
  .admin-availability-form-actions {
    flex-direction: column;
    align-items: stretch;
  }

  .admin-availability-manager-header-actions {
    display: grid;
    grid-template-columns: 1fr;
    justify-content: stretch;
  }

  .admin-availability-manager-header-actions select {
    min-width: 0;
  }

  .admin-availability-form-grid {
    grid-template-columns: 1fr;
  }

  .admin-availability-weekdays > div {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .admin-availability-window-row {
    align-items: flex-start;
    flex-direction: column;
  }

  .admin-availability-window-row > div:last-child {
    width: 100%;
  }

  .admin-availability-window-row > div:last-child button {
    flex: 1;
  }

  .admin-availability-save-button,
  .admin-availability-primary-button,
  .admin-availability-secondary-button {
    width: 100%;
  }

  .admin-availability-calendar-grid {
    gap: 3px;
  }

  .admin-availability-calendar-grid button {
    min-height: 38px;
  }
}

/* =========================================================
   SIMPLE CUSTOMER DATE / TIME PICKER
   ========================================================= */

.booking-date-time-card {
  display: grid;
  gap: 18px;
  padding: clamp(16px, 2vw, 24px);
  border: 1px solid var(--color-border);
  border-radius: 19px;
  background: var(--color-white);
}

.booking-date-time-intro h2 {
  margin: 5px 0 6px;
  color: var(--color-midnight);
  font-size: clamp(1.3rem, 3vw, 1.8rem);
}

.booking-date-time-intro p:last-child {
  margin: 0;
  color: var(--color-muted);
  font-size: 0.85rem;
  line-height: 1.55;
}

.booking-date-picker-block,
.booking-time-picker-block {
  display: grid;
  gap: 11px;
  padding-top: 16px;
  border-top: 1px solid var(--color-border);
}

.booking-date-picker-heading,
.booking-date-time-selected-label {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}

.booking-date-picker-heading strong,
.booking-date-time-selected-label strong {
  color: var(--color-midnight);
  font-size: 0.88rem;
}

.booking-date-picker-heading span,
.booking-date-time-selected-label span {
  color: var(--color-muted);
  font-size: 0.72rem;
}

.booking-date-options {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(115px, 1fr));
  gap: 8px;
}

.booking-date-option {
  min-width: 0;
  min-height: 62px;
  display: grid;
  align-content: center;
  gap: 3px;
  padding: 9px 10px;
  border: 1px solid var(--color-border);
  border-radius: 12px;
  background: var(--color-white);
  color: var(--color-midnight);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.booking-date-option span {
  font-size: 0.76rem;
  font-weight: 850;
}

.booking-date-option small {
  color: var(--color-muted);
  font-size: 0.68rem;
}

.booking-date-option.is-selected {
  border-color: var(--color-gold);
  background: rgba(214, 166, 59, 0.1);
  box-shadow: inset 0 0 0 1px var(--color-gold);
}

.booking-time-group {
  display: grid;
  gap: 9px;
}

.booking-time-group h3 {
  margin: 0;
  color: var(--color-midnight);
  font-size: 0.83rem;
}

.booking-time-options {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 8px;
}

.booking-time-option {
  position: relative;
  min-height: 58px;
  display: grid;
  align-content: center;
  gap: 2px;
  padding: 9px 30px 9px 11px;
  border: 1px solid var(--color-border);
  border-radius: 11px;
  background: var(--color-white);
  color: var(--color-midnight);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.booking-time-option span {
  font-size: 0.8rem;
  font-weight: 850;
}

.booking-time-option small {
  color: var(--color-muted);
  font-size: 0.66rem;
}

.booking-time-option b {
  position: absolute;
  top: 50%;
  right: 11px;
  transform: translateY(-50%);
  color: var(--color-midnight);
}

.booking-time-option.is-selected {
  border-color: var(--color-gold);
  background: rgba(214, 166, 59, 0.11);
  box-shadow: inset 0 0 0 1px var(--color-gold);
}

.booking-date-time-empty {
  display: grid;
  gap: 6px;
  padding: 18px;
  border-radius: 13px;
  background: rgba(31, 38, 56, 0.035);
}

.booking-date-time-empty h3,
.booking-date-time-empty p {
  margin: 0;
}

.booking-date-time-empty h3 {
  color: var(--color-midnight);
  font-size: 0.95rem;
}

.booking-date-time-empty p {
  color: var(--color-muted);
  font-size: 0.77rem;
  line-height: 1.5;
}

@media (max-width: 620px) {
  .booking-date-options {
    display: flex;
    overflow-x: auto;
    gap: 8px;
    padding-bottom: 3px;
    scrollbar-width: thin;
  }

  .booking-date-option {
    flex: 0 0 116px;
  }

  .booking-time-options {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .booking-date-picker-heading,
  .booking-date-time-selected-label {
    align-items: flex-start;
    flex-direction: column;
    gap: 3px;
  }
}
/* =========================================================
   SIMPLE AVAILABILITY MANAGER
   Replaces the cell-based admin editing experience.
   Mobile-first and intentionally independent from APIs.
   ========================================================= */

.admin-availability-manager {
  margin: 28px 0 36px;
  padding: clamp(16px, 2vw, 26px);
  border: 1px solid var(--color-border);
  border-radius: 22px;
  background: var(--color-white);
  box-shadow: 0 18px 50px rgba(31, 38, 56, 0.07);
}

.admin-availability-manager-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
}

.admin-availability-manager-header-copy {
  min-width: 0;
}

.admin-availability-manager-header-copy h2 {
  margin: 6px 0 8px;
  color: var(--color-midnight);
  font-size: clamp(1.4rem, 2vw, 1.9rem);
  line-height: 1.15;
}

.admin-availability-manager-header-copy p {
  max-width: 720px;
  margin: 0;
  color: var(--color-muted);
  font-size: 0.88rem;
  line-height: 1.6;
}

.admin-availability-manager-header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: 0 0 auto;
}

.admin-availability-manager-header-actions select {
  min-width: 210px;
  padding: 11px 14px;
  border: 1px solid var(--color-border);
  border-radius: 11px;
  background: var(--color-white);
  color: var(--color-midnight);
  font: inherit;
}

.admin-availability-manager-section {
  margin-top: 20px;
  padding-top: 20px;
  border-top: 1px solid var(--color-border);
}

.admin-availability-manager-section-title {
  margin-bottom: 12px;
}

.admin-availability-manager-section-title strong {
  display: block;
  color: var(--color-midnight);
  font-size: 0.9rem;
}

.admin-availability-manager-section-title span {
  display: block;
  margin-top: 3px;
  color: var(--color-muted);
  font-size: 0.75rem;
}

.admin-availability-form-grid {
  display: grid;
  grid-template-columns: 1.15fr 1fr 1fr auto;
  gap: 12px;
  align-items: end;
}

.admin-availability-field {
  min-width: 0;
}

.admin-availability-field label {
  display: block;
  margin-bottom: 6px;
  color: var(--color-muted);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.admin-availability-field input,
.admin-availability-field select {
  width: 100%;
  min-height: 46px;
  padding: 10px 12px;
  border: 1px solid var(--color-border);
  border-radius: 11px;
  background: var(--color-white);
  color: var(--color-midnight);
  font: inherit;
}

.admin-availability-form-actions {
  display: flex;
  gap: 8px;
}

.admin-availability-primary-button,
.admin-availability-secondary-button,
.admin-availability-save-button {
  min-height: 46px;
  padding: 10px 15px;
  border-radius: 11px;
  font: inherit;
  font-weight: 800;
  cursor: pointer;
  transition:
    transform 140ms ease,
    background 140ms ease,
    border-color 140ms ease;
}

.admin-availability-primary-button {
  border: 1px solid var(--color-midnight);
  background: var(--color-midnight);
  color: var(--color-white);
}

.admin-availability-secondary-button {
  border: 1px solid var(--color-border);
  background: var(--color-white);
  color: var(--color-midnight);
}

.admin-availability-save-button {
  border: 1px solid var(--color-gold);
  background: var(--color-gold);
  color: var(--color-midnight);
}

.admin-availability-primary-button:hover,
.admin-availability-secondary-button:hover,
.admin-availability-save-button:hover {
  transform: translateY(-1px);
}

.admin-availability-primary-button:disabled,
.admin-availability-secondary-button:disabled,
.admin-availability-save-button:disabled {
  opacity: 0.55;
  cursor: not-allowed;
  transform: none;
}

.admin-availability-weekly-controls {
  display: grid;
  gap: 14px;
}

.admin-availability-weekly-toggle-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.admin-availability-toggle {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: var(--color-midnight);
  font-weight: 800;
  cursor: pointer;
}

.admin-availability-toggle input {
  width: 18px;
  height: 18px;
  accent-color: var(--color-gold);
}

.admin-availability-weekdays {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 7px;
}

.admin-availability-weekdays label {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 40px;
  padding: 7px 6px;
  border: 1px solid var(--color-border);
  border-radius: 10px;
  background: var(--color-white);
  color: var(--color-muted);
  font-size: 0.72rem;
  font-weight: 800;
  cursor: pointer;
}

.admin-availability-weekdays label:has(input:checked) {
  border-color: var(--color-gold);
  background: rgba(214, 166, 59, 0.1);
  color: var(--color-midnight);
}

.admin-availability-weekdays input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.admin-availability-repeat-grid {
  display: grid;
  grid-template-columns: 1fr 1fr auto;
  gap: 12px;
  align-items: end;
}

.admin-availability-window-list {
  display: grid;
  gap: 9px;
}

.admin-availability-window-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 13px 14px;
  border: 1px solid var(--color-border);
  border-radius: 13px;
  background: var(--color-white);
}

.admin-availability-window-row-main {
  min-width: 0;
}

.admin-availability-window-row-date {
  color: var(--color-midnight);
  font-size: 0.86rem;
  font-weight: 800;
}

.admin-availability-window-row-time {
  margin-top: 3px;
  color: var(--color-muted);
  font-size: 0.78rem;
}

.admin-availability-window-row-actions {
  display: flex;
  flex: 0 0 auto;
  gap: 7px;
}

.admin-availability-calendar-preview {
  overflow: hidden;
  border: 1px solid var(--color-border);
  border-radius: 16px;
  background: var(--color-white);
}

.admin-availability-calendar-preview-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 12px 14px;
  border-bottom: 1px solid var(--color-border);
}

.admin-availability-calendar-preview-header strong {
  color: var(--color-midnight);
  font-size: 0.9rem;
}

.admin-availability-calendar-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 1px;
  background: var(--color-border);
}

.admin-availability-calendar-grid > div {
  min-width: 0;
  min-height: 72px;
  padding: 8px;
  background: var(--color-white);
}

.admin-availability-calendar-grid .is-available {
  background: rgba(79, 138, 102, 0.08);
}

.admin-availability-calendar-grid .is-booked {
  background: rgba(184, 93, 82, 0.08);
}

.admin-availability-calendar-grid .is-held {
  background: rgba(214, 166, 59, 0.1);
}

.admin-availability-calendar-day-number {
  display: block;
  margin-bottom: 6px;
  color: var(--color-midnight);
  font-size: 0.72rem;
  font-weight: 850;
}

.admin-availability-calendar-day-label {
  color: var(--color-muted);
  font-size: 0.66rem;
  line-height: 1.35;
}

.admin-availability-save-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-top: 20px;
  padding-top: 18px;
  border-top: 1px solid var(--color-border);
}

.admin-availability-status {
  color: var(--color-muted);
  font-size: 0.76rem;
}

.admin-availability-status.is-saved {
  color: #356f4b;
  font-weight: 800;
}

.admin-availability-status.is-error {
  color: #8d463d;
  font-weight: 800;
}

/* =========================================================
   SIMPLE CUSTOMER DATE / TIME PICKER
   ========================================================= */

.booking-date-time-card {
  margin-top: 18px;
  padding: clamp(15px, 2vw, 22px);
  border: 1px solid var(--color-border);
  border-radius: 18px;
  background: var(--color-white);
  box-shadow: 0 16px 40px rgba(31, 38, 56, 0.05);
}

.booking-date-time-intro h2 {
  margin: 5px 0 7px;
  color: var(--color-midnight);
  font-size: clamp(1.25rem, 2vw, 1.65rem);
  line-height: 1.2;
}

.booking-date-time-intro p {
  margin: 0;
  color: var(--color-muted);
  font-size: 0.83rem;
  line-height: 1.6;
}

.booking-date-picker-block,
.booking-time-picker-block {
  margin-top: 18px;
}

.booking-date-picker-heading,
.booking-date-time-selected-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
}

.booking-date-picker-heading strong,
.booking-date-time-selected-label strong {
  color: var(--color-midnight);
  font-size: 0.86rem;
}

.booking-date-picker-heading span,
.booking-date-time-selected-label span {
  color: var(--color-muted);
  font-size: 0.72rem;
}

.booking-date-options {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(112px, 1fr));
  gap: 8px;
}

.booking-date-option {
  min-height: 66px;
  padding: 9px 10px;
  border: 1px solid var(--color-border);
  border-radius: 12px;
  background: var(--color-white);
  color: var(--color-midnight);
  text-align: left;
  cursor: pointer;
}

.booking-date-option > span,
.booking-date-option > small {
  display: block;
}

.booking-date-option > span {
  font-size: 0.76rem;
  font-weight: 850;
}

.booking-date-option > small {
  margin-top: 4px;
  color: var(--color-muted);
  font-size: 0.66rem;
}

.booking-date-option.is-selected {
  border-color: var(--color-gold);
  background: rgba(214, 166, 59, 0.1);
  box-shadow: inset 0 0 0 1px var(--color-gold);
}

.booking-time-group {
  margin-top: 18px;
}

.booking-time-group h3 {
  margin: 0 0 9px;
  color: var(--color-midnight);
  font-size: 0.82rem;
}

.booking-time-options {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.booking-time-option {
  position: relative;
  min-height: 62px;
  padding: 10px 11px;
  border: 1px solid var(--color-border);
  border-radius: 12px;
  background: var(--color-white);
  color: var(--color-midnight);
  text-align: left;
  cursor: pointer;
}

.booking-time-option > span,
.booking-time-option > small {
  display: block;
}

.booking-time-option > span {
  font-size: 0.82rem;
  font-weight: 850;
}

.booking-time-option > small {
  margin-top: 4px;
  color: var(--color-muted);
  font-size: 0.66rem;
}

.booking-time-option > b {
  position: absolute;
  top: 8px;
  right: 9px;
  font-size: 0.8rem;
}

.booking-time-option.is-selected {
  border-color: var(--color-gold);
  background: rgba(214, 166, 59, 0.1);
  box-shadow: inset 0 0 0 1px var(--color-gold);
}

.booking-date-time-empty {
  margin-top: 16px;
  padding: 16px;
  border: 1px dashed var(--color-border);
  border-radius: 12px;
  background: rgba(31, 38, 56, 0.025);
}

.booking-date-time-empty h3,
.booking-date-time-empty p {
  margin: 0;
}

.booking-date-time-empty h3 {
  color: var(--color-midnight);
  font-size: 0.95rem;
}

.booking-date-time-empty p {
  margin-top: 5px;
  color: var(--color-muted);
  font-size: 0.77rem;
  line-height: 1.5;
}

/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 980px) {
  .admin-availability-form-grid {
    grid-template-columns: 1fr 1fr;
  }

  .admin-availability-form-actions {
    grid-column: 1 / -1;
  }

  .admin-availability-repeat-grid {
    grid-template-columns: 1fr 1fr;
  }

  .admin-availability-repeat-grid .admin-availability-primary-button {
    grid-column: 1 / -1;
  }

  .booking-time-options {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 720px) {
  .admin-availability-manager {
    margin: 18px 0 24px;
    padding: 14px;
    border-radius: 17px;
  }

  .admin-availability-manager-header,
  .admin-availability-manager-header-actions,
  .admin-availability-save-row,
  .admin-availability-weekly-toggle-row {
    flex-direction: column;
    align-items: stretch;
  }

  .admin-availability-manager-header-actions {
    width: 100%;
  }

  .admin-availability-manager-header-actions select {
    width: 100%;
    min-width: 0;
  }

  .admin-availability-form-grid,
  .admin-availability-repeat-grid {
    grid-template-columns: 1fr;
  }

  .admin-availability-form-actions,
  .admin-availability-repeat-grid .admin-availability-primary-button {
    grid-column: auto;
  }

  .admin-availability-form-actions > *,
  .admin-availability-primary-button,
  .admin-availability-secondary-button,
  .admin-availability-save-button {
    width: 100%;
  }

  .admin-availability-weekdays {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .admin-availability-window-row {
    align-items: flex-start;
    flex-direction: column;
  }

  .admin-availability-window-row-actions {
    width: 100%;
  }

  .admin-availability-window-row-actions > * {
    flex: 1;
  }

  .admin-availability-calendar-grid > div {
    min-height: 52px;
    padding: 6px;
  }

  .admin-availability-calendar-day-label {
    display: none;
  }

  .booking-date-options {
    display: flex;
    overflow-x: auto;
    gap: 8px;
    padding-bottom: 4px;
    scrollbar-width: thin;
    -webkit-overflow-scrolling: touch;
  }

  .booking-date-option {
    flex: 0 0 116px;
  }

  .booking-time-options {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .booking-date-picker-heading,
  .booking-date-time-selected-label {
    align-items: flex-start;
    flex-direction: column;
    gap: 3px;
  }
