/* =========================================================
   REPEAT WEEKLY — CLARITY + MOBILE POLISH
   ========================================================= */
.admin-availability-repeat-card {
  overflow: hidden;
}

.admin-availability-repeat-header {
  align-items: flex-start;
}

.admin-availability-switch {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  flex: 0 0 auto;
  min-height: 42px;
  padding: 0 12px;
  border: 1px solid var(--color-border);
  border-radius: 999px;
  background: var(--color-white);
  color: var(--color-midnight);
  font-size: 0.78rem;
  font-weight: 850;
  cursor: pointer;
}

.admin-availability-switch input {
  width: 17px;
  height: 17px;
  margin: 0;
  accent-color: var(--color-gold);
}

.admin-availability-repeat-flow {
  display: grid;
  gap: 12px;
  padding: 15px;
  border: 1px solid var(--color-border);
  border-radius: 14px;
  background: rgba(31, 38, 56, 0.018);
}

.admin-availability-repeat-step {
  display: flex;
  align-items: flex-start;
  gap: 10px;
}

.admin-availability-repeat-step-number {
  display: inline-grid;
  width: 26px;
  height: 26px;
  flex: 0 0 26px;
  place-items: center;
  border-radius: 999px;
  background: var(--color-gold);
  color: var(--color-midnight);
  font-size: 0.72rem;
  font-weight: 900;
}

.admin-availability-repeat-step strong,
.admin-availability-repeat-step small {
  display: block;
}

.admin-availability-repeat-step strong {
  color: var(--color-midnight);
  font-size: 0.84rem;
}

.admin-availability-repeat-step small {
  margin-top: 3px;
  color: var(--color-muted);
  font-size: 0.73rem;
  line-height: 1.45;
}

.admin-availability-repeat-date-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.admin-availability-repeat-date-grid label,
.admin-availability-repeat-time-grid label {
  display: grid;
  gap: 6px;
}

.admin-availability-repeat-date-grid label > span,
.admin-availability-repeat-time-grid label > span {
  color: var(--color-midnight);
  font-size: 0.73rem;
  font-weight: 800;
}

.admin-availability-repeat-date-grid input,
.admin-availability-repeat-time-grid input {
  width: 100%;
  min-height: 46px;
  box-sizing: border-box;
  padding: 0 12px;
  border: 1px solid var(--color-border);
  border-radius: 11px;
  background: var(--color-white);
  color: var(--color-midnight);
  font: inherit;
}

.admin-availability-repeat-time-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: end;
  gap: 10px;
}

.admin-availability-repeat-to {
  padding-bottom: 13px;
  color: var(--color-muted);
  font-size: 0.78rem;
  font-weight: 800;
}

.admin-availability-repeat-summary {
  display: grid;
  gap: 3px;
  padding: 13px 14px;
  border-radius: 12px;
  background: rgba(214, 166, 59, 0.08);
}

.admin-availability-repeat-summary strong {
  color: var(--color-midnight);
  font-size: 0.8rem;
}

.admin-availability-repeat-summary span,
.admin-availability-repeat-note {
  color: var(--color-muted);
  font-size: 0.74rem;
  line-height: 1.5;
}

.admin-availability-repeat-apply {
  width: 100%;
}

.admin-availability-repeat-off {
  display: grid;
  gap: 4px;
  padding: 14px;
  border: 1px dashed var(--color-border);
  border-radius: 12px;
  background: rgba(31, 38, 56, 0.02);
}

.admin-availability-repeat-off strong {
  color: var(--color-midnight);
  font-size: 0.82rem;
}

.admin-availability-repeat-off span {
  color: var(--color-muted);
  font-size: 0.74rem;
  line-height: 1.5;
}

@media (max-width: 720px) {
  .admin-availability-repeat-date-grid,
  .admin-availability-repeat-time-grid {
    grid-template-columns: 1fr;
  }

  .admin-availability-repeat-to {
    display: none;
  }

  .admin-availability-repeat-step {
    gap: 9px;
  }
}
/* =========================================================
   AVAILABILITY MANAGER — SCROLL TARGETS
   ========================================================= */

html {
  scroll-behavior: smooth;
}

#availability-add,
#availability-saved,
#availability-day-overview {
  scroll-margin-top: 110px;
}

@media (max-width: 720px) {
  #availability-add,
  #availability-saved,
  #availability-day-overview {
    scroll-margin-top: 84px;
  }
}
/* =========================================================
   AVAILABILITY MANAGER — DRAFT vs FINAL ACTIONS
   ========================================================= */

/* Non-final actions */
.admin-availability-primary-button,
.admin-availability-text-button,
.admin-availability-secondary-button {
  position: relative;
}

/* Draft/action buttons get a subtle "draft action" appearance */
.admin-availability-primary-button {
  box-shadow:
    0 0 0 2px rgba(214, 166, 59, 0.16),
    0 6px 16px rgba(31, 38, 56, 0.08);
}

.admin-availability-primary-button::after {
  content: "Draft";
  position: absolute;
  top: -9px;
  right: 10px;
  padding: 2px 7px;
  border-radius: 999px;
  background: var(--color-white);
  border: 1px solid var(--color-border);
  color: var(--color-muted);
  font-size: 9px;
  font-weight: 800;
  line-height: 1.2;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

/* Final database action stays visually strongest */
.admin-availability-save-button {
  position: relative;
  box-shadow:
    0 8px 22px rgba(214, 166, 59, 0.24);
}

.admin-availability-save-button::after {
  content: "Final action";
  position: absolute;
  top: -9px;
  right: 10px;
  padding: 2px 7px;
  border-radius: 999px;
  background: var(--color-midnight);
  color: var(--color-white);
  font-size: 9px;
  font-weight: 800;
  line-height: 1.2;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

/* Remove is a local draft action, not a database commit */
.admin-availability-danger-button {
  border-style: dashed !important;
  opacity: 0.85;
}

@media (max-width: 720px) {
  .admin-availability-primary-button::after,
  .admin-availability-save-button::after {
    top: -8px;
    right: 7px;
    font-size: 8px;
  }
}
