}

.about-principle-card span {
  display: block;
  margin-bottom: 18px;
  color: var(--gold-light, #e7c36c);
  font-size: 11px;
  letter-spacing: .16em;
}

.about-principle-card strong {
  color: #fff;
  font-family: var(--font-heading), Georgia, serif !important;
  font-size: 28px;
  font-weight: 500;
  line-height: 1.45;
}

.about-centered-heading {
