}

.about-pillar-card:hover {
  transform: translateY(-5px);
  border-color: rgba(214,166,59,.42);
  box-shadow: 0 22px 60px rgba(31,26,17,.08);
}

.about-pillar-icon,
.about-guidance-icon {
  width: 56px;
  height: 56px;
  display: grid;
  place-items: center;
  margin-bottom: 25px;
  border: 1px solid rgba(214,166,59,.38);
