}

.about-focus-copy .section-heading { margin-bottom: 20px; }
.about-focus-copy > p:last-child { color: var(--muted, #6f6a61); line-height: 1.95; }

.about-focus-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0;
}

.about-focus-item {
  display: flex;
  align-items: center;
  gap: 17px;
  min-height: 72px;
  padding: 10px 16px;
  border-bottom: 1px solid var(--border, #e4dac6);
}

.about-focus-item span {
  color: var(--gold, #d6a63b);
  font-family: var(--font-body), sans-serif !important;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .1em;
}

.about-focus-item strong {
  color: #263343;
  font-size: 15px;
  font-weight: 600;
}

.about-guidance-section { background: #f4eddd; }

.about-guidance-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.about-guidance-card {
  padding: 38px 34px;
  border: 1px solid var(--border, #e4dac6);
  background: #faf7ef;
}

.about-guidance-icon { margin-bottom: 23px; }

.about-philosophy-section { background: #faf7ef; }

.about-philosophy-shell {
  position: relative;
  max-width: 980px;
  margin: 0 auto;
  padding: 86px 70px;
  text-align: center;
  border: 1px solid rgba(214,166,59,.3);
  background:
    radial-gradient(circle at 50% 0%, rgba(214,166,59,.10), transparent 45%),
    #fffdf8;
}

.about-philosophy-mark {
  margin-bottom: 18px;
  color: var(--gold, #d6a63b);
  font-family: Georgia, serif !important;
  font-size: 38px;
}

.about-philosophy-shell h2 {
  max-width: 760px;
  margin: 14px auto 25px;
  color: #172536;
  font-family: var(--font-heading), Georgia, serif !important;
  font-size: clamp(34px, 4.5vw, 58px);
  font-weight: 500;
  line-height: 1.18;
}

.about-philosophy-rule {
  width: 58px;
  height: 1px;
  margin: 0 auto 26px;
  background: var(--gold, #d6a63b);
}

.about-philosophy-shell > p:last-child {
  max-width: 750px;
  margin: 0 auto;
  color: var(--muted, #6f6a61);
  font-size: 16px;
  line-height: 2;
}

.about-consultant-section {
  position: relative;
  overflow: hidden;
  color: #fff;
  background: #0d2238;
}

.about-consultant-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
  padding-top: 95px;
  padding-bottom: 95px;
}

.about-consultant-copy h2 {
  margin: 12px 0 10px;
  color: #fff;
  font-family: var(--font-heading), Georgia, serif !important;
  font-size: clamp(38px, 4vw, 60px);
  font-weight: 500;
  line-height: 1.05;
}

.about-consultant-copy > p:not(.eyebrow):not(.about-consultant-services) {
  margin: 25px 0 30px;
  color: #f4eddd;
  font-family: var(--font-heading), Georgia, serif !important;
  font-size: 25px;
}

.about-consultant-services {
  color: rgba(255,255,255,.62);
  font-family: var(--font-body), sans-serif !important;
  font-size: 12px;
  letter-spacing: .13em;
  text-transform: uppercase;
}

.about-consultant-services span {
  margin: 0 8px;
  color: var(--gold-light, #e7c36c);
}

.about-consultant-visual {
  position: relative;
  min-height: 450px;
  overflow: hidden;
  border-radius: 6px;
  border: 1px solid rgba(231,195,108,.25);
}

.about-consultant-visual img {
  object-fit: cover;
}

.about-consultant-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 40%, rgba(7,24,42,.72));
}

.about-consultant-badge {
  position: absolute;
  left: 26px;
  bottom: 24px;
  padding: 9px 15px;
  border: 1px solid rgba(231,195,108,.35);
  background: rgba(7,24,42,.75);
  color: #f4eddd;
  font-size: 12px;
  backdrop-filter: blur(8px);
}

@media (max-width: 1000px) {
  .about-hero-inner,
  .about-story-grid,
  .about-dark-inner,
  .about-focus-shell,
  .about-consultant-inner {
    grid-template-columns: 1fr;
  }

  .about-hero-inner { gap: 35px; }
  .about-hero-copy { text-align: center; margin: 0 auto; }
  .about-hero-intro { margin-left: auto; margin-right: auto; }
  .about-hero-actions { justify-content: center; }
  .about-hero-visual { min-height: 420px; }
  .about-story-grid { gap: 45px; }
  .about-dark-inner { gap: 45px; }
  .about-pillar-grid,
  .about-guidance-grid { grid-template-columns: 1fr; }
  .about-pillar-card { min-height: auto; }
  .about-focus-shell { gap: 40px; padding: 45px; }
  .about-consultant-inner { gap: 45px; }
}

@media (max-width: 640px) {
  .about-hero { min-height: 0; }
  .about-hero-inner { padding-top: 92px; padding-bottom: 70px; }
  .about-hero-title { font-size: clamp(42px, 13vw, 62px); }
  .about-hero-quote { font-size: 17px; }
  .about-hero-actions { flex-direction: column; }
  .about-hero-actions .btn { width: 100%; }
  .about-hero-visual { min-height: 350px; }
  .about-hero-card { min-height: 340px; width: min(310px, 100%); padding: 36px 25px; }
  .about-hero-card strong { font-size: 24px; }
  .about-story-card { padding: 34px 26px; }
  .about-dark-inner { padding-top: 70px; padding-bottom: 70px; }
  .about-principle-card { padding: 32px 25px; }
  .about-centered-heading { margin-bottom: 38px; }
  .about-focus-shell { padding: 30px 22px; }
  .about-focus-list { grid-template-columns: 1fr; }
  .about-focus-item { min-height: 60px; }
  .about-philosophy-shell { padding: 58px 25px; }
  .about-consultant-inner { padding-top: 70px; padding-bottom: 70px; }
  .about-consultant-visual { min-height: 350px; }
}


/* ============================================================
   AKSHAANSHH JYOTISH — ABOUT PAGE PREMIUM EXPERIENCE v2
   Real bilingual UI + stronger visual hierarchy
   ============================================================ */

.about-page {
  --about-gold: #d6a63b;
  --about-gold-light: #f0cf78;
  --about-midnight: #061523;
  --about-navy: #0c243b;
  --about-ivory: #faf7ef;
  overflow: hidden;
  background: var(--about-ivory);
}

.about-page,
.about-page p,
.about-page h1,
.about-page h2,
.about-page h3,
.about-page h4,
.about-page button,
.about-page a {
  transition: color .25s ease, background-color .25s ease, border-color .25s ease, transform .35s ease, box-shadow .35s ease, opacity .25s ease;
}

.about-page.about-lang-hi {
  font-family: "Noto Sans Devanagari", "Nirmala UI", "Mangal", var(--font-body), sans-serif;
}

.about-page.about-lang-hi h1,
.about-page.about-lang-hi h2,
.about-page.about-lang-hi h3,
.about-page.about-lang-hi h4 {
  font-family: "Noto Serif Devanagari", "Noto Sans Devanagari", Georgia, serif;
}

/* HERO */
.about-premium-hero {
  position: relative;
  min-height: 850px;
  display: flex;
  align-items: center;
  overflow: hidden;
  color: #fff;
  background:
    radial-gradient(circle at 75% 38%, rgba(214,166,59,.20), transparent 24%),
    radial-gradient(circle at 10% 80%, rgba(44,92,132,.18), transparent 28%),
    linear-gradient(135deg, #030d17 0%, #07182a 48%, #0e2b47 100%);
}

.about-premium-hero::after {
  content: "";
  position: absolute;
  left: -5%;
  right: -5%;
  bottom: -42px;
  height: 110px;
  background: var(--about-ivory);
  border-radius: 50% 50% 0 0 / 100% 100% 0 0;
}

.about-stars {
  position: absolute;
  inset: 0;
  opacity: .48;
  background-image:
    radial-gradient(rgba(255,255,255,.85) 1px, transparent 1px),
    radial-gradient(rgba(231,195,108,.65) .8px, transparent .8px);
  background-size: 74px 74px, 43px 43px;
  background-position: 0 0, 22px 17px;
  mask-image: linear-gradient(to right, transparent, #000 20%, #000 80%, transparent);
  pointer-events: none;
}

.about-hero-layout {
  position: relative;
  z-index: 3;
  width: min(100% - 40px, 1440px);
  margin-inline: auto;
  display: grid;
  grid-template-columns: minmax(0, 1.06fr) minmax(420px, .94fr);
  align-items: center;
  gap: 72px;
  padding: 132px 0 120px;
}

.about-hero-copy {
  max-width: 790px;
}

.about-language-row {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 34px;
}

.about-language-current {
  padding: 9px 14px;
  border: 1px solid rgba(231,195,108,.42);
  border-radius: 999px;
  color: rgba(255,255,255,.7);
  font-size: .68rem;
  font-weight: 700;
  letter-spacing: .14em;
}

.about-language-switch {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 38px;
  padding: 0 15px;
  border: 1px solid rgba(231,195,108,.7);
  border-radius: 999px;
  color: #07182a;
  background: linear-gradient(135deg, #f2d484, #d6a63b);
  font-size: .74rem;
  font-weight: 800;
  letter-spacing: .03em;
  box-shadow: 0 8px 28px rgba(214,166,59,.18);
}

.about-language-switch:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 32px rgba(214,166,59,.3);
}

.about-language-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #07182a;
}

.about-language-arrow {
  font-size: 1rem;
  line-height: 1;
}

.about-hero-eyebrow {
  margin: 0 0 18px;
  color: var(--about-gold-light);
  font-size: .78rem;
  font-weight: 800;
  letter-spacing: .2em;
}

.about-hero-kicker {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 18px;
  color: rgba(255,255,255,.42);
  font-size: .62rem;
  font-weight: 700;
  letter-spacing: .22em;
}

.about-hero-kicker span {
  display: block;
  width: 38px;
  height: 1px;
  background: rgba(231,195,108,.45);
}

.about-premium-hero h1 {
  max-width: 790px;
  margin: 0;
  color: #fff;
  font-family: var(--font-heading), Georgia, serif;
  font-size: clamp(3.5rem, 6.2vw, 6.7rem);
  font-weight: 500;
  line-height: .98;
  letter-spacing: -.045em;
}

.about-hero-quote {
  max-width: 720px;
  margin: 30px 0 20px;
  color: #f5ead1;
  font-family: var(--font-heading), Georgia, serif;
  font-size: clamp(1.18rem, 2vw, 1.55rem);
  line-height: 1.65;
}

.about-hero-intro {
  max-width: 680px;
  margin: 0;
  color: rgba(255,255,255,.68);
  font-size: 1rem;
  line-height: 1.95;
}

.about-hero-actions {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
  margin-top: 34px;
}

.about-hero-actions .btn {
  min-height: 54px;
  padding-inline: 24px;
}

.about-ghost-button {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  min-height: 54px;
  padding: 0 22px;
  border: 1px solid rgba(255,255,255,.18);
  border-radius: 8px;
  color: #fff;
  background: rgba(255,255,255,.035);
  backdrop-filter: blur(10px);
  font-size: .9rem;
  font-weight: 600;
}

.about-ghost-button:hover {
  transform: translateY(-2px);
  border-color: rgba(231,195,108,.55);
  background: rgba(231,195,108,.07);
  color: var(--about-gold-light);
}

/* Hero emblem */
.about-hero-emblem {
  position: relative;
  min-height: 560px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.about-emblem-outer {
  position: relative;
  width: min(510px, 100%);
  aspect-ratio: 1;
  border: 1px solid rgba(231,195,108,.48);
  border-radius: 50%;
  display: grid;
  place-items: center;
  box-shadow:
    0 0 0 24px rgba(214,166,59,.025),
    0 0 0 56px rgba(214,166,59,.015),
    0 35px 90px rgba(0,0,0,.35);
}

.about-emblem-outer::before,
.about-emblem-outer::after {
  content: "";
  position: absolute;
  border: 1px solid rgba(231,195,108,.15);
  border-radius: 50%;
}

.about-emblem-outer::before { inset: 34px; }
.about-emblem-outer::after { inset: 78px; }

.about-emblem-inner {
  width: 62%;
  aspect-ratio: 1;
  border: 1px solid rgba(231,195,108,.3);
  border-radius: 50%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: radial-gradient(circle, rgba(214,166,59,.11), rgba(7,24,42,.18) 65%);
  box-shadow: inset 0 0 70px rgba(214,166,59,.05);
}

.about-emblem-star {
  color: var(--about-gold-light);
  font-size: 1.25rem;
}

.about-emblem-symbol {
  margin: 4px 0 8px;
  color: rgba(255,255,255,.9);
  font-size: 2.4rem;
  font-family: Georgia, serif;
}

.about-emblem-brand {
  color: #f5ead1;
  font-family: var(--font-heading), Georgia, serif;
  font-size: 1.55rem;
  line-height: 1.2;
}

.about-emblem-caption {
  margin-top: 14px;
  color: rgba(231,195,108,.55);
  font-size: .48rem;
  letter-spacing: .2em;
}

.about-floating-chip {
  position: absolute;
  z-index: 4;
  padding: 11px 16px;
  border: 1px solid rgba(231,195,108,.3);
  border-radius: 999px;
  color: #f4eddd;
  background: rgba(4,17,31,.74);
  box-shadow: 0 15px 30px rgba(0,0,0,.18);
  backdrop-filter: blur(12px);
  font-size: .72rem;
  font-weight: 700;
}

.about-chip-one { top: 16%; right: 1%; }
.about-chip-two { left: 2%; top: 53%; }
.about-chip-three { right: 6%; bottom: 14%; }

.about-orbit {
  position: absolute;
  border: 1px solid rgba(231,195,108,.07);
  border-radius: 50%;
  pointer-events: none;
}
.about-orbit-a { width: 800px; height: 800px; right: -390px; top: -220px; transform: rotate(22deg); }
.about-orbit-b { width: 600px; height: 600px; right: -290px; top: -120px; transform: rotate(-28deg); }
.about-orbit-c { width: 360px; height: 360px; left: -220px; bottom: -180px; }

.about-scroll-cue {
  position: absolute;
  z-index: 4;
  bottom: 52px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  color: rgba(255,255,255,.38);
  font-size: .52rem;
  font-weight: 700;
  letter-spacing: .2em;
}
.about-scroll-cue i {
  width: 1px;
  height: 28px;
  background: linear-gradient(var(--about-gold), transparent);
}

/* STORY */
.about-story-premium {
  position: relative;
  background:
    radial-gradient(circle at 90% 10%, rgba(214,166,59,.07), transparent 22%),
    var(--about-ivory);
}
.about-story-layout {
  display: grid;
  grid-template-columns: .78fr 1.22fr;
  gap: 100px;
  align-items: start;
}
.about-story-heading h2 {
