/* =========================================================
   AKSHAANSHH JYOTISH — FINAL LIVE 3D HERO
   One controlled hero system. Replaces previous experiments.
   ========================================================= */

.hero-live {
  position: relative;
}

.hero-visual-live {
  position: relative;
  min-height: 650px;
  isolation: isolate;
  overflow: visible;
}

/* ---------- Celestial atmosphere ---------- */
.hero-celestial-field {
  position: absolute;
  inset: -8% -5% -5%;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}

.hero-celestial-field::before {
  content: "";
  position: absolute;
  width: 620px;
  height: 620px;
  left: 2%;
  top: 2%;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(214,166,59,.13) 0%, rgba(15,47,73,.08) 42%, transparent 72%);
  filter: blur(8px);
}

.hero-celestial-field::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image: radial-gradient(circle, rgba(231,195,108,.72) 0 1px, transparent 1.6px);
  background-size: 78px 72px;
  opacity: .18;
  mask-image: radial-gradient(circle at 52% 46%, black, transparent 74%);
}

.celestial-star {
  position: absolute;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--color-gold-light);
  box-shadow: 0 0 13px rgba(231,195,108,.8);
  animation: heroStarPulse 4s ease-in-out infinite;
}

.celestial-star-1 { left: 8%; top: 28%; }
.celestial-star-2 { left: 61%; top: 8%; animation-delay: .6s; }
.celestial-star-3 { left: 88%; top: 25%; animation-delay: 1.2s; }
.celestial-star-4 { left: 42%; top: 68%; animation-delay: 1.8s; }
.celestial-star-5 { left: 93%; top: 69%; animation-delay: 2.3s; }
.celestial-star-6 { left: 23%; top: 10%; animation-delay: 2.8s; }
.celestial-star-7 { left: 72%; top: 82%; animation-delay: 1s; }
