.guidance-card-number {
  color: #9b958a;
  font-size: .72rem;
  font-weight: 800;
  letter-spacing: .12em;
}

.guidance-card h3 {
  position: relative;
  z-index: 1;
  margin: 25px 0 9px;
  color: var(--color-midnight);
  font-family: var(--font-heading), Georgia, serif;
  font-size: 1.55rem;
  font-weight: 600;
}

.guidance-card-questions {
  position: relative;
  z-index: 1;
  margin: 0;
  color: var(--color-muted);
