}

.services-receive-heading .section-heading {
  margin: 10px 0 14px;
}

.services-receive-heading > p {
  max-width: 500px;
  margin: 0;
  color: var(--color-muted);
  line-height: 1.8;
}

.services-receive-list {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 26px 34px;
  align-content: center;
}

.services-receive-item {
  display: grid;
  grid-template-columns: 24px 1fr;
  gap: 12px;
}

.services-receive-item > span {
  color: var(--color-gold);
  padding-top: 2px;
}

.services-receive-item strong {
  color: var(--color-midnight);
  font-family: var(--font-heading), Georgia, serif;
  font-size: 1.08rem;
}

.services-receive-item p {
  margin: 6px 0 0;
  color: var(--color-muted);
  font-size: .88rem;
  line-height: 1.65;
}

/* Live service cards */
.services-live-section {
  background: var(--color-ivory);
}

.services-live-intro {
  max-width: 820px;
}

.services-live-count {
  display: inline-flex;
  margin-top: 21px;
