    linear-gradient(rgba(255,255,255,.035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,.035) 1px, transparent 1px);
  background-size: 58px 58px;
  mask-image: linear-gradient(to bottom, rgba(0,0,0,.8), transparent 88%);
  pointer-events: none;
}

.services-page-hero-orbit {
  position: absolute;
  border: 1px solid rgba(214,166,59,.13);
  border-radius: 50%;
  pointer-events: none;
}

.services-page-hero-orbit-one {
  width: 620px;
  height: 620px;
  right: -250px;
  top: -180px;
}

.services-page-hero-orbit-two {
  width: 390px;
  height: 390px;
  left: -250px;
  bottom: -230px;
}

.services-page-hero-inner {
  position: relative;
  z-index: 1;
  text-align: center;
}

.services-page-eyebrow {
  color: var(--color-gold-light);
}

.services-page-title {
  max-width: 980px;
  margin: 16px auto 0;
  color: #fff;
  font-family: var(--font-heading), Georgia, serif;
  font-size: clamp(3rem, 6vw, 5.8rem);
  font-weight: 500;
  line-height: 1.02;
  letter-spacing: -.045em;
}

.services-page-title span {
  color: var(--color-gold-light);
}

.services-page-lead {
  max-width: 760px;
  margin: 28px auto 0;
  color: #d7e0e8;
  font-size: 1.08rem;
  line-height: 1.9;
}

.services-page-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  flex-wrap: wrap;
  margin-top: 38px;
}

.services-page-hero-link {
  color: #fff;
  font-weight: 600;
  transition: color 180ms ease, transform 180ms ease;
}

.services-page-hero-link:hover {
  color: var(--color-gold-light);
  transform: translateX(3px);
}

.services-page-hero-note {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 13px;
  margin-top: 54px;
  color: rgba(255,255,255,.58);
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .18em;
  text-transform: uppercase;
}

/* Value */
.services-value-section {
  background: #fff;
}

.services-value-grid {
  display: grid;
  grid-template-columns: minmax(0, .9fr) minmax(0, 1.1fr);
  gap: 90px;
  align-items: start;
}

.services-value-heading .section-heading {
  margin: 10px 0 0;
}

.services-value-copy > p {
  max-width: 650px;
  margin: 0;
  color: var(--color-muted);
  font-size: 1.05rem;
  line-height: 1.85;
}

.services-value-points {
  display: grid;
  gap: 0;
  margin-top: 34px;
  border-top: 1px solid var(--color-border);
}

.services-value-points > div {
  display: grid;
  grid-template-columns: 48px 1fr;
  gap: 12px 18px;
  padding: 22px 0;
  border-bottom: 1px solid var(--color-border);
}

.services-value-points span {
  grid-row: span 2;
  color: var(--color-gold-dark);
  font-size: .74rem;
  font-weight: 800;
  letter-spacing: .1em;
}

.services-value-points strong {
  color: var(--color-midnight);
  font-family: var(--font-heading), Georgia, serif;
  font-size: 1.18rem;
  font-weight: 600;
}

.services-value-points p {
  margin: 0;
  color: var(--color-muted);
  font-size: .92rem;
  line-height: 1.65;
}

/* Shared section intro */
.services-section-intro {
  max-width: 760px;
  margin: 0 auto;
  text-align: center;
}

.services-section-intro .section-heading {
  margin: 9px 0 15px;
}

.services-section-intro > p {
  max-width: 700px;
  margin: 0 auto;
  color: var(--color-muted);
  line-height: 1.8;
}

/* Find guidance */
.services-guidance-section {
  background:
    radial-gradient(circle at 50% 0, rgba(214,166,59,.07), transparent 35%),
    var(--color-ivory);
}

.guidance-grid {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 18px;
  margin-top: 54px;
}

.guidance-card {
  grid-column: span 2;
  position: relative;
  min-height: 330px;
  display: flex;
  flex-direction: column;
  padding: 27px 25px 23px;
  overflow: hidden;
  background: rgba(255,255,255,.78);
  border: 1px solid var(--color-border);
  border-radius: 24px;
  box-shadow: var(--shadow-soft);
  transition: transform .3s ease, box-shadow .3s ease, border-color .3s ease;
}

.guidance-card:nth-child(4),
.guidance-card:nth-child(5) {
  grid-column: span 3;
}

.guidance-card::after {
  content: "✦";
  position: absolute;
  right: -8px;
  bottom: -28px;
  color: rgba(214,166,59,.08);
  font-family: Georgia, serif;
  font-size: 8rem;
  line-height: 1;
  pointer-events: none;
}

.guidance-card:hover {
  transform: translateY(-7px);
  border-color: var(--color-gold-light);
  box-shadow: 0 20px 50px rgba(7,24,42,.12);
}

.guidance-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.guidance-card-icon {
  width: 47px;
  height: 47px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(214,166,59,.38);
  border-radius: 14px;
  background: rgba(214,166,59,.1);
  color: var(--color-gold-dark);
  font-size: 1.35rem;
}

.guidance-card-number {
  color: #9b958a;
  font-size: .72rem;
  font-weight: 800;
  letter-spacing: .12em;
}

.guidance-card h3 {
  position: relative;
  z-index: 1;
  margin: 25px 0 9px;
  color: var(--color-midnight);
  font-family: var(--font-heading), Georgia, serif;
  font-size: 1.55rem;
  font-weight: 600;
}

.guidance-card-questions {
  position: relative;
  z-index: 1;
  margin: 0;
  color: var(--color-muted);
  font-size: .9rem;
  line-height: 1.7;
}

.guidance-card-service {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 3px;
  margin-top: auto;
  padding-top: 20px;
}

.guidance-card-service span {
  color: var(--color-gold-dark);
  font-size: .67rem;
  font-weight: 800;
  letter-spacing: .15em;
  text-transform: uppercase;
}

.guidance-card-service strong {
  color: var(--color-midnight);
  font-size: .93rem;
}

.guidance-card-link {
  position: relative;
  z-index: 1;
  align-self: flex-start;
  margin-top: 15px;
  color: var(--color-midnight);
  font-size: .8rem;
  font-weight: 700;
}

.guidance-card-link:hover {
  color: var(--color-gold-dark);
}

/* Receive */
.services-receive-section {
  background: #fff;
}

.services-receive-shell {
  display: grid;
  grid-template-columns: minmax(0, .9fr) minmax(0, 1.1fr);
  gap: 80px;
  padding: 64px;
  border: 1px solid var(--color-border);
  border-radius: 30px;
  background:
    radial-gradient(circle at 100% 0, rgba(214,166,59,.1), transparent 32%),
    linear-gradient(135deg, #fff, #faf7ef);
  box-shadow: var(--shadow-soft);
}

.services-receive-heading .section-heading {
  margin: 10px 0 14px;
}

.services-receive-heading > p {
  max-width: 500px;
  margin: 0;
  color: var(--color-muted);
  line-height: 1.8;
}

.services-receive-list {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 26px 34px;
  align-content: center;
}

.services-receive-item {
  display: grid;
  grid-template-columns: 24px 1fr;
  gap: 12px;
}

.services-receive-item > span {
  color: var(--color-gold);
  padding-top: 2px;
}

.services-receive-item strong {
  color: var(--color-midnight);
  font-family: var(--font-heading), Georgia, serif;
  font-size: 1.08rem;
}

.services-receive-item p {
  margin: 6px 0 0;
  color: var(--color-muted);
  font-size: .88rem;
  line-height: 1.65;
}

/* Live service cards */
.services-live-section {
  background: var(--color-ivory);
}

.services-live-intro {
  max-width: 820px;
}

.services-live-count {
  display: inline-flex;
  margin-top: 21px;
  padding: 7px 13px;
  border: 1px solid var(--color-border);
  border-radius: 999px;
  background: #fff;
  color: var(--color-gold-dark);
  font-size: .7rem;
  font-weight: 800;
  letter-spacing: .1em;
  text-transform: uppercase;
}

.services-detail-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 22px;
  margin-top: 50px;
}

.services-detail-card {
  position: relative;
  min-height: 410px;
  display: flex;
  flex-direction: column;
  padding: 29px 27px 24px;
  overflow: hidden;
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: 25px;
  box-shadow: var(--shadow-soft);
  transition: transform .3s ease, box-shadow .3s ease, border-color .3s ease;
}

.services-detail-card:hover {
  transform: translateY(-7px);
  border-color: var(--color-gold-light);
  box-shadow: 0 22px 52px rgba(7,24,42,.13);
}

.services-detail-card::after {
  content: "✦";
  position: absolute;
  right: -10px;
  top: 105px;
  color: rgba(214,166,59,.055);
  font-size: 8rem;
  line-height: 1;
  pointer-events: none;
}

.services-detail-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.services-detail-icon {
  width: 49px;
  height: 49px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(214,166,59,.35);
  border-radius: 15px;
  background: rgba(214,166,59,.09);
  color: var(--color-gold-dark);
  font-size: 1.4rem;
}

.services-detail-number {
  color: #9b958a;
  font-size: .72rem;
  font-weight: 800;
  letter-spacing: .12em;
}

.services-detail-category {
  align-self: flex-start;
  margin-top: 22px;
  padding: 6px 10px;
  border: 1px solid var(--color-border);
  border-radius: 999px;
  color: var(--color-gold-dark);
  background: #fcfaf4;
  font-size: .66rem;
  font-weight: 800;
  letter-spacing: .1em;
  text-transform: uppercase;
}

.services-detail-card h3 {
  position: relative;
  z-index: 1;
  margin: 16px 0 9px;
  color: var(--color-midnight);
  font-family: var(--font-heading), Georgia, serif;
  font-size: 1.55rem;
  font-weight: 600;
  line-height: 1.2;
}

.services-detail-description {
  position: relative;
  z-index: 1;
  min-height: 78px;
  margin: 0;
  color: var(--color-muted);
  font-size: .9rem;
  line-height: 1.7;
}

.services-detail-meta {
  position: relative;
  z-index: 1;
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
  margin-top: 19px;
  padding-top: 17px;
  border-top: 1px solid var(--color-border);
}

.services-detail-meta span {
  display: grid;
  gap: 2px;
  color: var(--color-midnight);
  font-size: .8rem;
}

.services-detail-meta b {
  color: #9b958a;
  font-size: .63rem;
  font-weight: 800;
  letter-spacing: .1em;
  text-transform: uppercase;
}

.services-detail-bottom {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 15px;
  margin-top: auto;
  padding-top: 23px;
}

.services-detail-bottom > div {
  display: grid;
  gap: 3px;
}

.services-detail-bottom small {
  color: #918b80;
  font-size: .68rem;
}

.services-detail-bottom strong {
  color: var(--color-midnight);
  font-family: var(--font-heading), Georgia, serif;
  font-size: 1.25rem;
  font-weight: 600;
}

.services-detail-book {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 43px;
  padding: 0 16px;
  border-radius: 999px;
  background: var(--color-midnight);
  color: #fff;
  font-size: .76rem;
  font-weight: 700;
  white-space: nowrap;
  transition: transform 180ms ease, background 180ms ease;
}

.services-detail-book:hover {
  transform: translateY(-2px);
  background: var(--color-gold-dark);
}

/* Loading/error */
.services-page-state {
  min-height: 220px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  margin-top: 50px;
  padding: 38px 24px;
  border: 1px solid var(--color-border);
  border-radius: 24px;
  background: #fff;
  text-align: center;
  box-shadow: var(--shadow-soft);
}

.services-page-state strong {
  margin-top: 13px;
  color: var(--color-midnight);
  font-family: var(--font-heading), Georgia, serif;
  font-size: 1.2rem;
}

.services-page-state p {
  max-width: 560px;
  margin: 7px 0 18px;
  color: var(--color-muted);
}

.services-page-spinner {
  width: 30px;
  height: 30px;
  border: 2px solid var(--color-border);
  border-top-color: var(--color-gold);
  border-radius: 50%;
  animation: services-page-spin .8s linear infinite;
}

@keyframes services-page-spin {
  to { transform: rotate(360deg); }
}

/* Process */
.services-process-section {
  background: #fff;
}

.services-process-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-top: 52px;
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
}

.services-process-step {
  min-height: 235px;
  padding: 31px 28px 28px;
  border-right: 1px solid var(--color-border);
}

.services-process-step:last-child {
  border-right: 0;
}

.services-process-step > span {
  color: var(--color-gold-dark);
  font-size: .72rem;
  font-weight: 800;
  letter-spacing: .12em;
}

.services-process-step h3 {
  margin: 27px 0 9px;
  color: var(--color-midnight);
  font-family: var(--font-heading), Georgia, serif;
  font-size: 1.28rem;
}

.services-process-step p {
  margin: 0;
  color: var(--color-muted);
  font-size: .88rem;
  line-height: 1.7;
}

/* Help */
.services-help-section {
  padding: 88px 0;
  background:
    radial-gradient(circle at 80% 30%, rgba(214,166,59,.16), transparent 28%),
    linear-gradient(135deg, #07182a, #0d2a45);
}

.services-help-shell {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 50px;
}

.services-help-shell .eyebrow {
  color: var(--color-gold-light);
}

.services-help-shell h2 {
  margin: 9px 0 10px;
  color: #fff;
  font-family: var(--font-heading), Georgia, serif;
  font-size: clamp(2rem, 4vw, 3.1rem);
  font-weight: 500;
  line-height: 1.12;
}

.services-help-shell p {
  max-width: 650px;
  margin: 0;
  color: #cbd7e0;
  line-height: 1.8;
}

.services-help-actions {
  display: flex;
  align-items: center;
  gap: 21px;
  flex-shrink: 0;
}

.services-help-book {
  color: #fff;
  font-weight: 700;
  white-space: nowrap;
}

.services-help-book:hover {
  color: var(--color-gold-light);
}

/* Responsive */
@media (max-width: 1050px) {
  .services-page-hero {
    min-height: 610px;
    padding: 135px 0 90px;
  }

  .services-value-grid,
  .services-receive-shell {
    grid-template-columns: 1fr;
    gap: 45px;
  }

  .guidance-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .guidance-card,
  .guidance-card:nth-child(4),
  .guidance-card:nth-child(5) {
    grid-column: span 1;
  }

  .services-detail-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .services-process-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .services-process-step:nth-child(2) {
    border-right: 0;
  }

  .services-process-step:nth-child(-n + 2) {
    border-bottom: 1px solid var(--color-border);
  }

  .services-help-shell {
    align-items: flex-start;
    flex-direction: column;
  }
}

@media (max-width: 700px) {
  .services-page-hero {
    min-height: 570px;
    padding: 120px 0 80px;
  }

  .services-page-title {
    font-size: clamp(2.65rem, 12vw, 4rem);
  }

  .services-page-lead {
    font-size: .96rem;
    line-height: 1.75;
  }

  .services-page-actions {
    gap: 18px;
    flex-direction: column;
  }

  .services-page-hero-note {
    margin-top: 39px;
    font-size: .62rem;
    letter-spacing: .11em;
  }

  .services-value-grid {
    gap: 35px;
  }

  .services-value-points > div {
    grid-template-columns: 40px 1fr;
  }

  .guidance-grid,
  .services-detail-grid {
    grid-template-columns: 1fr;
  }

  .guidance-card {
    min-height: 300px;
  }

  .services-receive-shell {
    padding: 36px 24px;
    border-radius: 24px;
  }

  .services-receive-list {
    grid-template-columns: 1fr;
    gap: 23px;
  }

  .services-detail-card {
    min-height: 390px;
  }

  .services-process-grid {
    grid-template-columns: 1fr;
  }

  .services-process-step {
    min-height: 0;
    border-right: 0;
    border-bottom: 1px solid var(--color-border);
  }

  .services-process-step:last-child {
    border-bottom: 0;
  }

  .services-help-section {
    padding: 68px 0;
  }

  .services-help-actions {
    align-items: flex-start;
    flex-direction: column;
    gap: 18px;
  }
}

@media (max-width: 430px) {
  .services-page-hero {
    padding-top: 108px;
  }

  .services-page-title {
    font-size: 2.55rem;
  }

  .services-page-hero-note {
    gap: 8px;
  }

  .services-detail-bottom {
    align-items: stretch;
    flex-direction: column;
  }

  .services-detail-book {
    width: 100%;
  }
}

@media (prefers-reduced-motion: reduce) {
  .services-detail-card,
  .guidance-card,
  .services-detail-book,
  .services-page-hero-link,
  .services-page-spinner {
    animation: none !important;
    transition: none !important;
  }
}

/* ============================================
   SERVICE FINDER — MODAL
   ============================================ */

.services-finder-inline-button {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  margin-top: 25px;
  padding: 10px 16px;
  border: 1px solid rgba(214,166,59,.42);
  border-radius: 999px;
  background: rgba(214,166,59,.07);
  color: var(--color-midnight);
  font-size: .78rem;
  font-weight: 800;
  cursor: pointer;
  transition: transform .2s ease, background .2s ease, border-color .2s ease;
}

.services-finder-inline-button:hover {
  transform: translateY(-2px);
  background: rgba(214,166,59,.13);
  border-color: var(--color-gold);
}

.guidance-card-button {
  border: 0;
  background: transparent;
  padding: 0;
  cursor: pointer;
  font: inherit;
  text-align: left;
}

.service-finder-backdrop {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: grid;
  place-items: center;
  padding: 22px;
  background: rgba(2, 12, 23, .72);
  backdrop-filter: blur(8px);
  animation: service-finder-fade .2s ease;
}

.service-finder-modal {
  position: relative;
  width: min(720px, 100%);
  max-height: min(820px, calc(100vh - 44px));
  overflow-y: auto;
  padding: 42px;
  border: 1px solid rgba(214,166,59,.28);
  border-radius: 28px;
  background:
    radial-gradient(circle at 100% 0, rgba(214,166,59,.1), transparent 30%),
    #fff;
  box-shadow: 0 35px 100px rgba(0,0,0,.3);
  animation: service-finder-rise .25s ease;
}

.service-finder-close {
  position: absolute;
  top: 18px;
  right: 19px;
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border: 1px solid var(--color-border);
  border-radius: 50%;
  background: #fff;
  color: var(--color-midnight);
  font-size: 1.45rem;
  line-height: 1;
  cursor: pointer;
  transition: transform .2s ease, border-color .2s ease;
}

.service-finder-close:hover {
  transform: rotate(6deg);
  border-color: var(--color-gold-light);
}

.service-finder-heading {
  max-width: 590px;
  padding-right: 35px;
}

.service-finder-heading h2 {
  margin: 9px 0 12px;
  color: var(--color-midnight);
  font-family: var(--font-heading), Georgia, serif;
  font-size: clamp(2rem, 5vw, 3rem);
  font-weight: 500;
  line-height: 1.1;
}

.service-finder-heading p {
  margin: 0;
  color: var(--color-muted);
  line-height: 1.75;
}

.service-finder-options {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-top: 30px;
}

.service-finder-option {
  min-height: 94px;
  display: grid;
  grid-template-columns: 42px 1fr 18px;
  align-items: center;
  gap: 13px;
  padding: 14px;
  border: 1px solid var(--color-border);
  border-radius: 18px;
  background: #fff;
  color: var(--color-midnight);
  text-align: left;
  cursor: pointer;
