/* =========================================================
   BOOKING — 3D SERVICE HOLDERS
   Frontend-only visual layer for the service selector.
   Service data remains driven by the existing API.
   ========================================================= */

.booking-services {
  align-items: start;
  perspective: 1400px;
}

.booking-service-card {
  min-height: 470px;
  padding: 0;
  overflow: visible;
  border: 0;
  background: transparent;
  box-shadow: none;
  isolation: isolate;
  transform-style: preserve-3d;
}

.booking-service-card::after {
  content: "";
  position: absolute;
  left: 8%;
  right: 8%;
  bottom: 4px;
  height: 34px;
  border-radius: 50%;
  background: rgba(7, 24, 42, 0.18);
  filter: blur(15px);
  z-index: -2;
  transition: transform 0.35s ease, opacity 0.35s ease;
}

.booking-service-card:hover {
  transform: translateY(-8px) rotateX(1deg);
  border-color: transparent;
  box-shadow: none;
}

.booking-service-card:hover::after {
  transform: scaleX(0.88);
  opacity: 0.8;
}

.booking-service-artwork {
  position: relative;
  display: block;
  height: 255px;
  margin: 0 16px -62px;
  z-index: 2;
  pointer-events: none;
  transform: translateY(2px) rotateX(0deg) rotateZ(-2deg) translateZ(35px);
  transform-origin: center bottom;
  transition: transform 0.45s cubic-bezier(.2,.75,.25,1), filter 0.45s ease;
}

.booking-service-card:nth-child(2n) .booking-service-artwork {
  transform: translateY(2px) rotateZ(2deg) translateZ(35px);
}

.booking-service-card:hover .booking-service-artwork {
  transform: translateY(-10px) rotateZ(-1deg) translateZ(55px) scale(1.025);
  filter: drop-shadow(0 18px 18px rgba(7, 24, 42, 0.18));
}

.booking-service-card:nth-child(2n):hover .booking-service-artwork {
  transform: translateY(-10px) rotateZ(1deg) translateZ(55px) scale(1.025);
}

.booking-service-artwork-shadow {
  position: absolute;
  left: 12%;
  right: 12%;
  bottom: 4px;
  height: 26px;
  border-radius: 50%;
  background: rgba(7, 24, 42, 0.28);
  filter: blur(13px);
  transform: scaleX(0.9);
}

.booking-service-artwork-frame {
  position: absolute;
  inset: 0 3% 8px;
  display: block;
  overflow: hidden;
  border: 2px solid rgba(214, 166, 59, 0.95);
  border-radius: 24px 24px 12px 12px;
  background: #100d08;
  box-shadow:
    0 14px 22px rgba(7, 24, 42, 0.2),
    inset 0 0 0 1px rgba(255, 244, 199, 0.22),
    inset 0 0 32px rgba(214, 166, 59, 0.08);
  transform: perspective(900px) rotateX(1deg);
}

.booking-service-artwork-frame::before,
.booking-service-artwork-frame::after {
  content: "";
  position: absolute;
  z-index: 2;
  pointer-events: none;
}

.booking-service-artwork-frame::before {
  inset: 10px;
  border: 1px solid rgba(244, 213, 133, 0.38);
  border-radius: 17px 17px 8px 8px;
}

.booking-service-artwork-frame::after {
  left: 8%;
  right: 8%;
  bottom: 0;
  height: 30%;
  background: linear-gradient(to top, rgba(7, 5, 2, 0.58), transparent);
}

.booking-service-artwork-svg {
  display: block;
  width: 100%;
  height: 100%;
}

.booking-service-holder {
  position: relative;
  z-index: 3;
  display: flex;
  flex-direction: column;
  min-height: 285px;
  padding: 48px 28px 25px;
  text-align: left;
  background:
    linear-gradient(145deg, #fffdf6 0%, #f6eddc 52%, #e9d9bd 100%);
  border: 1px solid rgba(166, 124, 49, 0.42);
  border-radius: 24px;
  box-shadow:
    0 18px 35px rgba(7, 24, 42, 0.12),
    0 5px 0 rgba(147, 105, 35, 0.14),
    inset 0 1px 0 rgba(255, 255, 255, 0.95),
    inset 0 -10px 24px rgba(116, 81, 30, 0.06);
  transition: box-shadow 0.35s ease, transform 0.35s ease;
}

.booking-service-holder::before {
  content: "";
  position: absolute;
  inset: 7px;
  border: 1px solid rgba(176, 133, 54, 0.18);
  border-radius: 19px;
  pointer-events: none;
}

.booking-service-card:hover .booking-service-holder {
  box-shadow:
    0 25px 45px rgba(7, 24, 42, 0.16),
    0 6px 0 rgba(147, 105, 35, 0.16),
    inset 0 1px 0 rgba(255, 255, 255, 0.98),
    inset 0 -10px 24px rgba(116, 81, 30, 0.06);
}

.booking-service-holder-emblem {
  position: absolute;
  top: -20px;
  left: 50%;
  display: grid;
  width: 50px;
  height: 50px;
  place-items: center;
  transform: translateX(-50%);
  border: 3px solid #f8e7b7;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #47300b, #110d06 70%);
  color: #f1c95f;
  font-size: 1.15rem;
  box-shadow:
    0 6px 12px rgba(7, 24, 42, 0.18),
    0 0 0 1px rgba(166, 124, 49, 0.72);
}

.booking-service-content {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
}

.booking-service-category {
  margin-bottom: 8px;
  color: var(--color-gold-dark);
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.booking-service-title {
  margin-bottom: 11px;
  color: var(--color-midnight);
  font-family: var(--font-heading), Georgia, serif;
  font-size: 1.42rem;
  font-weight: 700;
  line-height: 1.25;
}

.booking-service-description {
  color: var(--color-muted);
  font-size: 0.93rem;
  line-height: 1.65;
}

.booking-service-select {
  align-self: stretch;
  margin-top: 20px;
  padding: 12px 16px;
  border: 1px solid rgba(166, 124, 49, 0.46);
  border-radius: 12px;
  background: linear-gradient(135deg, #9c6915, #d7a938 55%, #a96f12);
  color: #fffdf5;
  font-size: 0.82rem;
  font-weight: 800;
  letter-spacing: 0.03em;
  text-align: center;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.32),
    0 7px 15px rgba(141, 94, 10, 0.18);
  transition: transform 0.25s ease, filter 0.25s ease;
}

.booking-service-card:hover .booking-service-select {
  transform: translateY(-2px);
  filter: brightness(1.05);
}

.booking-service-card-selected {
  background: transparent;
  border-color: transparent;
  box-shadow: none;
  animation: none;
}

.booking-service-card-selected::before {
  inset: 0;
  border-radius: 25px;
  background: linear-gradient(120deg, transparent 20%, rgba(231, 195, 108, 0.75) 40%, rgba(255, 255, 255, 0.95) 50%, rgba(231, 195, 108, 0.75) 60%, transparent 80%);
  background-size: 220% 100%;
  animation: goldenShimmer 2.8s linear infinite;
  opacity: 0.42;
  z-index: -1;
}

.booking-service-card-selected .booking-service-artwork {
  transform: translateY(-12px) rotateZ(-1deg) translateZ(60px) scale(1.035);
  filter: drop-shadow(0 20px 24px rgba(139, 94, 11, 0.25));
}

.booking-service-card-selected .booking-service-holder {
  border-color: rgba(214, 166, 59, 0.72);
  box-shadow:
    0 26px 48px rgba(7, 24, 42, 0.17),
    0 0 0 2px rgba(214, 166, 59, 0.18),
    0 0 30px rgba(214, 166, 59, 0.18),
    inset 0 1px 0 rgba(255,255,255,0.98);
}

.booking-service-card-selected .booking-service-select {
  background: linear-gradient(135deg, #754c09, #c9952b 55%, #805309);
}

@media (max-width: 950px) {
  .booking-service-card {
    min-height: 450px;
  }

  .booking-service-artwork {
    height: 235px;
  }

  .booking-service-holder {
    padding-inline: 23px;
  }
}

@media (max-width: 600px) {
  .booking-service-card {
    min-height: 425px;
  }

  .booking-service-artwork {
    height: 220px;
    margin-inline: 22px;
    margin-bottom: -52px;
  }

  .booking-service-holder {
    min-height: 260px;
    padding: 40px 22px 22px;
    border-radius: 20px;
  }

  .booking-service-title {
    font-size: 1.25rem;
  }

  .booking-service-description {
    font-size: 0.89rem;
  }

  .booking-service-artwork-frame {
    border-radius: 20px 20px 10px 10px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .booking-service-card,
  .booking-service-artwork,
  .booking-service-holder,
  .booking-service-select {
    transition: none !important;
  }

  .booking-service-card-selected::before {
    animation: none !important;
  }
}


