/* =========================================================
   CUSTOMER BOOKING — MODERN DATE & TIME CALENDAR
   Restored for the current DateTimeSelector component.
   Frontend-only styling; no booking/payment behavior changed.
   ========================================================= */

.booking-date-time-card {
  width: 100%;
  margin-top: 18px;
  padding: clamp(20px, 3vw, 34px);
  border: 1px solid rgba(228, 218, 198, 0.95);
  border-radius: 26px;
  background:
    radial-gradient(
      circle at 92% 0%,
      rgba(231, 195, 108, 0.12),
      transparent 30%
    ),
    #ffffff;
  box-shadow:
    0 24px 60px rgba(7, 24, 42, 0.08),
    0 2px 10px rgba(7, 24, 42, 0.03);
}

.booking-date-time-intro {
  max-width: 760px;
}

.booking-date-time-intro h2 {
  margin: 7px 0 8px;
  color: var(--color-midnight);
  font-family: var(--font-heading), Georgia, serif;
  font-size: clamp(1.65rem, 3vw, 2.35rem);
  font-weight: 500;
  line-height: 1.16;
  letter-spacing: -0.025em;
}

.booking-date-time-intro p:last-child {
  margin: 0;
  color: var(--color-muted);
  font-size: 0.88rem;
  line-height: 1.7;
}

.booking-date-time-intro strong {
  color: var(--color-gold-dark);
  font-weight: 700;
}

/* Calendar shell */

.booking-calendar-block {
  margin-top: 24px;
  padding: clamp(16px, 2.5vw, 26px);
  border: 1px solid rgba(228, 218, 198, 0.9);
  border-radius: 20px;
  background:
    linear-gradient(
      180deg,
      #fffefa 0%,
      #faf7ef 100%
    );
}

.booking-calendar-header {
  display: grid;
  grid-template-columns: 46px minmax(0, 1fr) 46px;
  align-items: center;
  gap: 14px;
  margin-bottom: 20px;
}

.booking-calendar-nav {
  width: 44px;
  height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 1px solid rgba(214, 166, 59, 0.34);
  border-radius: 50%;
  background: #ffffff;
  color: var(--color-midnight);
  font-size: 1.55rem;
  line-height: 1;
  box-shadow: 0 6px 18px rgba(7, 24, 42, 0.05);
  transition:
    transform 180ms ease,
    border-color 180ms ease,
    background-color 180ms ease,
    box-shadow 180ms ease;
}

.booking-calendar-nav:hover:not(:disabled) {
  transform: translateY(-2px);
  border-color: var(--color-gold);
  background: #fffaf0;
  box-shadow: 0 10px 24px rgba(7, 24, 42, 0.09);
}

.booking-calendar-nav:disabled {
  opacity: 0.32;
  cursor: not-allowed;
  box-shadow: none;
}

.booking-calendar-month {
  min-width: 0;
  display: grid;
  justify-items: center;
  gap: 3px;
  text-align: center;
}

.booking-calendar-month strong {
  color: var(--color-midnight);
  font-family: var(--font-heading), Georgia, serif;
  font-size: clamp(1.25rem, 2.6vw, 1.65rem);
  font-weight: 500;
  line-height: 1.2;
}

.booking-calendar-month span {
  color: var(--color-muted);
  font-size: 0.72rem;
  line-height: 1.35;
}

.booking-calendar-month .booking-calendar-month-eyebrow {
  color: var(--color-gold-dark);
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

/* Weekdays */

.booking-calendar-weekdays {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 8px;
  margin-bottom: 8px;
}

.booking-calendar-weekdays span {
  min-height: 26px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #8c8579;
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

/* Day grid */

.booking-calendar-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 8px;
}

.booking-calendar-day {
  position: relative;
  min-width: 0;
  min-height: 72px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 8px 5px;
  border: 1px solid transparent;
  border-radius: 15px;
  background: transparent;
  color: #b4aea3;
  font: inherit;
  cursor: not-allowed;
  overflow: hidden;
  transition:
    transform 180ms ease,
    border-color 180ms ease,
    background 180ms ease,
    box-shadow 180ms ease;
}

.booking-calendar-day.is-empty {
  pointer-events: none;
  visibility: hidden;
}

.booking-calendar-day.is-unavailable {
  opacity: 0.52;
}

.booking-calendar-day.is-available {
  border-color: rgba(228, 218, 198, 0.95);
  background: rgba(255, 255, 255, 0.94);
  color: var(--color-midnight);
  cursor: pointer;
  box-shadow: 0 3px 12px rgba(7, 24, 42, 0.035);
}

.booking-calendar-day.is-available:hover {
  transform: translateY(-2px);
  border-color: rgba(214, 166, 59, 0.62);
  background: #fffaf0;
  box-shadow:
    0 10px 24px rgba(7, 24, 42, 0.09),
    0 0 0 1px rgba(214, 166, 59, 0.08);
}

.booking-calendar-day.is-today {
  box-shadow:
    inset 0 0 0 1px rgba(214, 166, 59, 0.3);
}

.booking-calendar-day.is-selected {
  border-color: var(--color-gold);
  background:
    linear-gradient(
      145deg,
      #ffffff 5%,
      rgba(231, 195, 108, 0.32) 100%
    );
  color: var(--color-midnight);
  box-shadow:
    inset 0 0 0 1px var(--color-gold),
    0 10px 28px rgba(214, 166, 59, 0.17);
}

.booking-calendar-day-number {
  position: relative;
  z-index: 2;
  display: block;
  font-size: 0.95rem;
  font-weight: 800;
  line-height: 1;
}

.booking-calendar-day.is-selected .booking-calendar-day-number {
  font-size: 1rem;
}

.booking-calendar-day-dot {
  width: 18px;
  height: 7px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.booking-calendar-day-dot i {
  width: 6px;
  height: 6px;
  display: block;
  border-radius: 50%;
  background: var(--color-gold);
  box-shadow: 0 0 0 3px rgba(214, 166, 59, 0.1);
}

.booking-calendar-day.is-selected .booking-calendar-day-dot i {
  background: var(--color-gold-dark);
  box-shadow: 0 0 0 3px rgba(214, 166, 59, 0.14);
}

.booking-calendar-today-label {
  position: absolute;
  top: 6px;
  left: 50%;
  transform: translateX(-50%);
  color: var(--color-gold-dark);
  font-size: 0.48rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  line-height: 1;
  text-transform: uppercase;
}

/* Legend */

.booking-calendar-legend {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 20px;
  margin-top: 18px;
  color: var(--color-muted);
  font-size: 0.7rem;
}

.booking-calendar-legend span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
}

.booking-calendar-legend-dot {
  width: 8px;
  height: 8px;
  display: inline-block;
  border-radius: 50%;
  background: var(--color-border);
}

.booking-calendar-legend-dot.is-available {
  background: var(--color-gold-light);
}

.booking-calendar-legend-dot.is-selected {
  background: var(--color-gold-dark);
}

/* Selected date / times */

.booking-time-picker-block {
  margin-top: 24px;
  padding-top: 24px;
  border-top: 1px solid rgba(228, 218, 198, 0.9);
}

.booking-date-time-selected-label {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 20px;
}

.booking-date-time-selected-label > div {
  display: grid;
  gap: 4px;
}

.booking-selected-kicker {
  color: var(--color-gold-dark);
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.booking-date-time-selected-label strong {
  color: var(--color-midnight);
  font-family: var(--font-heading), Georgia, serif;
  font-size: 1.12rem;
  font-weight: 500;
}

.booking-date-time-selected-label > span {
  flex: 0 0 auto;
  color: var(--color-muted);
  font-size: 0.72rem;
  white-space: nowrap;
}

.booking-time-group {
  display: grid;
  gap: 10px;
  margin-top: 20px;
}

.booking-time-group:first-of-type {
  margin-top: 0;
}

.booking-time-group h3 {
  margin: 0;
  color: var(--color-midnight);
  font-size: 0.76rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.booking-time-options {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
  gap: 9px;
}

.booking-time-option {
  position: relative;
  min-height: 62px;
  display: grid;
  align-content: center;
  gap: 4px;
  padding: 10px 38px 10px 14px;
  border: 1px solid var(--color-border);
  border-radius: 13px;
  background: #ffffff;
  color: var(--color-midnight);
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition:
    transform 160ms ease,
    border-color 160ms ease,
    background 160ms ease,
    box-shadow 160ms ease;
}

.booking-time-option:hover {
  transform: translateY(-2px);
  border-color: var(--color-gold-light);
  background: #fffaf0;
  box-shadow: 0 8px 20px rgba(7, 24, 42, 0.07);
}

.booking-time-option.is-selected {
  border-color: var(--color-gold);
  background: rgba(214, 166, 59, 0.1);
  box-shadow:
    inset 0 0 0 1px var(--color-gold),
    0 8px 20px rgba(214, 166, 59, 0.1);
}

.booking-time-option > span,
.booking-time-option > small {
  display: block;
}

.booking-time-option > span {
  color: var(--color-midnight);
  font-size: 0.84rem;
  font-weight: 800;
}

.booking-time-option > small {
  color: var(--color-muted);
  font-size: 0.64rem;
  font-weight: 600;
}

.booking-time-option > b {
  position: absolute;
  top: 50%;
  right: 13px;
  transform: translateY(-50%);
  color: var(--color-gold-dark);
  font-size: 0.92rem;
}

.booking-date-time-empty {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 18px;
  border: 1px solid var(--color-border);
  border-radius: 15px;
  background: rgba(31, 38, 56, 0.035);
}

.booking-date-time-empty h3,
.booking-date-time-empty p {
  margin: 0;
}

.booking-date-time-empty h3 {
  color: var(--color-midnight);
  font-family: var(--font-heading), Georgia, serif;
  font-size: 1rem;
}

.booking-date-time-empty p {
  margin-top: 4px;
  color: var(--color-muted);
  font-size: 0.78rem;
  line-height: 1.55;
}

.booking-calendar-nav:focus-visible,
.booking-calendar-day:focus-visible,
.booking-time-option:focus-visible {
  outline: 2px solid var(--color-gold);
  outline-offset: 3px;
}

/* Responsive calendar */

@media (max-width: 720px) {
  .booking-date-time-card {
    padding: 18px;
    border-radius: 21px;
  }

  .booking-calendar-block {
    padding: 14px;
    border-radius: 17px;
  }

  .booking-calendar-header {
    grid-template-columns: 40px minmax(0, 1fr) 40px;
    gap: 8px;
  }

  .booking-calendar-nav {
    width: 38px;
    height: 38px;
    font-size: 1.35rem;
  }

  .booking-calendar-grid,
  .booking-calendar-weekdays {
    gap: 5px;
  }

  .booking-calendar-day {
    min-height: 58px;
    border-radius: 11px;
  }

  .booking-calendar-day-number {
    font-size: 0.82rem;
  }

  .booking-calendar-today-label {
    top: 5px;
    font-size: 0.42rem;
  }

  .booking-calendar-day-dot {
    width: 15px;
  }

  .booking-calendar-day-dot i {
    width: 5px;
    height: 5px;
  }

  .booking-calendar-weekdays span {
    font-size: 0.56rem;
  }

  .booking-date-time-selected-label {
    align-items: flex-start;
    flex-direction: column;
    gap: 6px;
  }

  .booking-date-time-selected-label > span {
    white-space: normal;
  }

  .booking-time-options {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 420px) {
  .booking-date-time-card {
    padding: 14px;
  }

  .booking-calendar-block {
    padding: 10px;
  }

  .booking-calendar-header {
    margin-bottom: 14px;
  }

  .booking-calendar-month strong {
    font-size: 1.08rem;
  }

  .booking-calendar-month span {
    font-size: 0.62rem;
  }

  .booking-calendar-month .booking-calendar-month-eyebrow {
    font-size: 0.52rem;
  }

  .booking-calendar-day {
    min-height: 51px;
    padding: 6px 2px;
    border-radius: 9px;
  }

  .booking-calendar-grid,
  .booking-calendar-weekdays {
    gap: 4px;
  }

  .booking-calendar-day-number {
    font-size: 0.74rem;
  }

  .booking-calendar-weekdays span {
    font-size: 0.5rem;
    letter-spacing: 0.04em;
  }

  .booking-calendar-today-label {
    font-size: 0.38rem;
  }

  .booking-time-options {
    grid-template-columns: 1fr;
  }
}

@media (prefers-reduced-motion: reduce) {
  .booking-calendar-nav,
  .booking-calendar-day,
  .booking-time-option {
    transition: none;
  }

  .booking-calendar-nav:hover:not(:disabled),
  .booking-calendar-day.is-available:hover,
  .booking-time-option:hover {
    transform: none;
  }
}
/* =========================================================
   SUPER ADMINISTRATOR - POWER & ACCESS
   ========================================================= */

.admin-settings-power {
  margin-top: 28px;
}

.admin-settings-power-intro {
  margin-bottom: 22px;
}

.admin-settings-power-intro strong {
  display: block;
  color: #2d2318;
  font-size: 15px;
  font-weight: 700;
  margin-bottom: 6px;
}

.admin-settings-power-intro p {
  margin: 0;
  color: #766653;
  font-size: 13px;
  line-height: 1.7;
}

.admin-settings-permissions {
  display: grid;
  gap: 12px;
}

.admin-settings-permission-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 15px 16px;
  border: 1px solid rgba(180, 145, 74, 0.18);
  border-radius: 12px;
  background: rgba(250, 247, 239, 0.72);
}

.admin-settings-permission-copy {
  min-width: 0;
}

.admin-settings-permission-copy strong {
  display: block;
  color: #2d2318;
  font-size: 13px;
  font-weight: 700;
  margin-bottom: 4px;
}

.admin-settings-permission-copy span {
  display: block;
  color: #887864;
  font-size: 12px;
  line-height: 1.55;
}

.admin-settings-permission-badge {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 30px;
  padding: 5px 10px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  white-space: nowrap;
}

.admin-settings-permission-badge.allowed {
  color: #715313;
  background: rgba(208, 170, 77, 0.14);
  border: 1px solid rgba(180, 145, 74, 0.26);
}

.admin-settings-permission-badge.protected {
  color: #7d5d28;
  background: rgba(242, 229, 193, 0.48);
  border: 1px solid rgba(180, 145, 74, 0.18);
}

.admin-settings-admin-list {
  display: grid;
  gap: 12px;
  margin-top: 20px;
}

.admin-settings-admin-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 16px;
  border: 1px solid rgba(180, 145, 74, 0.18);
  border-radius: 12px;
  background: #fffdf8;
}

.admin-settings-admin-main {
  min-width: 0;
}

.admin-settings-admin-name-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 5px;
}

.admin-settings-admin-name {
  color: #2d2318;
  font-size: 14px;
  font-weight: 750;
}

.admin-settings-admin-email {
  color: #887864;
  font-size: 12px;
  overflow-wrap: anywhere;
}

.admin-settings-admin-role {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  padding: 3px 8px;
  border-radius: 999px;
  color: #74571f;
  background: rgba(208, 170, 77, 0.13);
  border: 1px solid rgba(180, 145, 74, 0.2);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.admin-settings-admin-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 8px;
  color: #9a8b78;
  font-size: 11px;
}

.admin-settings-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 25px;
  padding: 4px 9px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  white-space: nowrap;
}

.admin-settings-status::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}

.admin-settings-status-active {
  color: #3d6b4a;
  background: rgba(96, 145, 109, 0.1);
  border: 1px solid rgba(96, 145, 109, 0.18);
}

.admin-settings-status-revoked {
  color: #91534b;
  background: rgba(164, 91, 80, 0.08);
  border: 1px solid rgba(164, 91, 80, 0.15);
}

.admin-settings-admin-actions {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 8px;
}

.admin-settings-management-button {
  min-height: 36px;
  padding: 8px 13px;
  border-radius: 9px;
  border: 1px solid rgba(180, 145, 74, 0.28);
  background: #fffaf0;
  color: #6f541d;
  font-size: 11px;
  font-weight: 750;
  cursor: pointer;
  transition:
    background 160ms ease,
    border-color 160ms ease,
    transform 160ms ease;
}

.admin-settings-management-button:hover:not(:disabled) {
  background: #f7eedc;
  border-color: rgba(180, 145, 74, 0.42);
  transform: translateY(-1px);
}

.admin-settings-management-button:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.admin-settings-management-button.danger {
  color: #8d4d45;
  border-color: rgba(164, 91, 80, 0.2);
  background: #fff8f5;
}

.admin-settings-management-button.danger:hover:not(:disabled) {
  background: #fdf0eb;
  border-color: rgba(164, 91, 80, 0.32);
}

.admin-settings-protected {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 34px;
  padding: 7px 10px;
  border-radius: 8px;
  background: rgba(242, 229, 193, 0.42);
  color: #806327;
  border: 1px solid rgba(180, 145, 74, 0.18);
  font-size: 10px;
  font-weight: 750;
  white-space: nowrap;
}

.admin-settings-management-error {
  margin-top: 14px;
  padding: 11px 13px;
  border-radius: 9px;
  color: #8d4d45;
  background: #fff6f3;
  border: 1px solid rgba(164, 91, 80, 0.15);
  font-size: 12px;
  line-height: 1.5;
}

.admin-settings-management-success {
  margin-top: 14px;
  padding: 11px 13px;
  border-radius: 9px;
  color: #46664f;
  background: #f5faf5;
  border: 1px solid rgba(96, 145, 109, 0.16);
  font-size: 12px;
  line-height: 1.5;
}

.admin-settings-management-loading {
  padding: 18px 0;
  color: #8b7a65;
  font-size: 12px;
}

@media (max-width: 720px) {
  .admin-settings-permission-row,
  .admin-settings-admin-row {
    align-items: flex-start;
    flex-direction: column;
  }

  .admin-settings-admin-actions {
    width: 100%;
  }

  .admin-settings-management-button,
  .admin-settings-protected {
    width: 100%;
    justify-content: center;
  }
}
/* =========================================================
   CONSULTANT ACTIONS
   ========================================================= */

.admin-consultant-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.admin-consultant-remove {
  border: 1px solid rgba(164, 91, 80, 0.22);
  background: #fff8f5;
  color: #8d4d45;
  border-radius: 8px;
  padding: 7px 11px;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  transition:
    background 160ms ease,
    border-color 160ms ease,
    transform 160ms ease;
}

.admin-consultant-remove:hover:not(:disabled) {
  background: #fdf0eb;
  border-color: rgba(164, 91, 80, 0.34);
  transform: translateY(-1px);
}

.admin-consultant-remove:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

@media (max-width: 760px) {
  .admin-consultant-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .admin-consultant-actions .admin-consultant-edit,
  .admin-consultant-actions .admin-consultant-remove {
    width: 100%;
  }
}
/* =========================================================
   ADMIN PORTAL — GLOBAL FORM FIELD SYSTEM
   ---------------------------------------------------------
   Final field-styling layer for admin pages.
   Scoped to .admin-shell so public website forms are untouched.
   ========================================================= */

/* =========================
   FIELD WRAPPERS
   ========================= */

.admin-shell label {
  color: var(--color-midnight);
}

.admin-shell label > span,
.admin-shell .admin-field-label,
.admin-shell .admin-form-label {
  display: block;
  margin-bottom: 7px;
  color: var(--color-midnight);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  line-height: 1.35;
}


/* =========================
   TEXT / EMAIL / PASSWORD /
   NUMBER / TEL / DATE / TIME
   ========================= */

.admin-shell input:not([type="checkbox"]):not([type="radio"]),
.admin-shell textarea,
.admin-shell select {
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  min-height: 46px;

  padding: 11px 13px;

  border: 1px solid var(--color-border);
  border-radius: 10px;

  outline: none;

  background: var(--color-white);
  color: var(--color-midnight);

  font: inherit;
  font-size: 0.86rem;
  line-height: 1.35;

  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.8);

  transition:
    border-color 180ms ease,
    background-color 180ms ease,
    box-shadow 180ms ease,
    color 180ms ease,
    transform 180ms ease;
}


/* =========================
   TEXTAREA
   ========================= */

.admin-shell textarea {
  min-height: 110px;
  resize: vertical;
  padding: 12px 13px;
}


/* =========================
   SELECT
   ========================= */

.admin-shell select {
  appearance: auto;
  cursor: pointer;
  padding-right: 36px;
}


/* =========================
   PLACEHOLDERS
   ========================= */

.admin-shell input::placeholder,
.admin-shell textarea::placeholder {
  color: #a9a298;
  opacity: 1;
}


/* =========================
   HOVER
   ========================= */

.admin-shell
  input:not([type="checkbox"]):not([type="radio"]):hover:not(:disabled):not([readonly]),
.admin-shell
  textarea:hover:not(:disabled):not([readonly]),
.admin-shell
  select:hover:not(:disabled) {
  border-color: rgba(214, 166, 59, 0.52);
}


/* =========================
   FOCUS
   ========================= */

.admin-shell
  input:not([type="checkbox"]):not([type="radio"]):focus,
.admin-shell
  textarea:focus,
.admin-shell
  select:focus {
  border-color: var(--color-gold);

  background: #fffdfa;

  box-shadow:
    0 0 0 3px rgba(214, 166, 59, 0.12),
    0 5px 16px rgba(7, 24, 42, 0.045);
}


/* =========================
   FOCUS VISIBLE
   ========================= */

.admin-shell
  input:not([type="checkbox"]):not([type="radio"]):focus-visible,
.admin-shell
  textarea:focus-visible,
.admin-shell
  select:focus-visible {
  border-color: var(--color-gold);

  box-shadow:
    0 0 0 3px rgba(214, 166, 59, 0.14),
    0 5px 16px rgba(7, 24, 42, 0.05);
}


/* =========================
   DISABLED
   ========================= */

.admin-shell
  input:not([type="checkbox"]):not([type="radio"]):disabled,
.admin-shell
  textarea:disabled,
.admin-shell
  select:disabled {
  cursor: not-allowed;

  background: #f4f2ee;
  border-color: #dedad3;

  color: #8e8a84;

  opacity: 0.8;

  box-shadow: none;
}


/* =========================
   READONLY
   ========================= */

.admin-shell
  input:not([type="checkbox"]):not([type="radio"])[readonly],
.admin-shell
  textarea[readonly] {
  background: #f8f6f2;
  color: #5f5a53;
}


/* =========================
   AUTOFILL
   ========================= */

.admin-shell
  input:-webkit-autofill,
.admin-shell
  input:-webkit-autofill:hover,
.admin-shell
  input:-webkit-autofill:focus {
  -webkit-text-fill-color: var(--color-midnight);

  box-shadow:
    0 0 0 1000px #fffdfa inset,
    0 0 0 3px rgba(214, 166, 59, 0.08);

  transition:
    background-color 9999s ease-in-out 0s;
}


/* =========================
   INVALID FIELDS
   ========================= */

.admin-shell
  input:not([type="checkbox"]):not([type="radio"]).is-invalid,
.admin-shell
  textarea.is-invalid,
.admin-shell
  select.is-invalid,
.admin-shell
  input:not([type="checkbox"]):not([type="radio"])[aria-invalid="true"],
.admin-shell
  textarea[aria-invalid="true"],
.admin-shell
  select[aria-invalid="true"] {
  border-color: #c84a43;

  background: #fffafa;

  box-shadow:
    0 0 0 3px rgba(200, 74, 67, 0.08);
}


/* =========================
   VALID FIELDS
   ========================= */

.admin-shell
  input:not([type="checkbox"]):not([type="radio"]).is-valid,
.admin-shell
  textarea.is-valid,
.admin-shell
  select.is-valid,
.admin-shell
  input:not([type="checkbox"]):not([type="radio"])[aria-invalid="false"],
.admin-shell
  textarea[aria-invalid="false"],
.admin-shell
  select[aria-invalid="false"] {
  border-color: #6b9e7b;
}


/* =========================
   FIELD HELP TEXT
   ========================= */

.admin-shell .admin-field-help,
.admin-shell .admin-form-help,
.admin-shell .field-help {
  display: block;

  margin-top: 6px;

  color: var(--color-muted);

  font-size: 0.72rem;
  line-height: 1.55;
}


/* =========================
   FIELD ERROR TEXT
   ========================= */

.admin-shell .admin-field-error,
.admin-shell .admin-form-error,
.admin-shell .field-error {
  display: block;

  margin-top: 6px;

  color: #b42318;

  font-size: 0.72rem;
  font-weight: 600;
  line-height: 1.5;
}


/* =========================
   REQUIRED MARKER
   ========================= */

.admin-shell .required,
.admin-shell .admin-required {
  color: #b42318;
}


/* =========================
   CHECKBOX / RADIO
   ========================= */

.admin-shell
  input[type="checkbox"],
.admin-shell
  input[type="radio"] {
  width: 16px;
  height: 16px;

  margin: 0;

  accent-color: var(--color-gold);

  cursor: pointer;
}

.admin-shell
  input[type="checkbox"]:disabled,
.admin-shell
  input[type="radio"]:disabled {
  cursor: not-allowed;
}


/* =========================
   CHECKBOX / RADIO LABEL ROW
   ========================= */

.admin-shell
  label:has(input[type="checkbox"]),
.admin-shell
  label:has(input[type="radio"]) {
  display: flex;
  align-items: center;

  gap: 9px;

  cursor: pointer;
}

.admin-shell
  label:has(input[type="checkbox"]:disabled),
.admin-shell
  label:has(input[type="radio"]:disabled) {
  cursor: not-allowed;
}


/* =========================
   ADMIN SEARCH FIELDS
   ========================= */

.admin-shell
  .admin-search-input,
.admin-shell
  .admin-consultants-search,
.admin-shell
  input[type="search"] {
  min-height: 44px;
  border-radius: 11px;
}


/* =========================
   ADMIN SETTINGS FIELDS
   ========================= */

.admin-shell
  .admin-settings-card
  input:not([type="checkbox"]):not([type="radio"]),
.admin-shell
  .admin-settings-card
  textarea,
.admin-shell
  .admin-settings-card
  select {
  min-height: 48px;
  border-radius: 11px;
}


