.booking-calendar-day {
  position: relative;
  min-height: 72px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid transparent;
  border-radius: 14px;
  background: #f8f6f0;
  color: #aaa39a;
  font-size: .95rem;
  font-weight: 600;
  cursor: not-allowed;
  transition: transform .2s ease, border-color .2s ease, background .2s ease, box-shadow .2s ease;
}

.booking-calendar-day.is-available {
  background: #ffffff;
  border-color: var(--color-border);
  color: var(--color-midnight);
  cursor: pointer;
}

.booking-calendar-day.is-available:hover {
  transform: translateY(-2px);
  border-color: var(--color-gold-light);
  background: #fffaf0;
  box-shadow: 0 8px 22px rgba(7, 24, 42, .10);
}

.booking-calendar-day.is-selected {
  border-color: var(--color-gold-light);
  background: #fff8df;
  color: var(--color-midnight);
  box-shadow: 0 0 0 2px rgba(214, 166, 59, .22);
}

.booking-calendar-day.is-today .booking-calendar-day-number {
  font-weight: 800;
}

.booking-calendar-day.has-booking:not(.is-available) {
  background: #fff7f6;
  border-color: rgba(184, 93, 82, .16);
  color: #7c403a;
}

.booking-calendar-day-dot {
  position: absolute;
  bottom: 9px;
  left: 50%;
  transform: translateX(-50%);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  min-height: 7px;
}

.booking-calendar-day-dot i,
.booking-calendar-legend-dot {
  display: inline-block;
  width: 7px;
  height: 7px;
  flex: 0 0 7px;
  border-radius: 50%;
}

.booking-calendar-day-dot .is-available,
.booking-calendar-legend-dot.is-available {
  background: #4f8a66;
}

.booking-calendar-day-dot .is-booked,
.booking-calendar-legend-dot.is-booked {
  background: #b85d52;
}

.booking-calendar-legend {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 10px 22px;
  margin-top: 20px;
  color: var(--color-muted);
  font-size: .78rem;
}

.booking-calendar-legend span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
}

.booking-calendar-legend-dot.is-selected {
  background: var(--color-gold);
}

.booking-calendar-day:disabled {
  opacity: .88;
}

@media (max-width: 560px) {
  .booking-calendar-day {
    min-height: 60px;
    border-radius: 11px;
    font-size: .86rem;
  }

  .booking-calendar-day-dot {
    bottom: 7px;
  }

  .booking-calendar-legend {
    gap: 9px 15px;
  }
}
