/* =========================================================
   HOMEPAGE — LANDING / RESPONSIVE UI POLISH
   Append to the end of globals.css.
   Existing data, APIs and booking flows are untouched.
   ========================================================= */

/* Hero: make the first impression more intentional without rebuilding
   the existing live 3D system. */
.hero-live .hero-content {
  position: relative;
  z-index: 20;
}

.hero-live .hero-eyebrow {
  margin-bottom: 14px;
}

.hero-live .hero-title {
  max-width: 760px;
  text-wrap: balance;
}

.hero-live .hero-description {
  max-width: 610px;
}

.hero-live .hero-actions .btn {
  min-height: 50px;
}

.hero-live .hero-trust > div {
  position: relative;
  padding-left: 16px;
}

.hero-live .hero-trust > div::before {
  content: "";
  position: absolute;
  left: 0;
  top: 3px;
  bottom: 3px;
  width: 1px;
  background: linear-gradient(to bottom, var(--color-gold), transparent);
}

/* Trust becomes a transition from the emotional hero into practical choices. */
.trust-card {
  min-height: 205px;
}

.trust-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 23px;
}

.trust-card-index {
  color: var(--color-gold-dark);
  font-size: .62rem;
  font-weight: 800;
  letter-spacing: .16em;
}

.trust-card-mark {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border: 1px solid rgba(214,166,59,.28);
  border-radius: 50%;
  color: var(--color-gold-dark);
  font-size: .78rem;
  background: rgba(214,166,59,.06);
}

.home-next-step {
  display: grid;
  grid-template-columns: minmax(220px, .72fr) minmax(0, 1.55fr);
  align-items: center;
  gap: 24px;
  margin-top: 22px;
  padding: 19px 20px 19px 23px;
  border: 1px solid rgba(214,166,59,.23);
  border-radius: 22px;
  background: linear-gradient(135deg, rgba(7,24,42,.97), rgba(13,42,68,.92));
  box-shadow: 0 18px 44px rgba(7,24,42,.12);
}

.home-next-step-copy .eyebrow {
  margin: 0 0 7px;
  color: var(--color-gold-light);
  font-size: .58rem;
}

.home-next-step-copy strong {
  display: block;
  color: rgba(255,255,255,.93);
  font-family: var(--font-heading), Georgia, serif;
  font-size: 1.15rem;
  font-weight: 500;
  line-height: 1.3;
}

.home-next-step-links {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.home-next-step-link {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 9px;
  min-height: 48px;
  padding: 10px 13px;
  border: 1px solid rgba(255,255,255,.11);
  border-radius: 13px;
  color: rgba(255,255,255,.78);
  background: rgba(255,255,255,.035);
  font-size: .72rem;
  font-weight: 650;
  text-decoration: none;
  transition: transform .22s ease, border-color .22s ease, background .22s ease, color .22s ease;
}

.home-next-step-link b {
  color: var(--color-gold-light);
  font-size: .95rem;
  font-weight: 500;
}

.home-next-step-link:hover,
.home-next-step-link:focus-visible {
  transform: translateY(-2px);
  border-color: rgba(231,195,108,.42);
  color: #fff;
  background: rgba(255,255,255,.075);
}

.home-next-step-link-primary {
  border-color: rgba(231,195,108,.4);
  color: #07182a;
  background: linear-gradient(135deg, #f0d58a, #d6a63b);
}

.home-next-step-link-primary b {
  color: #07182a;
}

/* Process: turn four cards into a visual journey on larger screens. */
.process-grid {
  position: relative;
}

.process-card {
  z-index: 1;
}

.process-connector {
  position: absolute;
  left: calc(100% + 1px);
  top: 32px;
  width: 19px;
  height: 1px;
  background: linear-gradient(90deg, rgba(214,166,59,.65), rgba(214,166,59,.12));
}

/* Testimonials: add a subtle editorial quote treatment. */
.testimonial-card {
  overflow: hidden;
}

.testimonial-quote-mark {
  position: absolute;
  top: 4px;
  right: 22px;
  color: rgba(214,166,59,.13);
  font-family: Georgia, serif;
  font-size: 5rem;
  line-height: 1;
  pointer-events: none;
}

.testimonial-card:hover {
  transform: translateY(-6px);
  border-color: rgba(214,166,59,.45);
  box-shadow: 0 18px 42px rgba(7,24,42,.11);
}

/* Stronger keyboard navigation throughout the landing page. */
.home-next-step-link:focus-visible,
.hero-live-options button:focus-visible,
.hero-live .btn:focus-visible {
  outline: 2px solid var(--color-gold);
  outline-offset: 3px;
}

@media (max-width: 1050px) {
  .home-next-step {
    grid-template-columns: 1fr;
  }

  .home-next-step-links {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .process-connector {
    display: none;
  }
}

@media (max-width: 700px) {
  .hero-live .hero-title {
    max-width: 100%;
    font-size: clamp(2.8rem, 12vw, 4rem);
  }

  .hero-live .hero-description {
    font-size: .91rem;
    line-height: 1.7;
  }

  .hero-live .hero-actions {
    gap: 9px;
  }

  .hero-live .hero-actions .btn {
    min-height: 48px;
  }

  .hero-live .hero-trust {
    gap: 12px;
    margin-top: 28px;
  }

  .hero-live .hero-trust > div {
    padding-left: 11px;
  }

  .home-next-step {
    margin-top: 18px;
    padding: 18px 16px;
    border-radius: 18px;
  }

  .home-next-step-links {
    grid-template-columns: 1fr;
  }

  .home-next-step-link {
    min-height: 46px;
  }

  .trust-card {
    min-height: 0;
    padding: 25px 23px;
  }

  .process-card,
  .testimonial-card {
    padding: 27px 23px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .home-next-step-link,
  .testimonial-card,
  .trust-card {
    transition: none !important;
  }
}
/* =========================================================
ADMIN — FEEDBACK & REVIEWS
Premium moderation interface
Scoped exclusively to .admin-feedback-page
========================================================= */

.admin-feedback-page {
--feedback-gold: var(--color-gold);
--feedback-gold-light: var(--color-gold-light);
--feedback-gold-dark: var(--color-gold-dark);
--feedback-ink: var(--color-midnight);
--feedback-muted: var(--color-muted);
--feedback-border: var(--color-border);

position: relative;
}

/* ---------- Page header ---------- */

.admin-feedback-page .admin-page-header {
position: relative;
display: flex;
align-items: flex-end;
justify-content: space-between;
gap: 28px;
margin-bottom: 28px;
padding: 4px 2px 22px;
border-bottom: 1px solid rgba(228, 218, 198, 0.72);
}

.admin-feedback-page .admin-page-header::after {
content: "";
position: absolute;
left: 0;
bottom: -1px;
width: 76px;
height: 2px;
border-radius: 999px;
background: linear-gradient(
90deg,
var(--feedback-gold-dark),
var(--feedback-gold-light),
transparent
);
}

.admin-feedback-page .admin-topbar-eyebrow {
margin: 0 0 7px;
color: var(--feedback-gold-dark);
font-size: 0.64rem;
font-weight: 800;
letter-spacing: 0.16em;
text-transform: uppercase;
}

.admin-feedback-page .admin-page-title {
margin: 0;
color: var(--feedback-ink);
font-family: var(--font-heading), Georgia, serif;
font-size: clamp(2rem, 4vw, 3rem);
font-weight: 500;
line-height: 1.08;
letter-spacing: -0.025em;
}

.admin-feedback-page .admin-page-description {
max-width: 720px;
margin: 12px 0 0;
color: var(--feedback-muted);
font-size: 0.88rem;
line-height: 1.75;
}

/* ---------- Refresh button ---------- */

.admin-feedback-page .admin-bookings-refresh {
position: relative;
flex: 0 0 auto;
min-height: 44px;
padding: 0 18px;
border: 1px solid rgba(214, 166, 59, 0.3);
border-radius: 999px;
background: rgba(255, 255, 255, 0.78);
color: var(--feedback-ink);
font-size: 0.76rem;
font-weight: 750;
box-shadow: 0 7px 22px rgba(7, 24, 42, 0.05);
transition:
transform 220ms ease,
border-color 220ms ease,
background 220ms ease,
box-shadow 220ms ease;
}

.admin-feedback-page .admin-bookings-refresh:hover:not(:disabled) {
transform: translateY(-2px);
border-color: rgba(214, 166, 59, 0.62);
background: #fff;
box-shadow: 0 12px 28px rgba(7, 24, 42, 0.09);
}

.admin-feedback-page .admin-bookings-refresh:disabled {
cursor: wait;
opacity: 0.58;
}

.admin-feedback-page .admin-bookings-refresh:focus-visible,
.admin-feedback-page button:focus-visible,
.admin-feedback-page input:focus-visible,
.admin-feedback-page textarea:focus-visible {
outline: 2px solid rgba(214, 166, 59, 0.75);
outline-offset: 3px;
}

/* ---------- Alerts ---------- */

.admin-feedback-page .admin-alert {
position: relative;
overflow: hidden;
border-radius: 14px;
padding: 13px 16px !important;
font-size: 0.78rem;
line-height: 1.55;
animation: feedbackAlertIn 360ms cubic-bezier(0.22, 1, 0.36, 1);
}

.admin-feedback-page .admin-alert::before {
content: "";
position: absolute;
left: 0;
top: 0;
bottom: 0;
width: 3px;
}

.admin-feedback-page .admin-alert-error {
border: 1px solid rgba(173, 66, 66, 0.16);
background: rgba(173, 66, 66, 0.055);
color: #913939;
}

.admin-feedback-page .admin-alert-error::before {
background: #a33f3f;
}

.admin-feedback-page .admin-alert-success {
border: 1px solid rgba(53, 133, 83, 0.16);
background: rgba(53, 133, 83, 0.055);
color: #356f4b;
}

.admin-feedback-page .admin-alert-success::before {
background: #4b8d63;
}

@keyframes feedbackAlertIn {
from {
opacity: 0;
transform: translateY(-8px);
}

to {
opacity: 1;
transform: translateY(0);
}
}

/* ---------- Main card ---------- */

.admin-feedback-page .admin-table-card {
position: relative;
overflow: hidden;
border: 1px solid rgba(228, 218, 198, 0.92);
border-radius: 24px;
background:
radial-gradient(
circle at 100% 0%,
rgba(214, 166, 59, 0.065),
transparent 30%
),
rgba(255, 255, 255, 0.92);
box-shadow:
0 18px 55px rgba(7, 24, 42, 0.065),
0 2px 8px rgba(7, 24, 42, 0.025);
animation: feedbackCardIn 520ms cubic-bezier(0.22, 1, 0.36, 1);
}

.admin-feedback-page .admin-table-card::before {
content: "";
position: absolute;
left: 0;
right: 0;
top: 0;
height: 2px;
background: linear-gradient(
90deg,
transparent,
rgba(214, 166, 59, 0.75),
rgba(231, 195, 108, 0.35),
transparent
);
}

@keyframes feedbackCardIn {
from {
opacity: 0;
transform: translateY(12px);
}

to {
opacity: 1;
transform: translateY(0);
}
}

/* ---------- Toolbar ---------- */

.admin-feedback-page .admin-feedback-toolbar {
position: relative;
padding: 18px 22px !important;
border-bottom: 1px solid rgba(228, 218, 198, 0.7) !important;
background:
linear-gradient(
180deg,
rgba(250, 247, 239, 0.78),
rgba(255, 255, 255, 0.55)
);
}

.admin-feedback-page .admin-filter-button {
position: relative;
min-height: 38px;
padding: 0 14px;
border: 1px solid rgba(228, 218, 198, 0.9);
border-radius: 999px;
background: rgba(255, 255, 255, 0.72);
color: rgba(41, 41, 41, 0.68);
font-size: 0.7rem;
font-weight: 700;
white-space: nowrap;
transition:
color 180ms ease,
background 180ms ease,
border-color 180ms ease,
transform 180ms ease,
box-shadow 180ms ease;
}

.admin-feedback-page .admin-filter-button:hover {
transform: translateY(-1px);
border-color: rgba(214, 166, 59, 0.42);
color: var(--feedback-ink);
background: #fff;
}

.admin-feedback-page .admin-filter-button.is-active {
