box-shadow:
0 5px 15px rgba(214, 166, 59, 0.1),
inset 0 0 0 1px rgba(255, 255, 255, 0.5);
}

.admin-feedback-page .admin-filter-button.is-active::after {
content: "";
position: absolute;
