color: var(--feedback-gold) !important;
font-size: 0.83rem !important;
box-shadow: inset 0 1px rgba(255, 255, 255, 0.7);
}

.admin-feedback-page .admin-table td span[aria-label*="out of 5 stars"] span {
display: inline-block;
transition: transform 180ms ease;
}

.admin-feedback-page .admin-table tr:hover span[aria-label*="out of 5 stars"] span {
transform: translateY(-1px);
}

/* ---------- Status ---------- */

.admin-feedback-page .admin-status-badge {
position: relative;
gap: 6px;
padding: 6px 10px;
border-width: 1px;
font-size: 0.59rem;
letter-spacing: 0.065em;
transition:
transform 180ms ease,
box-shadow 180ms ease;
}

.admin-feedback-page .admin-status-badge::before {
content: "";
width: 5px;
height: 5px;
flex: 0 0 5px;
border-radius: 50%;
background: currentColor;
opacity: 0.75;
}

.admin-feedback-page .admin-status-pending {
background: rgba(214, 166, 59, 0.1);
color: var(--feedback-gold-dark);
border-color: rgba(214, 166, 59, 0.2);
}

.admin-feedback-page .admin-status-pending::before {
animation: pendingDot 1.8s ease-in-out infinite;
}

@keyframes pendingDot {
0%,
100% {
opacity: 0.45;
transform: scale(0.85);
}

50% {
opacity: 1;
transform: scale(1.2);
}
}

.admin-feedback-page .admin-status-approved {
background: rgba(53, 133, 83, 0.085);
color: #356f4b;
border-color: rgba(53, 133, 83, 0.16);
}

.admin-feedback-page .admin-status-rejected {
background: rgba(173, 66, 66, 0.075);
color: #9a3d3d;
border-color: rgba(173, 66, 66, 0.14);
}

.admin-feedback-page .admin-status-badge:hover {
transform: translateY(-1px);
}

/* ---------- Published label ---------- */

.admin-feedback-page .admin-table td div[style*="Published"] {
display: inline-flex;
align-items: center;
gap: 5px;
color: #356f4b !important;
font-size: 0.61rem !important;
letter-spacing: 0.03em;
}

.admin-feedback-page .admin-table td div[style*="Published"]::before {
content: "✓";
display: grid;
width: 15px;
height: 15px;
place-items: center;
border-radius: 50%;
background: rgba(53, 133, 83, 0.09);
font-size: 0.55rem;
}

/* ---------- Review / secondary buttons ---------- */

.admin-feedback-page .admin-service-cancel {
min-height: 36px;
padding: 0 13px;
border: 1px solid rgba(228, 218, 198, 0.95);
border-radius: 10px;
background: rgba(255, 255, 255, 0.8);
color: var(--feedback-ink);
font-size: 0.69rem;
font-weight: 750;
white-space: nowrap;
transition:
transform 180ms ease,
border-color 180ms ease,
background 180ms ease,
color 180ms ease,
box-shadow 180ms ease;
}

.admin-feedback-page .admin-service-cancel:hover:not(:disabled) {
transform: translateY(-2px);
border-color: rgba(214, 166, 59, 0.45);
background: #fff;
color: var(--feedback-gold-dark);
box-shadow: 0 7px 18px rgba(7, 24, 42, 0.07);
}

.admin-feedback-page .admin-service-cancel:disabled,
.admin-feedback-page .admin-services-add:disabled {
cursor: wait;
opacity: 0.5;
}

/* ---------- Empty state ---------- */

.admin-feedback-page .admin-empty-state {
position: relative;
overflow: hidden;
background:
radial-gradient(
circle at 50% 0%,
rgba(214, 166, 59, 0.075),
transparent 36%
) !important;
}

.admin-feedback-page .admin-empty-state > div > div:first-child {
position: relative;
border-color: rgba(214, 166, 59, 0.28) !important;
background:
radial-gradient(
circle,
rgba(214, 166, 59, 0.12),
rgba(214, 166, 59, 0.035)
) !important;
box-shadow: 0 10px 30px rgba(214, 166, 59, 0.08);
animation: emptyStarFloat 3.5s ease-in-out infinite;
}

@keyframes emptyStarFloat {
0%,
100% {
transform: translateY(0);
}

50% {
transform: translateY(-5px);
}
}

.admin-feedback-page .admin-empty-state strong {
letter-spacing: -0.01em;
}

/* ---------- Loading ---------- */

.admin-feedback-page .admin-empty-state:has(> span),
.admin-feedback-page .admin-empty-state {
transition: opacity 250ms ease;
}

.admin-feedback-page .admin-empty-state {
color: var(--feedback-muted);
}

/* ---------- Pagination ---------- */

.admin-feedback-page .admin-table-card > div:last-child button {
transition:
transform 180ms ease,
border-color 180ms ease,
background 180ms ease,
box-shadow 180ms ease;
}

.admin-feedback-page .admin-table-card > div:last-child button:hover:not(:disabled) {
transform: translateY(-2px);
}

.admin-feedback-page .admin-table-card > div:last-child button:disabled {
opacity: 0.4;
cursor: not-allowed;
}

.admin-feedback-page .admin-table-card > div:last-child span {
padding: 7px 13px;
border: 1px solid rgba(228, 218, 198, 0.75);
border-radius: 999px;
background: rgba(250, 247, 239, 0.45);
}

/* =========================================================
FEEDBACK REVIEW MODAL
========================================================= */

.admin-feedback-page > div[role="dialog"] {
background: rgba(4, 14, 24, 0.66) !important;
backdrop-filter: blur(12px);
-webkit-backdrop-filter: blur(12px);
animation: feedbackOverlayIn 260ms ease;
}

@keyframes feedbackOverlayIn {
from {
opacity: 0;
}

to {
opacity: 1;
}
}

.admin-feedback-page > div[role="dialog"] > div {
position: relative;
overflow: hidden;
border: 1px solid rgba(214, 166, 59, 0.24) !important;
border-radius: 26px !important;
background:
radial-gradient(
circle at 100% 0%,
rgba(214, 166, 59, 0.08),
transparent 32%
),
#fff !important;
box-shadow:
0 35px 100px rgba(0, 0, 0, 0.3),
0 8px 30px rgba(0, 0, 0, 0.12) !important;
animation: feedbackModalIn 420ms cubic-bezier(0.22, 1, 0.36, 1);
}

.admin-feedback-page > div[role="dialog"] > div::before {
content: "";
position: absolute;
left: 0;
right: 0;
top: 0;
height: 3px;
background: linear-gradient(
90deg,
transparent,
var(--feedback-gold),
var(--feedback-gold-light),
transparent
);
}

@keyframes feedbackModalIn {
from {
opacity: 0;
transform: translateY(22px) scale(0.975);
}

to {
opacity: 1;
transform: translateY(0) scale(1);
}
}

/* ---------- Modal header ---------- */

.admin-feedback-page > div[role="dialog"] > div > div:first-child {
padding: 25px 28px 20px !important;
background:
linear-gradient(
180deg,
rgba(250, 247, 239, 0.55),
rgba(255, 255, 255, 0)
);
}

.admin-feedback-page > div[role="dialog"] h2 {
letter-spacing: -0.02em;
}

.admin-feedback-page > div[role="dialog"] button[aria-label="Close feedback review"] {
transition:
transform 180ms ease,
background 180ms ease,
border-color 180ms ease;
}

.admin-feedback-page > div[role="dialog"] button[aria-label="Close feedback review"]:hover:not(:disabled) {
transform: rotate(90deg);
border-color: rgba(214, 166, 59, 0.4) !important;
background: rgba(214, 166, 59, 0.07) !important;
}

/* ---------- Modal content ---------- */

.admin-feedback-page > div[role="dialog"] > div > div:nth-child(2) {
gap: 24px !important;
padding: 25px 28px 30px !important;
}

/* ---------- Modal info cards ---------- */

.admin-feedback-page > div[role="dialog"] > div > div:nth-child(2) > div:first-child > div {
position: relative;
overflow: hidden;
border-color: rgba(228, 218, 198, 0.8) !important;
border-radius: 16px !important;
background:
linear-gradient(
145deg,
rgba(250, 247, 239, 0.78),
rgba(255, 255, 255, 0.9)
) !important;
transition:
transform 200ms ease,
border-color 200ms ease,
box-shadow 200ms ease;
}

.admin-feedback-page > div[role="dialog"] > div > div:nth-child(2) > div:first-child > div:hover {
transform: translateY(-2px);
border-color: rgba(214, 166, 59, 0.28) !important;
box-shadow: 0 8px 22px rgba(7, 24, 42, 0.05);
}

/* ---------- Customer feedback quote ---------- */

.admin-feedback-page > div[role="dialog"] > div > div:nth-child(2) > div:nth-child(2) > div {
position: relative;
overflow: hidden;
border-color: rgba(214, 166, 59, 0.2) !important;
border-radius: 18px !important;
background:
linear-gradient(
145deg,
rgba(214, 166, 59, 0.065),
rgba(250, 247, 239, 0.5)
) !important;
box-shadow: inset 0 1px rgba(255, 255, 255, 0.65);
}

.admin-feedback-page > div[role="dialog"] > div > div:nth-child(2) > div:nth-child(2) > div::before {
content: "“";
position: absolute;
right: 16px;
top: -5px;
color: rgba(214, 166, 59, 0.11);
font-family: Georgia, serif;
font-size: 5rem;
line-height: 1;
pointer-events: none;
}

/* ---------- Admin note ---------- */

.admin-feedback-page #feedback-admin-note {
min-height: 112px !important;
border-radius: 14px !important;
line-height: 1.65;
}

/* ---------- Modal actions ---------- */

.admin-feedback-page > div[role="dialog"] > div > div:nth-child(2) > div:last-child {
padding-top: 10px !important;
}

.admin-feedback-page > div[role="dialog"] .admin-services-add {
min-height: 42px;
border-radius: 12px;
}

.admin-feedback-page > div[role="dialog"] .admin-service-cancel {
min-height: 42px;
border-radius: 12px;
}

/* =========================================================
RESPONSIVE
========================================================= */

@media (max-width: 900px) {
.admin-feedback-page .admin-page-header {
align-items: flex-start;
flex-direction: column;
gap: 18px;
}

.admin-feedback-page .admin-bookings-refresh {
width: auto;
}

.admin-feedback-page .admin-feedback-toolbar {
align-items: stretch !important;
}

.admin-feedback-page .admin-feedback-toolbar > div:first-child {
width: 100%;
overflow-x: auto;
flex-wrap: nowrap !important;
padding-bottom: 3px;
scrollbar-width: none;
}

.admin-feedback-page .admin-feedback-toolbar > div:first-child::-webkit-scrollbar {
display: none;
}

.admin-feedback-page .admin-feedback-toolbar form {
justify-content: stretch !important;
flex: 1 1 100% !important;
}

.admin-feedback-page .admin-feedback-toolbar form .admin-search-input {
width: 100% !important;
flex: 1 1 auto;
}

.admin-feedback-page .admin-table {
min-width: 900px;
}
}

@media (max-width: 680px) {
.admin-feedback-page .admin-page-title {
font-size: clamp(1.8rem, 9vw, 2.35rem);
}

.admin-feedback-page .admin-page-description {
font-size: 0.82rem;
}

.admin-feedback-page .admin-bookings-refresh {
width: 100%;
}

.admin-feedback-page .admin-table-card {
border-radius: 19px;
}

.admin-feedback-page .admin-feedback-toolbar {
padding: 15px !important;
gap: 12px !important;
}

.admin-feedback-page .admin-filter-button {
min-height: 36px;
padding-inline: 12px;
font-size: 0.65rem;
}

.admin-feedback-page .admin-feedback-toolbar form {
display: grid !important;
grid-template-columns: 1fr auto;
gap: 7px !important;
}

.admin-feedback-page .admin-services-add {
padding-inline: 14px;
}

.admin-feedback-page .admin-table-card > div[style*="fontSize"] {
padding-inline: 15px !important;
}

.admin-feedback-page > div[role="dialog"] {
place-items: end center !important;
padding: 0 !important;
}

.admin-feedback-page > div[role="dialog"] > div {
width: 100% !important;
max-height: min(88vh, 820px) !important;
border-radius: 24px 24px 0 0 !important;
animation: feedbackSheetIn 420ms cubic-bezier(0.22, 1, 0.36, 1);
}

@keyframes feedbackSheetIn {
from {
opacity: 0;
transform: translateY(100%);
}



to {
  opacity: 1;
  transform: translateY(0);
}

}

.admin-feedback-page > div[role="dialog"] > div > div:first-child {
padding: 21px 20px 17px !important;
}

.admin-feedback-page > div[role="dialog"] > div > div:nth-child(2) {
padding: 20px 20px 24px !important;
}

.admin-feedback-page > div[role="dialog"] > div > div:nth-child(2) > div:first-child {
grid-template-columns: 1fr 1fr !important;
}

.admin-feedback-page > div[role="dialog"] > div > div:nth-child(2) > div:last-child {
justify-content: stretch !important;
}

.admin-feedback-page > div[role="dialog"] > div > div:nth-child(2) > div:last-child button {
flex: 1 1 calc(50% - 5px);
}
}

@media (max-width: 430px) {
.admin-feedback-page .admin-page-header {
padding-bottom: 18px;
}

.admin-feedback-page .admin-feedback-toolbar form {
grid-template-columns: 1fr;
}

.admin-feedback-page .admin-services-add {
width: 100%;
}

.admin-feedback-page > div[role="dialog"] > div > div:nth-child(2) > div:first-child {
grid-template-columns: 1fr !important;
}

.admin-feedback-page > div[role="dialog"] > div > div:nth-child(2) > div:last-child {
flex-direction: column;
}

.admin-feedback-page > div[role="dialog"] > div > div:nth-child(2) > div:last-child button {
width: 100%;
flex: 1 1 auto;
}
}

/* =========================================================
REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {
.admin-feedback-page *,
.admin-feedback-page *::before,
.admin-feedback-page *::after {
animation-duration: 0.01ms !important;
animation-iteration-count: 1 !important;
scroll-behavior: auto !important;
transition-duration: 0.01ms !important;
}
}
/* =========================================================
CONTACT PAGE
Premium responsive contact + feedback experience
========================================================= */

.contact-page {
position: relative;
width: 100%;
overflow: hidden;
background:
radial-gradient(circle at 8% 18%, rgba(214, 166, 59, 0.07), transparent 28%),
radial-gradient(circle at 92% 42%, rgba(13, 34, 56, 0.045), transparent 30%);
}

.contact-section {
width: min(1180px, calc(100% - 40px));
margin: 0 auto;
padding: 76px 0 100px;
}

.contact-intro-grid {
display: grid;
grid-template-columns: minmax(0, 1.25fr) minmax(300px, 0.75fr);
align-items: end;
gap: 44px;
margin-bottom: 34px;
}

.contact-intro {
max-width: 720px;
}

.contact-form-badge {
display: inline-flex;
align-items: center;
min-height: 30px;
padding: 0 11px;
border: 1px solid rgba(214, 166, 59, 0.32);
border-radius: 999px;
background: rgba(214, 166, 59, 0.07);
color: var(--color-gold-dark);
font-size: 0.66rem;
font-weight: 850;
letter-spacing: 0.13em;
line-height: 1;
text-transform: uppercase;
}

.contact-intro h2,
.contact-form-heading h2 {
margin: 13px 0 0;
color: var(--color-midnight);
font-family: var(--font-heading), Georgia, serif;
font-weight: 600;
letter-spacing: -0.025em;
}

.contact-intro h2 {
font-size: clamp(2.15rem, 4vw, 3.55rem);
line-height: 1.04;
}

.contact-intro p {
max-width: 650px;
margin: 17px 0 0;
color: var(--color-muted);
font-size: 0.94rem;
line-height: 1.8;
}

.contact-trust-card {
display: flex;
align-items: flex-start;
gap: 15px;
padding: 20px 21px;
border: 1px solid rgba(214, 166, 59, 0.24);
border-radius: 18px;
background:
linear-gradient(
135deg,
rgba(214, 166, 59, 0.10),
rgba(255, 255, 255, 0.82)
);
box-shadow: 0 18px 45px rgba(23, 28, 45, 0.07);
}

.contact-trust-card > span {
display: grid;
width: 38px;
height: 38px;
flex: 0 0 38px;
place-items: center;
border-radius: 12px;
background: var(--color-midnight);
color: var(--color-gold-light);
font-size: 0.9rem;
}

.contact-trust-card strong {
display: block;
color: var(--color-midnight);
font-size: 0.84rem;
font-weight: 800;
}

.contact-trust-card p {
margin: 5px 0 0;
color: var(--color-muted);
font-size: 0.73rem;
line-height: 1.65;
}

/* Mode selector */

.contact-mode-switch {
position: relative;
display: grid;
grid-template-columns: 1fr 1fr;
gap: 6px;
width: min(620px, 100%);
margin: 0 auto 28px;
padding: 5px;
border: 1px solid var(--color-border);
border-radius: 17px;
background: rgba(31, 38, 56, 0.045);
box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.65);
}

.contact-mode-switch button {
position: relative;
display: inline-flex;
min-height: 52px;
align-items: center;
justify-content: center;
gap: 9px;
border: 1px solid transparent;
border-radius: 12px;
background: transparent;
color: var(--color-muted);
cursor: pointer;
font: inherit;
font-size: 0.77rem;
font-weight: 800;
letter-spacing: 0.025em;
transition:
color 220ms ease,
background 220ms ease,
border-color 220ms ease,
box-shadow 220ms ease,
transform 220ms ease;
}

.contact-mode-switch button span {
color: var(--color-gold-dark);
font-size: 0.82rem;
}

.contact-mode-switch button:hover {
color: var(--color-midnight);
background: rgba(255, 255, 255, 0.58);
}

.contact-mode-switch button.active {
border-color: rgba(214, 166, 59, 0.30);
background: var(--color-white);
color: var(--color-midnight);
box-shadow:
0 7px 18px rgba(23, 28, 45, 0.08),
0 1px 2px rgba(23, 28, 45, 0.06);
}

.contact-mode-switch button:active {
transform: translateY(1px);
}

.contact-mode-switch button:focus-visible {
outline: 3px solid rgba(214, 166, 59, 0.22);
outline-offset: 2px;
}

/* Main form */

.contact-form-card {
position: relative;
width: 100%;
overflow: hidden;
padding: clamp(27px, 4vw, 46px);
border: 1px solid var(--color-border);
border-radius: 24px;
background:
linear-gradient(
145deg,
rgba(255, 255, 255, 0.98),
rgba(250, 247, 239, 0.88)
);
box-shadow:
0 25px 70px rgba(23, 28, 45, 0.09),
0 2px 8px rgba(23, 28, 45, 0.035);
animation: contact-card-enter 500ms cubic-bezier(.22, .75, .25, 1) both;
}

.contact-form-card::before {
position: absolute;
top: 0;
left: 0;
width: 100%;
height: 3px;
background: linear-gradient(
90deg,
transparent,
var(--color-gold),
transparent
);
content: "";
opacity: 0.75;
}

.contact-form-heading {
margin-bottom: 30px;
}

.contact-form-heading h2 {
font-size: clamp(1.65rem, 3vw, 2.35rem);
line-height: 1.1;
}

.contact-form-heading p {
max-width: 680px;
margin: 10px 0 0;
color: var(--color-muted);
font-size: 0.83rem;
line-height: 1.7;
}

.contact-form {
display: block;
}

.contact-form-grid {
display: grid;
grid-template-columns: repeat(2, minmax(0, 1fr));
gap: 22px 20px;
}

.contact-field {
min-width: 0;
}

.contact-field-full {
grid-column: 1 / -1;
}

.contact-field label {
display: block;
margin-bottom: 8px;
color: var(--color-midnight);
font-size: 0.73rem;
font-weight: 800;
letter-spacing: 0.025em;
}

.contact-field label span {
color: var(--color-gold-dark);
}

.contact-field input,
.contact-field select,
.contact-field textarea {
display: block;
width: 100%;
border: 1px solid rgba(31, 38, 56, 0.14);
border-radius: 13px;
background: rgba(255, 255, 255, 0.86);
color: var(--color-midnight);
font: inherit;
font-size: 0.83rem;
outline: none;
box-shadow: 0 1px 2px rgba(23, 28, 45, 0.025);
transition:
border-color 200ms ease,
box-shadow 200ms ease,
background 200ms ease,
transform 200ms ease;
}

.contact-field input,
.contact-field select {
min-height: 48px;
padding: 0 14px;
}

.contact-field textarea {
min-height: 170px;
padding: 13px 14px;
resize: vertical;
line-height: 1.7;
}

.contact-field input::placeholder,
.contact-field textarea::placeholder {
color: #9a9388;
}

.contact-field input:hover,
.contact-field select:hover,
.contact-field textarea:hover {
border-color: rgba(214, 166, 59, 0.32);
background: var(--color-white);
}

.contact-field input:focus,
.contact-field select:focus,
.contact-field textarea:focus {
border-color: var(--color-gold);
background: var(--color-white);
box-shadow:
0 0 0 4px rgba(214, 166, 59, 0.10),
0 8px 20px rgba(23, 28, 45, 0.045);
}

.contact-field input:focus-visible,
.contact-field select:focus-visible,
.contact-field textarea:focus-visible {
outline: none;
}

.contact-field small {
display: block;
margin-top: 7px;
color: var(--color-muted);
font-size: 0.67rem;
line-height: 1.55;
}

/* Rating */

.contact-rating-input {
display: inline-flex;
align-items: center;
gap: 4px;
min-height: 48px;
padding: 5px 7px;
border: 1px solid var(--color-border);
border-radius: 13px;
background: rgba(255, 255, 255, 0.75);
}

.contact-rating-input button {
display: grid;
width: 39px;
height: 39px;
place-items: center;
border: 0;
border-radius: 9px;
background: transparent;
color: #c7c0b5;
cursor: pointer;
font-size: 1.35rem;
line-height: 1;
transition:
color 160ms ease,
background 160ms ease,
transform 160ms ease;
}

.contact-rating-input button:hover {
background: rgba(214, 166, 59, 0.08);
color: var(--color-gold);
transform: translateY(-2px) scale(1.04);
}

.contact-rating-input button.active {
color: var(--color-gold);
}

.contact-rating-input button:focus-visible {
outline: 2px solid rgba(214, 166, 59, 0.4);
outline-offset: 1px;
}

/* Hidden honeypot */

.contact-honeypot {
position: absolute !important;
width: 1px !important;
height: 1px !important;
overflow: hidden !important;
clip: rect(0 0 0 0) !important;
clip-path: inset(50%) !important;
white-space: nowrap !important;
}

/* Feedback notice */

.contact-consent {
display: flex;
align-items: flex-start;
gap: 11px;
margin-top: 24px;
padding: 14px 16px;
border: 1px solid rgba(214, 166, 59, 0.18);
border-radius: 13px;
background: rgba(214, 166, 59, 0.055);
}

.contact-consent > span {
flex: 0 0 auto;
color: var(--color-gold-dark);
font-size: 0.75rem;
}

.contact-consent p {
margin: 0;
color: var(--color-muted);
font-size: 0.68rem;
line-height: 1.6;
}

/* Status */

.contact-form-status {
margin-top: 20px;
padding: 13px 15px;
border: 1px solid var(--color-border);
border-radius: 13px;
font-size: 0.76rem;
font-weight: 650;
line-height: 1.55;
animation: contact-status-enter 280ms ease both;
}

.contact-form-status.success {
border-color: rgba(79, 138, 102, 0.25);
background: rgba(79, 138, 102, 0.07);
color: #356747;
}

.contact-form-status.error {
border-color: rgba(184, 93, 82, 0.25);
background: rgba(184, 93, 82, 0.07);
color: #8d463d;
}

/* Submit */

.contact-submit {
display: flex;
align-items: center;
gap: 17px;
margin-top: 27px;
}

.contact-submit button {
position: relative;
min-height: 48px;
padding: 0 22px;
overflow: hidden;
border: 1px solid var(--color-midnight);
border-radius: 12px;
background: var(--color-midnight);
color: var(--color-white);
cursor: pointer;
font: inherit;
font-size: 0.76rem;
font-weight: 800;
transition:
transform 180ms ease,
box-shadow 180ms ease,
background 180ms ease;
}

.contact-submit button::after {
position: absolute;
inset: 0;
background: linear-gradient(
110deg,
transparent 25%,
rgba(255, 255, 255, 0.14) 50%,
transparent 75%
);
content: "";
transform: translateX(-120%);
transition: transform 550ms ease;
}

.contact-submit button:hover {
background: #102b45;
box-shadow: 0 12px 26px rgba(7, 24, 42, 0.18);
transform: translateY(-2px);
}

.contact-submit button:hover::after {
transform: translateX(120%);
}

.contact-submit button:active {
transform: translateY(0);
}

.contact-submit button:disabled {
cursor: not-allowed;
opacity: 0.58;
transform: none;
}

.contact-submit span {
color: var(--color-muted);
font-size: 0.68rem;
line-height: 1.5;
}

/* Bottom information */

.contact-direct-grid {
display: grid;
grid-template-columns: repeat(2, minmax(0, 1fr));
gap: 16px;
margin-top: 18px;
}

.contact-direct-grid > div {
padding: 20px 21px;
border: 1px solid var(--color-border);
border-radius: 17px;
background: rgba(255, 255, 255, 0.60);
transition:
transform 220ms ease,
border-color 220ms ease,
box-shadow 220ms ease;
}

.contact-direct-grid > div:hover {
border-color: rgba(214, 166, 59, 0.25);
box-shadow: 0 14px 30px rgba(23, 28, 45, 0.055);
transform: translateY(-3px);
}

.contact-direct-grid span {
display: block;
margin-bottom: 7px;
color: var(--color-gold-dark);
font-size: 0.62rem;
font-weight: 850;
letter-spacing: 0.13em;
}

.contact-direct-grid strong {
display: block;
color: var(--color-midnight);
font-family: var(--font-heading), Georgia, serif;
font-size: 1.05rem;
font-weight: 600;
}

.contact-direct-grid p {
margin: 7px 0 0;
color: var(--color-muted);
font-size: 0.71rem;
line-height: 1.65;
}

@keyframes contact-card-enter {
from {
opacity: 0;
transform: translateY(16px);
}

to {
opacity: 1;
transform: translateY(0);
}
}

@keyframes contact-status-enter {
from {
opacity: 0;
transform: translateY(5px);
}

to {
opacity: 1;
transform: translateY(0);
}
}

@media (max-width: 900px) {
.contact-section {
width: min(100% - 30px, 760px);
padding: 58px 0 76px;
}

.contact-intro-grid {
grid-template-columns: 1fr;
gap: 24px;
}

.contact-trust-card {
max-width: 650px;
}

.contact-form-grid {
gap: 18px 15px;
}
}

@media (max-width: 640px) {
.contact-section {
width: min(100% - 22px, 560px);
padding: 42px 0 58px;
}

.contact-intro h2 {
font-size: 2.15rem;
}

.contact-intro p {
font-size: 0.82rem;
}

.contact-mode-switch {
margin-bottom: 20px;
}

.contact-mode-switch button {
min-height: 48px;
font-size: 0.70rem;
}

.contact-form-card {
padding: 24px 17px;
border-radius: 19px;
}

.contact-form-heading {
margin-bottom: 24px;
}

.contact-form-heading h2 {
font-size: 1.65rem;
}

.contact-form-heading p {
font-size: 0.75rem;
}

.contact-form-grid {
grid-template-columns: 1fr;
gap: 17px;
}

.contact-field-full {
grid-column: auto;
}

.contact-field textarea {
min-height: 145px;
}

.contact-rating-input {
width: 100%;
justify-content: space-between;
}

.contact-rating-input button {
width: 42px;
}

.contact-submit {
align-items: stretch;
flex-direction: column;
gap: 10px;
}

.contact-submit button {
width: 100%;
}

.contact-submit span {
text-align: center;
}

.contact-direct-grid {
grid-template-columns: 1fr;
}
}

@media (max-width: 390px) {
.contact-mode-switch button {
gap: 5px;
padding: 0 7px;
font-size: 0.65rem;
}

.contact-rating-input button {
width: 37px;
font-size: 1.2rem;
}
}

@media (prefers-reduced-motion: reduce) {
.contact-form-card,
.contact-form-status {
animation: none;
}

.contact-mode-switch button,
.contact-field input,
.contact-field select,
.contact-field textarea,
.contact-rating-input button,
.contact-submit button,
.contact-direct-grid > div {
transition: none;
}
}
/* =========================================================
ADMIN — CONTACT QUERIES
Premium light / gold administration interface
========================================================= */

.queries-page {
width: 100%;
max-width: 1500px;
margin: 0 auto;
animation: queriesPageEnter 420ms ease both;
}

.queries-header {
display: flex;
align-items: flex-end;
justify-content: space-between;
gap: 28px;
margin-bottom: 26px;
}

.queries-heading {
margin: 0;
color: var(--color-midnight);
font-family: var(--font-heading), Georgia, serif;
font-size: clamp(30px, 3vw, 42px);
font-weight: 600;
line-height: 1.04;
letter-spacing: -0.035em;
}

.queries-description {
max-width: 720px;
margin: 9px 0 0;
color: var(--color-muted);
font-size: 14px;
line-height: 1.65;
}

.queries-refresh {
display: inline-flex;
align-items: center;
justify-content: center;
min-width: 118px;
min-height: 44px;
flex: 0 0 auto;
padding: 0 17px;
border: 1px solid rgba(214, 166, 59, 0.38);
border-radius: 12px;
background: linear-gradient(
180deg,
rgba(255, 255, 255, 0.96),
rgba(250, 247, 239, 0.96)
);
color: var(--color-midnight);
box-shadow: 0 5px 18px rgba(7, 24, 42, 0.07);
cursor: pointer;
font-size: 12px;
font-weight: 700;
letter-spacing: 0.01em;
transition:
transform 180ms ease,
box-shadow 180ms ease,
border-color 180ms ease,
background 180ms ease;
}

.queries-refresh:hover:not(:disabled) {
border-color: rgba(214, 166, 59, 0.7);
background: #fff;
box-shadow: 0 9px 26px rgba(7, 24, 42, 0.11);
transform: translateY(-2px);
}

.queries-refresh:active:not(:disabled) {
transform: translateY(0);
}

.queries-refresh:disabled {
cursor: not-allowed;
opacity: 0.55;
}

/* ---------------------------------------------------------
TOOLBAR
--------------------------------------------------------- */

.queries-toolbar {
display: grid;
grid-template-columns: minmax(260px, 1fr) 175px 175px auto;
gap: 10px;
margin-bottom: 18px;
padding: 13px;
border: 1px solid var(--color-border);
border-radius: 16px;
background:
linear-gradient(
135deg,
rgba(255, 255, 255, 0.98),
rgba(250, 247, 239, 0.94)
);
box-shadow:
0 8px 28px rgba(7, 24, 42, 0.055),
inset 0 1px 0 rgba(255, 255, 255, 0.8);
}

.queries-search {
display: flex;
min-width: 0;
}

.queries-input,
.queries-select,
.queries-reply {
width: 100%;
border: 1px solid rgba(7, 24, 42, 0.13);
border-radius: 11px;
outline: none;
background: #fff;
color: var(--color-midnight);
box-shadow: inset 0 1px 2px rgba(7, 24, 42, 0.025);
font-family: inherit;
transition:
border-color 180ms ease,
box-shadow 180ms ease,
background 180ms ease,
transform 180ms ease;
}

.queries-input,
.queries-select {
height: 44px;
padding: 0 13px;
font-size: 13px;
}

.queries-input:hover,
.queries-select:hover {
border-color: rgba(214, 166, 59, 0.42);
}

.queries-input:focus,
.queries-select:focus,
.queries-reply:focus {
border-color: rgba(214, 166, 59, 0.78);
background: #fff;
box-shadow:
0 0 0 3px rgba(214, 166, 59, 0.11),
0 4px 14px rgba(7, 24, 42, 0.045);
}

.queries-input::placeholder,
.queries-reply::placeholder {
color: var(--color-muted);
opacity: 0.68;
}

.queries-search-button,
.queries-clear-button {
height: 44px;
padding: 0 16px;
border-radius: 11px;
cursor: pointer;
font-family: inherit;
font-size: 12px;
font-weight: 700;
transition:
transform 180ms ease,
box-shadow 180ms ease,
background 180ms ease,
border-color 180ms ease;
}

.queries-search-button {
border: 1px solid var(--color-gold-dark);
background: linear-gradient(
135deg,
var(--color-gold),
var(--color-gold-light)
);
color: var(--color-midnight);
box-shadow: 0 5px 15px rgba(173, 124, 29, 0.16);
}

.queries-search-button:hover {
border-color: var(--color-gold);
box-shadow: 0 8px 20px rgba(173, 124, 29, 0.22);
transform: translateY(-1px);
}

.queries-search-button:active,
.queries-clear-button:active {
transform: translateY(0);
}

.queries-clear-button {
border: 1px solid rgba(7, 24, 42, 0.12);
background: rgba(255, 255, 255, 0.7);
color: var(--color-midnight);
}

.queries-clear-button:hover {
border-color: rgba(214, 166, 59, 0.42);
background: #fff;
}

/* ---------------------------------------------------------
ERROR / SUMMARY
--------------------------------------------------------- */

.queries-error {
margin-bottom: 16px;
padding: 13px 15px;
border: 1px solid rgba(177, 54, 54, 0.2);
border-radius: 12px;
background: rgba(177, 54, 54, 0.055);
color: #9c3030;
font-size: 13px;
line-height: 1.55;
animation: queriesStatusEnter 250ms ease both;
}

.queries-summary {
display: flex;
align-items: center;
justify-content: space-between;
gap: 14px;
margin-bottom: 10px;
color: var(--color-muted);
font-size: 11px;
font-weight: 600;
letter-spacing: 0.02em;
}

/* ---------------------------------------------------------
TABLE
--------------------------------------------------------- */

.queries-table-wrap {
overflow: hidden;
border: 1px solid var(--color-border);
border-radius: 18px;
background: #fff;
box-shadow:
0 10px 32px rgba(7, 24, 42, 0.065),
0 2px 5px rgba(7, 24, 42, 0.025);
}

.queries-table {
width: 100%;
min-width: 920px;
border-collapse: separate;
border-spacing: 0;
}

.queries-table th {
padding: 13px 16px;
border-bottom: 1px solid var(--color-border);
background:
linear-gradient(
180deg,
rgba(250, 247, 239, 0.98),
rgba(244, 237, 221, 0.78)
);
color: var(--color-muted);
text-align: left;
font-size: 9px;
font-weight: 800;
letter-spacing: 0.13em;
text-transform: uppercase;
white-space: nowrap;
}

.queries-table td {
padding: 15px 16px;
border-bottom: 1px solid rgba(7, 24, 42, 0.065);
vertical-align: middle;
color: var(--color-midnight);
font-size: 13px;
}

.queries-table tbody tr {
position: relative;
cursor: pointer;
background: #fff;
transition:
background 180ms ease,
box-shadow 180ms ease;
}

.queries-table tbody tr:hover {
background: rgba(250, 247, 239, 0.72);
box-shadow: inset 3px 0 0 var(--color-gold);
}

.queries-table tbody tr:last-child td {
border-bottom: 0;
}

/* ---------------------------------------------------------
TABLE CONTENT
--------------------------------------------------------- */

.query-id {
display: inline-flex;
align-items: center;
min-height: 26px;
padding: 0 8px;
border: 1px solid rgba(214, 166, 59, 0.2);
border-radius: 7px;
background: rgba(214, 166, 59, 0.065);
color: var(--color-gold-dark);
font-size: 10px;
font-weight: 800;
letter-spacing: 0.045em;
white-space: nowrap;
}

.query-customer {
display: flex;
flex-direction: column;
gap: 3px;
min-width: 150px;
}

.query-customer strong {
overflow: hidden;
color: var(--color-midnight);
font-size: 13px;
font-weight: 700;
text-overflow: ellipsis;
white-space: nowrap;
}

.query-customer span {
overflow: hidden;
color: var(--color-muted);
font-size: 11px;
text-overflow: ellipsis;
white-space: nowrap;
}

.query-subject {
display: flex;
flex-direction: column;
gap: 4px;
max-width: 310px;
}

.query-subject strong {
overflow: hidden;
color: var(--color-midnight);
font-size: 13px;
font-weight: 650;
line-height: 1.4;
text-overflow: ellipsis;
white-space: nowrap;
}

.query-category {
color: var(--color-muted);
font-size: 10px;
font-weight: 600;
}

/* ---------------------------------------------------------
STATUS / PRIORITY BADGES
--------------------------------------------------------- */

.query-badge {
display: inline-flex;
align-items: center;
justify-content: center;
min-height: 27px;
padding: 0 10px;
border: 1px solid transparent;
border-radius: 999px;
font-size: 9px;
font-weight: 800;
letter-spacing: 0.055em;
line-height: 1;
text-transform: uppercase;
white-space: nowrap;
}

.admin-query-status-new {
border-color: rgba(57, 111, 171, 0.18);
background: rgba(57, 111, 171, 0.075);
color: #315f8e;
}

.admin-query-status-in_progress {
border-color: rgba(173, 124, 29, 0.2);
background: rgba(214, 166, 59, 0.105);
color: #946817;
}

.admin-query-status-resolved {
border-color: rgba(49, 126, 82, 0.18);
background: rgba(49, 126, 82, 0.075);
color: #286b45;
}

.admin-query-status-closed {
border-color: rgba(7, 24, 42, 0.12);
background: rgba(7, 24, 42, 0.055);
color: #59636d;
}

.admin-query-priority-normal {
border-color: rgba(7, 24, 42, 0.1);
background: rgba(7, 24, 42, 0.045);
color: #65707a;
}

.admin-query-priority-high {
border-color: rgba(173, 124, 29, 0.2);
background: rgba(214, 166, 59, 0.1);
color: #946817;
}

.admin-query-priority-urgent {
border-color: rgba(177, 54, 54, 0.18);
background: rgba(177, 54, 54, 0.07);
color: #a33333;
}

/* ---------------------------------------------------------
EMPTY / LOADING
--------------------------------------------------------- */

.queries-empty,
.queries-loading {
min-height: 250px;
padding: 70px 20px;
text-align: center;
}

.queries-empty-title {
margin: 0 0 7px;
color: var(--color-midnight);
font-family: var(--font-heading), Georgia, serif;
font-size: 19px;
font-weight: 600;
}

.queries-empty-text {
max-width: 440px;
margin: 0 auto;
color: var(--color-muted);
font-size: 13px;
line-height: 1.6;
}

.queries-loading {
color: var(--color-muted);
font-size: 13px;
}

/* ---------------------------------------------------------
PAGINATION
--------------------------------------------------------- */

.queries-pagination {
display: flex;
align-items: center;
justify-content: center;
gap: 6px;
margin-top: 18px;
}

.queries-page-button {
display: inline-flex;
align-items: center;
justify-content: center;
min-width: 36px;
height: 36px;
padding: 0 9px;
border: 1px solid rgba(7, 24, 42, 0.11);
border-radius: 9px;
background: #fff;
color: var(--color-midnight);
cursor: pointer;
font-size: 11px;
font-weight: 700;
transition:
background 160ms ease,
border-color 160ms ease,
transform 160ms ease,
box-shadow 160ms ease;
}

.queries-page-button:hover:not(:disabled) {
border-color: rgba(214, 166, 59, 0.5);
background: var(--color-ivory);
box-shadow: 0 4px 12px rgba(7, 24, 42, 0.06);
transform: translateY(-1px);
}

.queries-page-button-active {
border-color: var(--color-gold-dark);
background: linear-gradient(
135deg,
var(--color-gold),
var(--color-gold-light)
);
color: var(--color-midnight);
box-shadow: 0 4px 12px rgba(173, 124, 29, 0.15);
}

.queries-page-button:disabled {
cursor: not-allowed;
opacity: 0.38;
}

/* =========================================================
QUERY DETAIL DRAWER
========================================================= */

.query-overlay {
position: fixed;
inset: 0;
z-index: 1000;
display: flex;
justify-content: flex-end;
background: rgba(7, 24, 42, 0.42);
backdrop-filter: blur(7px);
animation: queryOverlayEnter 220ms ease both;
}

.query-panel {
display: flex;
width: min(720px, 100%);
height: 100%;
flex-direction: column;
overflow: hidden;
border-left: 1px solid rgba(214, 166, 59, 0.25);
background:
linear-gradient(
180deg,
#fff 0%,
#fffdf9 48%,
var(--color-ivory) 100%
);
box-shadow: -24px 0 70px rgba(7, 24, 42, 0.18);
animation: queryPanelEnter 300ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.query-panel-header {
display: flex;
align-items: flex-start;
justify-content: space-between;
gap: 18px;
padding: 23px 26px 21px;
border-bottom: 1px solid var(--color-border);
background:
linear-gradient(
135deg,
rgba(255, 255, 255, 0.99),
rgba(250, 247, 239, 0.95)
);
}

.query-panel-kicker {
margin: 0 0 7px;
color: var(--color-gold-dark);
font-size: 9px;
font-weight: 800;
letter-spacing: 0.15em;
text-transform: uppercase;
}

.query-panel-title {
margin: 0;
color: var(--color-midnight);
font-family: var(--font-heading), Georgia, serif;
font-size: 23px;
font-weight: 600;
line-height: 1.2;
}

.query-panel-close {
display: inline-flex;
width: 38px;
height: 38px;
flex: 0 0 auto;
align-items: center;
justify-content: center;
border: 1px solid rgba(7, 24, 42, 0.12);
border-radius: 10px;
background: #fff;
color: var(--color-midnight);
cursor: pointer;
font-size: 20px;
line-height: 1;
transition:
background 160ms ease,
border-color 160ms ease,
transform 160ms ease,
box-shadow 160ms ease;
}

.query-panel-close:hover {
border-color: rgba(214, 166, 59, 0.48);
background: var(--color-ivory);
box-shadow: 0 5px 15px rgba(7, 24, 42, 0.08);
transform: rotate(2deg);
}

.query-panel-body {
flex: 1;
overflow-y: auto;
padding: 23px 26px 34px;
scrollbar-width: thin;
scrollbar-color: rgba(173, 124, 29, 0.35) transparent;
}

/* ---------------------------------------------------------
QUERY META
--------------------------------------------------------- */

.query-meta-grid {
display: grid;
grid-template-columns: repeat(2, minmax(0, 1fr));
gap: 10px;
margin-bottom: 22px;
}

.query-meta-card {
min-width: 0;
padding: 14px;
border: 1px solid var(--color-border);
border-radius: 12px;
background: rgba(255, 255, 255, 0.82);
box-shadow: 0 3px 12px rgba(7, 24, 42, 0.035);
}

.query-meta-label {
display: block;
margin-bottom: 6px;
color: var(--color-muted);
font-size: 8px;
font-weight: 800;
letter-spacing: 0.12em;
text-transform: uppercase;
}

.query-meta-value {
display: block;
overflow-wrap: anywhere;
color: var(--color-midnight);
font-size: 12px;
font-weight: 600;
line-height: 1.5;
}

/* ---------------------------------------------------------
CONTROLS
--------------------------------------------------------- */

.query-controls {
display: grid;
grid-template-columns: 1fr 1fr;
gap: 11px;
margin-bottom: 24px;
}

.query-control {
display: flex;
flex-direction: column;
gap: 7px;
}

.query-control label {
color: var(--color-muted);
font-size: 9px;
font-weight: 800;
letter-spacing: 0.1em;
text-transform: uppercase;
}

/* ---------------------------------------------------------
MESSAGE SECTIONS
--------------------------------------------------------- */

.query-message-section {
margin-bottom: 25px;
}

.query-section-title {
display: flex;
align-items: center;
gap: 9px;
margin: 0 0 10px;
color: var(--color-midnight);
font-size: 10px;
font-weight: 800;
letter-spacing: 0.1em;
text-transform: uppercase;
}

.query-section-title::before {
width: 18px;
height: 1px;
flex: 0 0 auto;
background: var(--color-gold);
content: "";
}

.query-original-message {
padding: 16px;
border: 1px solid var(--color-border);
border-radius: 12px;
background: rgba(250, 247, 239, 0.72);
color: #273544;
font-size: 13px;
line-height: 1.75;
white-space: pre-wrap;
overflow-wrap: anywhere;
box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.7);
}

/* ---------------------------------------------------------
CONVERSATION THREAD
--------------------------------------------------------- */

.query-thread {
display: flex;
flex-direction: column;
gap: 11px;
margin-bottom: 23px;
}

.query-thread-message {
max-width: 88%;
padding: 14px 15px;
border: 1px solid rgba(7, 24, 42, 0.09);
border-radius: 13px 13px 13px 4px;
background: #fff;
box-shadow: 0 4px 15px rgba(7, 24, 42, 0.045);
}

.query-thread-message-admin {
align-self: flex-end;
border-color: rgba(214, 166, 59, 0.27);
border-radius: 13px 13px 4px 13px;
background:
linear-gradient(
135deg,
rgba(214, 166, 59, 0.1),
rgba(255, 255, 255, 0.92)
);
}

.query-thread-top {
display: flex;
align-items: center;
justify-content: space-between;
gap: 12px;
margin-bottom: 8px;
}

.query-thread-sender {
color: var(--color-gold-dark);
font-size: 9px;
font-weight: 800;
letter-spacing: 0.09em;
text-transform: uppercase;
}

.query-thread-time {
color: var(--color-muted);
font-size: 9px;
white-space: nowrap;
}

.query-thread-text {
margin: 0;
color: #293847;
font-size: 12px;
line-height: 1.7;
white-space: pre-wrap;
overflow-wrap: anywhere;
}

/* ---------------------------------------------------------
REPLY BOX
--------------------------------------------------------- */

.query-reply-box {
padding-top: 19px;
border-top: 1px solid var(--color-border);
}

.queries-reply {
min-height: 128px;
resize: vertical;
padding: 13px 14px;
color: var(--color-midnight);
font: inherit;
font-size: 13px;
line-height: 1.65;
}

.query-reply-footer {
display: flex;
align-items: center;
justify-content: space-between;
gap: 12px;
margin-top: 10px;
}

.query-reply-counter {
color: var(--color-muted);
font-size: 9px;
font-weight: 600;
}

.query-reply-button {
display: inline-flex;
align-items: center;
justify-content: center;
min-height: 43px;
padding: 0 18px;
border: 1px solid var(--color-gold-dark);
border-radius: 10px;
background: linear-gradient(
135deg,
var(--color-gold),
var(--color-gold-light)
);
color: var(--color-midnight);
box-shadow: 0 6px 17px rgba(173, 124, 29, 0.16);
cursor: pointer;
font-size: 11px;
font-weight: 800;
transition:
transform 180ms ease,
box-shadow 180ms ease,
opacity 180ms ease;
}

.query-reply-button:hover:not(:disabled) {
box-shadow: 0 9px 22px rgba(173, 124, 29, 0.23);
transform: translateY(-1px);
}

.query-reply-button:active:not(:disabled) {
transform: translateY(0);
}

.query-reply-button:disabled {
cursor: not-allowed;
opacity: 0.48;
}

.query-reply-error,
.query-reply-success {
margin-top: 9px;
padding: 9px 11px;
border-radius: 8px;
font-size: 10px;
font-weight: 600;
line-height: 1.5;
}

.query-reply-error {
border: 1px solid rgba(177, 54, 54, 0.16);
background: rgba(177, 54, 54, 0.05);
color: #9c3030;
}

.query-reply-success {
border: 1px solid rgba(49, 126, 82, 0.16);
background: rgba(49, 126, 82, 0.05);
color: #286b45;
}

.query-detail-loading {
padding: 35px 0;
color: var(--color-muted);
text-align: center;
font-size: 12px;
}

/* =========================================================
ANIMATION
========================================================= */

@keyframes queriesPageEnter {
from {
opacity: 0;
transform: translateY(7px);
}

to {
opacity: 1;
transform: translateY(0);
}
}

@keyframes queriesStatusEnter {
from {
opacity: 0;
transform: translateY(-4px);
}

to {
opacity: 1;
transform: translateY(0);
}
}

@keyframes queryOverlayEnter {
from {
opacity: 0;
}

to {
opacity: 1;
}
}

@keyframes queryPanelEnter {
from {
opacity: 0;
transform: translateX(28px);
}

to {
opacity: 1;
transform: translateX(0);
}
}

/* =========================================================
RESPONSIVE
========================================================= */

@media (max-width: 1100px) {
.queries-toolbar {
grid-template-columns: minmax(220px, 1fr) 155px 155px auto;
}
}

@media (max-width: 900px) {
.queries-header {
align-items: stretch;
}

.queries-toolbar {
grid-template-columns: 1fr 1fr;
}

.queries-search {
grid-column: 1 / -1;
}

.queries-search-button,
.queries-clear-button {
width: 100%;
}

.query-panel {
width: min(680px, 100%);
}
}

@media (max-width: 640px) {
.queries-header {
flex-direction: column;
align-items: stretch;
gap: 16px;
}

.queries-heading {
font-size: 30px;
}

.queries-refresh {
width: 100%;
}

.queries-toolbar {
grid-template-columns: 1fr;
padding: 10px;
}

.queries-search {
grid-column: auto;
}

.queries-table-wrap {
border-radius: 14px;
}

.queries-table {
min-width: 860px;
}

.query-overlay {
align-items: flex-end;
}

.query-panel {
width: 100%;
max-height: 94vh;
height: 94vh;
border-top: 1px solid rgba(214, 166, 59, 0.25);
border-left: 0;
border-radius: 18px 18px 0 0;
animation-name: queryPanelMobileEnter;
}

.query-panel-header {
padding: 19px 17px 17px;
}

.query-panel-body {
padding: 19px 17px 28px;
}

.query-meta-grid,
.query-controls {
grid-template-columns: 1fr;
}

.query-thread-message {
max-width: 94%;
}

.query-reply-footer {
align-items: stretch;
flex-direction: column;
}

.query-reply-button {
width: 100%;
}
}

@media (max-width: 390px) {
.queries-heading {
font-size: 27px;
}

.queries-description {
font-size: 12px;
}

.query-panel-title {
font-size: 20px;
}

.query-meta-grid {
gap: 8px;
}
}

@keyframes queryPanelMobileEnter {
from {
opacity: 0;
transform: translateY(25px);
}

to {
opacity: 1;
transform: translateY(0);
}
}

@media (prefers-reduced-motion: reduce) {
.queries-page,
.queries-refresh,
.queries-table tbody tr,
.query-overlay,
.query-panel,
.query-panel-close,
.queries-page-button,
.query-reply-button {
animation: none !important;
transition: none !important;
}
}
/* =========================================================
   ADMIN — CUSTOMER FEEDBACK
   Premium light / ivory / navy / gold moderation interface
   ========================================================= */

.admin-feedback-page {
  width: 100%;
  max-width: 1500px;
  margin: 0 auto;
  animation: feedbackPageEnter 420ms ease both;
}

/* ---------- Header ---------- */

.admin-feedback-page .admin-page-header,
.feedback-page-header {
  margin-bottom: 26px;
}

.feedback-page-title {
  color: var(--color-midnight, #07182a);
  font-family: inherit;
}

.feedback-page-description {
  color: var(--color-muted, #6c747b);
}

/* ---------- Toolbar ---------- */

.feedback-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 20px;
}

.feedback-filters {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.feedback-filter-button {
  appearance: none;
  border: 1px solid var(--color-border, #e4dac6);
  background: rgba(255, 255, 255, 0.86);
  color: var(--color-muted, #6c747b);
  min-height: 40px;
  padding: 0 15px;
  border-radius: 999px;
  font: inherit;
  font-size: 0.78rem;
  font-weight: 750;
  letter-spacing: 0.02em;
  cursor: pointer;
  transition:
    color 180ms ease,
    background 180ms ease,
    border-color 180ms ease,
    transform 180ms ease,
    box-shadow 180ms ease;
}

.feedback-filter-button:hover {
  color: var(--color-midnight, #07182a);
  border-color: rgba(214, 166, 59, 0.5);
  transform: translateY(-1px);
}

.feedback-filter-button.active {
  color: #fff;
  background: var(--color-midnight, #07182a);
  border-color: var(--color-midnight, #07182a);
  box-shadow: 0 8px 20px rgba(7, 24, 42, 0.12);
}

.feedback-search {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: min(100%, 340px);
}

.feedback-search .admin-search-input {
  flex: 1;
}

/* ---------- Main table/card ---------- */

.feedback-table-card {
  overflow: hidden;
  background: rgba(255, 255, 255, 0.94);
  border: 1px solid var(--color-border, #e4dac6);
  border-radius: 20px;
  box-shadow:
    0 16px 45px rgba(7, 24, 42, 0.07),
    0 2px 8px rgba(7, 24, 42, 0.035);
}

.feedback-table-wrapper {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.feedback-table {
  width: 100%;
  min-width: 900px;
  border-collapse: collapse;
}

.feedback-table th {
  padding: 14px 18px;
  text-align: left;
  color: #7a766e;
  background: #faf7ef;
  border-bottom: 1px solid var(--color-border, #e4dac6);
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  white-space: nowrap;
}

.feedback-table td {
  padding: 17px 18px;
  color: var(--color-midnight, #07182a);
  border-bottom: 1px solid rgba(228, 218, 198, 0.72);
  vertical-align: middle;
  font-size: 0.82rem;
}

.feedback-table tbody tr {
  transition:
    background 180ms ease,
    transform 180ms ease;
}

.feedback-table tbody tr:hover {
  background: rgba(250, 247, 239, 0.72);
}

.feedback-table tbody tr:last-child td {
  border-bottom: 0;
}

/* ---------- Customer ---------- */

.feedback-customer {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 180px;
}

.feedback-customer-avatar {
  width: 36px;
  height: 36px;
  flex: 0 0 36px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: var(--color-midnight, #07182a);
  background:
    linear-gradient(
      145deg,
      rgba(231, 195, 108, 0.42),
      rgba(214, 166, 59, 0.14)
    );
  border: 1px solid rgba(214, 166, 59, 0.35);
  font-size: 0.76rem;
  font-weight: 850;
}

.feedback-customer-name {
  display: block;
  color: var(--color-midnight, #07182a);
  font-weight: 750;
  line-height: 1.25;
}

.feedback-customer-email {
  display: block;
  margin-top: 3px;
  color: #7b7f82;
  font-size: 0.7rem;
  line-height: 1.3;
}

/* ---------- Rating ---------- */

.feedback-rating {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  white-space: nowrap;
}

.feedback-rating-star {
  color: var(--color-gold, #d6a63b);
  font-size: 0.9rem;
}

.feedback-rating-number {
  margin-left: 6px;
  color: var(--color-midnight, #07182a);
  font-size: 0.75rem;
  font-weight: 800;
}

/* ---------- Message preview ---------- */

.feedback-message-preview {
  display: block;
  max-width: 330px;
  overflow: hidden;
  color: #626a70;
  line-height: 1.55;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ---------- Service / verified ---------- */

.feedback-service {
  color: var(--color-midnight, #07182a);
  font-weight: 650;
}

.feedback-verified {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin-top: 5px;
  color: #8a6519;
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

/* ---------- Status ---------- */

.feedback-status {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 0 10px;
  border-radius: 999px;
  font-size: 0.65rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  white-space: nowrap;
}

.feedback-status-pending {
  color: #85631a;
  background: rgba(214, 166, 59, 0.13);
  border: 1px solid rgba(214, 166, 59, 0.25);
}

.feedback-status-approved {
  color: #286347;
  background: rgba(65, 145, 101, 0.1);
  border: 1px solid rgba(65, 145, 101, 0.2);
}

.feedback-status-rejected {
  color: #8b3d3d;
  background: rgba(180, 77, 77, 0.08);
  border: 1px solid rgba(180, 77, 77, 0.18);
}

/* ---------- Row action ---------- */

.feedback-view-button {
  appearance: none;
  border: 1px solid var(--color-border, #e4dac6);
  background: #fff;
  color: var(--color-midnight, #07182a);
  min-height: 34px;
  padding: 0 12px;
  border-radius: 9px;
  font: inherit;
  font-size: 0.7rem;
  font-weight: 800;
  cursor: pointer;
  transition:
    background 180ms ease,
    color 180ms ease,
    border-color 180ms ease,
    transform 180ms ease;
}

.feedback-view-button:hover {
  color: #fff;
  background: var(--color-midnight, #07182a);
  border-color: var(--color-midnight, #07182a);
  transform: translateY(-1px);
}

/* ---------- Empty / loading ---------- */

.feedback-empty {
  padding: 72px 24px;
  text-align: center;
}

.feedback-empty-title {
  margin: 0;
  color: var(--color-midnight, #07182a);
  font-size: 1.1rem;
  font-weight: 800;
}

.feedback-empty-text {
  max-width: 420px;
  margin: 8px auto 0;
  color: #7a7f83;
  font-size: 0.82rem;
  line-height: 1.65;
}

.feedback-loading {
  padding: 60px 20px;
  text-align: center;
  color: #777d82;
  font-size: 0.8rem;
}

/* ---------- Pagination ---------- */

.feedback-pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 18px;
  border-top: 1px solid var(--color-border, #e4dac6);
  background: #fffdf8;
}

.feedback-pagination-info {
  color: #7b8084;
  font-size: 0.72rem;
}

.feedback-pagination-controls {
  display: flex;
  align-items: center;
  gap: 6px;
}

.feedback-page-button {
  appearance: none;
  min-width: 34px;
  height: 34px;
  padding: 0 9px;
  border: 1px solid var(--color-border, #e4dac6);
  border-radius: 8px;
  background: #fff;
  color: var(--color-midnight, #07182a);
  font: inherit;
  font-size: 0.7rem;
  font-weight: 800;
  cursor: pointer;
  transition: all 180ms ease;
}

.feedback-page-button:hover:not(:disabled) {
  border-color: var(--color-gold, #d6a63b);
  transform: translateY(-1px);
}

.feedback-page-button.active {
  color: #fff;
  background: var(--color-midnight, #07182a);
  border-color: var(--color-midnight, #07182a);
}

.feedback-page-button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* =========================================================
   FEEDBACK REVIEW DRAWER / MODAL
   ========================================================= */

.feedback-overlay {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: flex;
  justify-content: flex-end;
  background: rgba(7, 24, 42, 0.42);
  backdrop-filter: blur(7px);
  -webkit-backdrop-filter: blur(7px);
  animation: feedbackOverlayEnter 220ms ease both;
}

.feedback-modal,
.feedback-panel {
  width: min(620px, 100%);
  height: 100%;
  overflow-y: auto;
  background:
    linear-gradient(
      180deg,
      #fffdf9 0%,
      #faf7ef 100%
    );
  border-left: 1px solid rgba(214, 166, 59, 0.24);
  box-shadow: -22px 0 65px rgba(7, 24, 42, 0.16);
  animation: feedbackDrawerEnter 360ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.feedback-modal-header,
.feedback-panel-header {
  position: sticky;
  top: 0;
  z-index: 2;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  padding: 25px 28px 20px;
  background: rgba(255, 253, 249, 0.94);
  border-bottom: 1px solid var(--color-border, #e4dac6);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

.feedback-modal-kicker {
  display: block;
  margin-bottom: 7px;
  color: var(--color-gold-dark, #ad7c1d);
  font-size: 0.63rem;
  font-weight: 850;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.feedback-modal-title {
  margin: 0;
  color: var(--color-midnight, #07182a);
  font-size: 1.35rem;
  line-height: 1.2;
  font-weight: 850;
}

.feedback-modal-close {
  appearance: none;
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: grid;
  place-items: center;
  border: 1px solid var(--color-border, #e4dac6);
  border-radius: 10px;
  background: #fff;
  color: var(--color-midnight, #07182a);
  font-size: 1.1rem;
  cursor: pointer;
  transition: all 180ms ease;
}

.feedback-modal-close:hover {
  color: #fff;
  background: var(--color-midnight, #07182a);
  border-color: var(--color-midnight, #07182a);
  transform: rotate(3deg);
}

.feedback-modal-body,
.feedback-panel-body {
  display: flex;
  flex-direction: column;
  gap: 22px;
  padding: 26px 28px 34px;
}

/* ---------- Detail identity ---------- */

.feedback-detail-identity {
  padding: 20px;
  border-radius: 16px;
  background: #fff;
  border: 1px solid var(--color-border, #e4dac6);
  box-shadow: 0 8px 24px rgba(7, 24, 42, 0.045);
}

.feedback-detail-name {
  margin: 0;
  color: var(--color-midnight, #07182a);
  font-size: 1.05rem;
  font-weight: 850;
}

.feedback-detail-email {
  margin: 4px 0 0;
  color: #747b80;
  font-size: 0.75rem;
}

.feedback-detail-id {
  display: inline-block;
  margin-top: 12px;
  color: var(--color-gold-dark, #ad7c1d);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.67rem;
  font-weight: 700;
}

/* ---------- Meta cards ---------- */

.feedback-meta-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.feedback-meta-card {
  min-width: 0;
  padding: 15px 16px;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.84);
  border: 1px solid var(--color-border, #e4dac6);
}

.feedback-meta-label {
  display: block;
  margin-bottom: 6px;
  color: #7b807f;
  font-size: 0.62rem;
  font-weight: 850;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.feedback-meta-value {
  display: block;
  color: var(--color-midnight, #07182a);
  font-size: 0.78rem;
  font-weight: 700;
  overflow-wrap: anywhere;
}

/* ---------- Full feedback ---------- */

.feedback-message-card {
  padding: 20px;
  border-radius: 16px;
  background: #fff;
  border: 1px solid var(--color-border, #e4dac6);
}

.feedback-message-card-label {
  display: block;
  margin-bottom: 10px;
  color: var(--color-gold-dark, #ad7c1d);
  font-size: 0.64rem;
  font-weight: 850;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.feedback-message {
  margin: 0;
  color: #39434b;
  font-size: 0.88rem;
  line-height: 1.8;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

/* ---------- Moderation note ---------- */

.feedback-admin-note-label {
  display: block;
  margin-bottom: 8px;
  color: var(--color-midnight, #07182a);
  font-size: 0.76rem;
  font-weight: 800;
}

.feedback-admin-note {
  width: 100%;
  min-height: 110px;
  resize: vertical;
  padding: 12px 14px;
}

/* ---------- Modal actions ---------- */

.feedback-modal-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 9px;
  padding-top: 4px;
}

.feedback-modal-actions button {
  min-height: 40px;
}

/* ---------- Error ---------- */

.feedback-modal-error,
.feedback-action-error {
  padding: 11px 13px;
  border-radius: 10px;
  color: #8b3d3d;
  background: rgba(180, 77, 77, 0.07);
  border: 1px solid rgba(180, 77, 77, 0.17);
  font-size: 0.74rem;
  line-height: 1.5;
  animation: feedbackStatusEnter 220ms ease both;
}

/* ---------- Scrollbar ---------- */

.feedback-modal::-webkit-scrollbar,
.feedback-panel::-webkit-scrollbar {
  width: 7px;
}

.feedback-modal::-webkit-scrollbar-thumb,
.feedback-panel::-webkit-scrollbar-thumb {
  background: rgba(122, 118, 110, 0.28);
  border-radius: 999px;
}

.feedback-modal::-webkit-scrollbar-track,
.feedback-panel::-webkit-scrollbar-track {
  background: transparent;
}

/* =========================================================
   ANIMATIONS
   ========================================================= */

@keyframes feedbackPageEnter {
  from {
    opacity: 0;
    transform: translateY(8px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes feedbackOverlayEnter {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

@keyframes feedbackDrawerEnter {
  from {
    opacity: 0;
    transform: translateX(35px);
  }

  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes feedbackStatusEnter {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 900px) {
  .feedback-toolbar {
    align-items: stretch;
  }

  .feedback-filters {
    width: 100%;
  }

  .feedback-search {
    width: 100%;
  }

  .feedback-table-card {
    border-radius: 16px;
  }

  .feedback-modal,
  .feedback-panel {
    width: min(560px, 100%);
  }
}

@media (max-width: 640px) {
  .admin-feedback-page {
    max-width: none;
  }

  .feedback-toolbar {
    gap: 11px;
  }

  .feedback-filter-button {
    min-height: 38px;
    padding-inline: 12px;
    font-size: 0.7rem;
  }

  .feedback-pagination {
    align-items: flex-start;
    flex-direction: column;
  }

  .feedback-pagination-controls {
    width: 100%;
    justify-content: space-between;
  }

  .feedback-overlay {
    align-items: flex-end;
  }

  .feedback-modal,
  .feedback-panel {
    width: 100%;
    height: min(92dvh, 850px);
    max-height: 92dvh;
    border-left: 0;
    border-top: 1px solid rgba(214, 166, 59, 0.25);
    border-radius: 22px 22px 0 0;
    animation: feedbackSheetEnter 360ms cubic-bezier(0.22, 1, 0.36, 1) both;
  }

  .feedback-modal-header,
  .feedback-panel-header {
    padding: 20px 20px 17px;
  }

  .feedback-modal-body,
  .feedback-panel-body {
    padding: 21px 20px 28px;
  }

  .feedback-meta-grid {
    grid-template-columns: 1fr;
  }

  .feedback-modal-title {
    font-size: 1.18rem;
  }
}

@media (max-width: 420px) {
  .feedback-filters {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .feedback-filter-button {
    width: 100%;
  }

  .feedback-search {
    min-width: 0;
  }

  .feedback-modal-actions {
    display: grid;
    grid-template-columns: 1fr;
  }

  .feedback-modal-actions button {
    width: 100%;
  }
}

@keyframes feedbackSheetEnter {
  from {
    opacity: 0;
    transform: translateY(45px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .admin-feedback-page,
  .feedback-overlay,
  .feedback-modal,
  .feedback-panel,
  .feedback-status-enter {
    animation: none !important;
  }

  .feedback-filter-button,
  .feedback-view-button,
  .feedback-page-button,
  .feedback-modal-close {
    transition: none !important;
  }
}
/* =========================================================
   ADMIN QUERIES — PREMIUM LIGHT ADMIN UI
   ========================================================= */

.admin-queries-page {
  width: 100%;
  animation: adminQueriesPageEnter 0.45s ease both;
}

.admin-queries-header {
  margin-bottom: 24px;
}

.admin-queries-title {
  margin: 0;
  color: var(--color-midnight);
  font-size: clamp(1.65rem, 2.4vw, 2.15rem);
  font-weight: 800;
  letter-spacing: -0.035em;
  line-height: 1.15;
}

.admin-queries-description {
  max-width: 720px;
  margin: 8px 0 0;
  color: var(--color-muted);
  font-size: 0.94rem;
  line-height: 1.65;
}

/* ---------------------------------------------------------
   TOOLBAR
   --------------------------------------------------------- */

.queries-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 18px;
}

.queries-filters {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.queries-filter-button {
  min-height: 38px;
  padding: 0 14px;
  border: 1px solid var(--color-border);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.78);
  color: var(--color-charcoal);
  font-size: 0.82rem;
  font-weight: 700;
  cursor: pointer;
  transition:
    background 0.2s ease,
    border-color 0.2s ease,
    color 0.2s ease,
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.queries-filter-button:hover {
  border-color: rgba(214, 166, 59, 0.45);
  background: var(--color-ivory);
  transform: translateY(-1px);
}

.queries-filter-button.active {
  border-color: var(--color-gold);
  background: rgba(214, 166, 59, 0.12);
  color: var(--color-midnight);
  box-shadow: 0 5px 16px rgba(214, 166, 59, 0.1);
}

.queries-search {
  width: min(100%, 320px);
  min-height: 42px;
  padding: 0 14px;
  border: 1px solid var(--color-border);
  border-radius: 11px;
  outline: none;
  background: #fff;
  color: var(--color-midnight);
  font-size: 0.87rem;
  transition:
    border-color 0.2s ease,
    box-shadow 0.2s ease;
}

.queries-search::placeholder {
  color: var(--color-muted);
}

.queries-search:focus {
  border-color: rgba(214, 166, 59, 0.72);
  box-shadow: 0 0 0 4px rgba(214, 166, 59, 0.1);
}

/* ---------------------------------------------------------
   TABLE
   --------------------------------------------------------- */

.queries-table-card {
  overflow: hidden;
  border: 1px solid rgba(13, 34, 56, 0.09);
  border-radius: 18px;
  background: #fff;
  box-shadow:
    0 14px 42px rgba(7, 24, 42, 0.07),
    0 2px 8px rgba(7, 24, 42, 0.025);
}

.queries-table-wrapper {
  width: 100%;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.queries-table {
  width: 100%;
  min-width: 920px;
  border-collapse: collapse;
}

.queries-table thead {
  background: rgba(250, 247, 239, 0.72);
}

.queries-table th {
  padding: 14px 17px;
  border-bottom: 1px solid var(--color-border);
  color: var(--color-muted);
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.075em;
  line-height: 1.2;
  text-align: left;
  text-transform: uppercase;
  white-space: nowrap;
}

.queries-table td {
  padding: 16px 17px;
  border-bottom: 1px solid rgba(13, 34, 56, 0.065);
  color: var(--color-charcoal);
  font-size: 0.83rem;
  vertical-align: middle;
}

.queries-table tbody tr {
  transition:
    background 0.2s ease,
    box-shadow 0.2s ease;
}

.queries-table tbody tr:hover {
  background: rgba(250, 247, 239, 0.48);
}

.queries-table tbody tr:last-child td {
  border-bottom: 0;
}

/* ---------------------------------------------------------
   CUSTOMER
   --------------------------------------------------------- */

.query-customer {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 175px;
}

.query-customer-avatar {
  display: grid;
  flex: 0 0 36px;
  width: 36px;
  height: 36px;
  place-items: center;
  border: 1px solid rgba(214, 166, 59, 0.3);
  border-radius: 50%;
  background: linear-gradient(
    145deg,
    rgba(214, 166, 59, 0.17),
    rgba(231, 195, 108, 0.08)
  );
  color: var(--color-midnight);
  font-size: 0.78rem;
  font-weight: 800;
}

.query-customer-info {
  min-width: 0;
}

.query-customer-name {
  overflow: hidden;
  color: var(--color-midnight);
  font-weight: 750;
  line-height: 1.35;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.query-customer-email {
  overflow: hidden;
  max-width: 210px;
  margin-top: 2px;
  color: var(--color-muted);
  font-size: 0.74rem;
  line-height: 1.4;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ---------------------------------------------------------
   SUBJECT / MESSAGE
   --------------------------------------------------------- */

.query-subject {
  display: block;
  max-width: 230px;
  overflow: hidden;
  color: var(--color-midnight);
  font-weight: 750;
  line-height: 1.4;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.query-message-preview {
  display: -webkit-box;
  max-width: 280px;
  overflow: hidden;
  color: var(--color-muted);
  font-size: 0.76rem;
  line-height: 1.55;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

/* ---------------------------------------------------------
   CATEGORY
   --------------------------------------------------------- */

.query-category {
  display: inline-flex;
  align-items: center;
  min-height: 27px;
  padding: 4px 9px;
  border: 1px solid rgba(13, 34, 56, 0.1);
  border-radius: 8px;
  background: rgba(13, 34, 56, 0.035);
  color: var(--color-navy);
  font-size: 0.7rem;
  font-weight: 750;
  white-space: nowrap;
}

/* ---------------------------------------------------------
   STATUS / PRIORITY
   --------------------------------------------------------- */

.query-status-badge,
.query-priority-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 27px;
  padding: 4px 9px;
  border-radius: 999px;
  font-size: 0.69rem;
  font-weight: 800;
  line-height: 1;
  white-space: nowrap;
}

.query-status-badge.status-new {
  border: 1px solid rgba(37, 99, 235, 0.18);
  background: rgba(37, 99, 235, 0.08);
  color: #1d4ed8;
}

.query-status-badge.status-in_progress {
  border: 1px solid rgba(214, 166, 59, 0.22);
  background: rgba(214, 166, 59, 0.1);
  color: #8a6514;
}

.query-status-badge.status-resolved {
  border: 1px solid rgba(22, 101, 52, 0.17);
  background: rgba(22, 101, 52, 0.08);
  color: #166534;
}

.query-status-badge.status-closed {
  border: 1px solid rgba(100, 116, 139, 0.2);
  background: rgba(100, 116, 139, 0.08);
  color: #475569;
}

.query-priority-badge.priority-normal {
  border: 1px solid rgba(100, 116, 139, 0.18);
  background: rgba(100, 116, 139, 0.07);
  color: #475569;
}

.query-priority-badge.priority-high {
  border: 1px solid rgba(180, 83, 9, 0.18);
  background: rgba(180, 83, 9, 0.08);
  color: #9a3412;
}

.query-priority-badge.priority-urgent {
  border: 1px solid rgba(185, 28, 28, 0.18);
  background: rgba(185, 28, 28, 0.08);
  color: #b91c1c;
}

/* ---------------------------------------------------------
   VIEW BUTTON
   --------------------------------------------------------- */

.query-view-button {
  min-height: 34px;
  padding: 0 12px;
  border: 1px solid rgba(13, 34, 56, 0.12);
  border-radius: 9px;
  background: #fff;
  color: var(--color-navy);
  font-size: 0.74rem;
  font-weight: 800;
  cursor: pointer;
  transition:
    background 0.2s ease,
    border-color 0.2s ease,
    color 0.2s ease,
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.query-view-button:hover {
  border-color: rgba(214, 166, 59, 0.45);
  background: var(--color-ivory);
  color: var(--color-midnight);
  transform: translateY(-1px);
  box-shadow: 0 5px 14px rgba(7, 24, 42, 0.07);
}

/* ---------------------------------------------------------
   EMPTY / LOADING
   --------------------------------------------------------- */

.queries-empty-state,
.queries-loading-state {
  display: flex;
  min-height: 250px;
  align-items: center;
  justify-content: center;
  padding: 32px;
  color: var(--color-muted);
  font-size: 0.86rem;
  text-align: center;
}

.queries-loading-state {
  animation: queriesPulse 1.4s ease-in-out infinite;
}

/* ---------------------------------------------------------
   PAGINATION
   --------------------------------------------------------- */

.queries-pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 14px 17px;
  border-top: 1px solid rgba(13, 34, 56, 0.065);
}

.queries-pagination-info {
  color: var(--color-muted);
  font-size: 0.76rem;
}

.queries-pagination-actions {
  display: flex;
  align-items: center;
  gap: 7px;
}

.queries-pagination-button {
  min-width: 34px;
  height: 34px;
  padding: 0 9px;
  border: 1px solid var(--color-border);
  border-radius: 8px;
  background: #fff;
  color: var(--color-navy);
  font-size: 0.75rem;
  font-weight: 750;
  cursor: pointer;
  transition:
    background 0.2s ease,
    border-color 0.2s ease,
    opacity 0.2s ease;
}

.queries-pagination-button:hover:not(:disabled) {
  border-color: rgba(214, 166, 59, 0.4);
  background: var(--color-ivory);
}

.queries-pagination-button:disabled {
  cursor: not-allowed;
  opacity: 0.42;
}

/* ---------------------------------------------------------
   DETAIL / REPLY DRAWER
   --------------------------------------------------------- */

.queries-overlay {
  position: fixed;
  z-index: 1000;
  inset: 0;
  display: flex;
  justify-content: flex-end;
  background: rgba(7, 24, 42, 0.42);
  backdrop-filter: blur(5px);
  -webkit-backdrop-filter: blur(5px);
  animation: queriesOverlayEnter 0.22s ease both;
}

.queries-drawer {
  display: flex;
  width: min(100%, 590px);
  height: 100%;
  flex-direction: column;
  overflow: hidden;
  background: var(--color-ivory);
  border-left: 1px solid rgba(13, 34, 56, 0.1);
  box-shadow: -18px 0 55px rgba(7, 24, 42, 0.16);
  animation: queriesDrawerEnter 0.32s cubic-bezier(0.22, 1, 0.36, 1) both;
}

.queries-drawer-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 22px 24px;
  border-bottom: 1px solid rgba(13, 34, 56, 0.09);
  background: rgba(255, 255, 255, 0.76);
}

.queries-drawer-heading {
  min-width: 0;
}

.queries-drawer-title {
  margin: 0;
  color: var(--color-midnight);
  font-size: 1.08rem;
  font-weight: 800;
  line-height: 1.35;
}

.queries-drawer-subtitle {
  margin: 5px 0 0;
  color: var(--color-muted);
  font-size: 0.76rem;
}

.queries-drawer-close {
  display: grid;
  flex: 0 0 34px;
  width: 34px;
  height: 34px;
  place-items: center;
  border: 1px solid rgba(13, 34, 56, 0.1);
  border-radius: 9px;
  background: #fff;
  color: var(--color-navy);
  font-size: 1rem;
  cursor: pointer;
  transition:
    background 0.2s ease,
    border-color 0.2s ease,
    transform 0.2s ease;
}

.queries-drawer-close:hover {
  border-color: rgba(214, 166, 59, 0.45);
  background: var(--color-ivory);
  transform: rotate(2deg);
}

.queries-drawer-body {
  flex: 1;
  overflow-y: auto;
  padding: 22px 24px 30px;
}

/* ---------------------------------------------------------
   QUERY DETAIL
   --------------------------------------------------------- */

.query-detail-identity {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
}

.query-detail-avatar {
  display: grid;
  flex: 0 0 44px;
  width: 44px;
  height: 44px;
  place-items: center;
  border: 1px solid rgba(214, 166, 59, 0.3);
  border-radius: 50%;
  background: rgba(214, 166, 59, 0.1);
  color: var(--color-midnight);
  font-weight: 850;
}

.query-detail-name {
  margin: 0;
  color: var(--color-midnight);
  font-size: 0.95rem;
  font-weight: 800;
}

.query-detail-email {
  margin: 3px 0 0;
  color: var(--color-muted);
  font-size: 0.75rem;
}

.query-detail-meta-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 20px;
}

.query-detail-meta-card {
  padding: 12px 13px;
  border: 1px solid rgba(13, 34, 56, 0.08);
  border-radius: 11px;
  background: rgba(255, 255, 255, 0.72);
}

.query-detail-meta-label {
  display: block;
  margin-bottom: 5px;
  color: var(--color-muted);
  font-size: 0.65rem;
  font-weight: 800;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.query-detail-meta-value {
  color: var(--color-midnight);
  font-size: 0.78rem;
  font-weight: 750;
  line-height: 1.45;
}

.query-detail-message {
  margin-bottom: 22px;
  padding: 16px;
  border: 1px solid rgba(13, 34, 56, 0.08);
  border-radius: 13px;
  background: #fff;
}

.query-detail-message-label {
  margin: 0 0 8px;
  color: var(--color-muted);
  font-size: 0.67rem;
  font-weight: 800;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.query-detail-message-text {
  margin: 0;
  color: var(--color-charcoal);
  font-size: 0.84rem;
  line-height: 1.72;
  white-space: pre-wrap;
}

/* ---------------------------------------------------------
   CONVERSATION
   --------------------------------------------------------- */

.query-conversation {
  display: flex;
  flex-direction: column;
  gap: 11px;
  margin-bottom: 22px;
}

.query-conversation-message {
  max-width: 88%;
  padding: 12px 14px;
  border: 1px solid rgba(13, 34, 56, 0.08);
  border-radius: 13px;
  background: #fff;
}

.query-conversation-message.customer {
  align-self: flex-start;
}

.query-conversation-message.admin {
  align-self: flex-end;
  border-color: rgba(214, 166, 59, 0.2);
  background: rgba(214, 166, 59, 0.08);
}

.query-conversation-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 5px;
}

.query-conversation-sender {
  color: var(--color-midnight);
  font-size: 0.68rem;
  font-weight: 800;
}

.query-conversation-time {
  color: var(--color-muted);
  font-size: 0.62rem;
}

.query-conversation-text {
  margin: 0;
  color: var(--color-charcoal);
  font-size: 0.78rem;
  line-height: 1.62;
  white-space: pre-wrap;
}

/* ---------------------------------------------------------
   REPLY
   --------------------------------------------------------- */

.query-reply-section {
  padding-top: 18px;
  border-top: 1px solid rgba(13, 34, 56, 0.09);
}

.query-reply-label {
  display: block;
  margin-bottom: 8px;
  color: var(--color-midnight);
  font-size: 0.75rem;
  font-weight: 800;
}

.query-reply-textarea {
  width: 100%;
  min-height: 135px;
  resize: vertical;
  padding: 13px 14px;
  border: 1px solid var(--color-border);
  border-radius: 11px;
  outline: none;
  background: #fff;
  color: var(--color-charcoal);
  font: inherit;
  font-size: 0.82rem;
  line-height: 1.6;
  transition:
    border-color 0.2s ease,
    box-shadow 0.2s ease;
}

.query-reply-textarea::placeholder {
  color: var(--color-muted);
}

.query-reply-textarea:focus {
  border-color: rgba(214, 166, 59, 0.72);
  box-shadow: 0 0 0 4px rgba(214, 166, 59, 0.1);
}

.query-reply-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 9px;
  margin-top: 11px;
}

.query-reply-button {
  min-height: 40px;
  padding: 0 17px;
  border: 1px solid var(--color-gold-dark);
  border-radius: 9px;
  background: var(--color-gold);
  color: var(--color-midnight);
  font-size: 0.76rem;
  font-weight: 850;
  cursor: pointer;
  box-shadow: 0 6px 16px rgba(214, 166, 59, 0.16);
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease,
    background 0.2s ease;
}

.query-reply-button:hover:not(:disabled) {
  background: var(--color-gold-light);
  transform: translateY(-1px);
  box-shadow: 0 9px 20px rgba(214, 166, 59, 0.2);
}

.query-reply-button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

/* ---------------------------------------------------------
   DRAWER ERROR / STATUS
   --------------------------------------------------------- */

.query-action-error {
  margin-top: 10px;
  padding: 10px 12px;
  border: 1px solid rgba(185, 28, 28, 0.16);
  border-radius: 9px;
  background: rgba(185, 28, 28, 0.06);
  color: #b91c1c;
  font-size: 0.73rem;
  line-height: 1.5;
  animation: queriesStatusEnter 0.25s ease both;
}

.query-action-success {
  margin-top: 10px;
  padding: 10px 12px;
  border: 1px solid rgba(22, 101, 52, 0.16);
  border-radius: 9px;
  background: rgba(22, 101, 52, 0.06);
  color: #166534;
  font-size: 0.73rem;
  line-height: 1.5;
  animation: queriesStatusEnter 0.25s ease both;
}

/* ---------------------------------------------------------
   ANIMATIONS
   --------------------------------------------------------- */

@keyframes adminQueriesPageEnter {
  from {
    opacity: 0;
    transform: translateY(7px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes queriesOverlayEnter {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

@keyframes queriesDrawerEnter {
  from {
    opacity: 0;
    transform: translateX(28px);
  }

  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes queriesStatusEnter {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes queriesPulse {
  0%,
  100% {
    opacity: 0.55;
  }

  50% {
    opacity: 1;
  }
}

/* ---------------------------------------------------------
   RESPONSIVE
   --------------------------------------------------------- */

@media (max-width: 900px) {
  .queries-toolbar {
    align-items: stretch;
  }

  .queries-search {
    width: 100%;
    max-width: 100%;
  }

  .queries-filters {
    width: 100%;
  }

  .queries-filter-button {
    flex: 1 1 auto;
  }

  .queries-drawer {
    width: min(100%, 560px);
  }
}

@media (max-width: 640px) {
  .admin-queries-header {
    margin-bottom: 18px;
  }

  .queries-toolbar {
    gap: 11px;
  }

  .queries-filters {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .queries-filter-button {
    width: 100%;
  }

  .queries-table-card {
    border-radius: 14px;
  }

  .queries-pagination {
    align-items: flex-start;
    flex-direction: column;
  }

  .queries-pagination-actions {
    width: 100%;
    justify-content: flex-end;
  }

  .queries-drawer {
    width: 100%;
    border-left: 0;
  }

  .queries-drawer-header {
    padding: 18px;
  }

  .queries-drawer-body {
    padding: 18px 18px 26px;
  }

  .query-detail-meta-grid {
    grid-template-columns: 1fr;
  }

  .query-conversation-message {
    max-width: 94%;
  }
}

@media (max-width: 420px) {
  .queries-filters {
    grid-template-columns: 1fr;
  }

  .queries-drawer-title {
    font-size: 0.98rem;
  }

  .query-detail-message {
    padding: 13px;
  }

  .query-reply-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .query-reply-button {
    width: 100%;
  }
}

@media (prefers-reduced-motion: reduce) {
  .admin-queries-page,
  .queries-overlay,
  .queries-drawer,
  .query-action-error,
  .query-action-success,
  .queries-loading-state {
    animation: none !important;
  }

  .queries-filter-button,
  .query-view-button,
  .queries-drawer-close,
  .query-reply-button {
    transition: none !important;
  }
}
/* =========================================================
   GLOBAL LANGUAGE SWITCHER — NAVBAR
   ========================================================= */

.navbar-language {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;

  flex-shrink: 0;

  white-space: nowrap;
}

.navbar-language > span {
