}

.navbar-links > a.is-active:hover {
  color: var(--color-gold-light);
  transform: none;
}


/* =========================================================
   MOBILE NAVBAR — ACTIVE PAGE
   ========================================================= */

.navbar-mobile-links > a.is-active {
  color: #8f681e !important;

  background:
    linear-gradient(
      90deg,
      rgba(201, 166, 94, 0.16),
      rgba(201, 166, 94, 0.055)
    );

  border-bottom-color:
    rgba(201, 166, 94, 0.42);

  position: relative;

  font-weight: 700;
}

.navbar-mobile-links > a.is-active::before {
  content: "";

  position: absolute;

  left: 0;
  top: 9px;
  bottom: 9px;

  width: 3px;

  border-radius: 999px;

  background:
    linear-gradient(
      180deg,
      var(--color-gold-light),
      var(--color-gold)
    );

  box-shadow:
    0 0 8px
    rgba(201, 166, 94, 0.35);
}

.navbar-mobile-links > a.is-active span:last-child {
  color: var(--color-gold);
  transform: translateX(2px);
}


/* =========================================================
   ACCESSIBILITY — KEYBOARD FOCUS
   ========================================================= */

.navbar-links > a.is-active:focus-visible,
.navbar-mobile-links > a.is-active:focus-visible {
  outline:
    2px solid
    rgba(201, 166, 94, 0.65);

  outline-offset: 2px;
}
/* =========================================================
   ADMIN SETTINGS — CONSULTANT ACCESS & RECOVERY
   ========================================================= */

.admin-settings-consultant-access-card {
  overflow: hidden;
}

.admin-settings-consultant-summary {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr)) auto;
  gap: 12px;
  align-items: stretch;
  margin-top: 24px;
}

.admin-settings-consultant-stat {
  min-width: 0;
  padding: 16px 17px;
  border: 1px solid rgba(180, 145, 74, 0.18);
  border-radius: 14px;
  background: #fffdf8;
}

.admin-settings-consultant-stat.is-revoked {
  background: #fff9f6;
  border-color: rgba(164, 91, 80, 0.16);
}

.admin-settings-consultant-stat span {
  display: block;
  margin-bottom: 6px;
  color: #9a8b78;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.12em;
}

.admin-settings-consultant-stat strong {
  display: block;
  color: #2d2318;
  font-size: 1.35rem;
  line-height: 1;
}

.admin-settings-consultant-stat small {
  display: block;
  margin-top: 6px;
  color: #887864;
  font-size: 10px;
  line-height: 1.5;
}

.admin-settings-consultant-manage-link {
  min-width: 170px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  padding: 14px 16px;
  border: 1px solid rgba(180, 145, 74, 0.24);
  border-radius: 14px;
  background: linear-gradient(135deg, #fffaf0, #f7eedc);
  color: #70531c;
  font-size: 11px;
  font-weight: 800;
  text-decoration: none;
  transition: transform 160ms ease, border-color 160ms ease, box-shadow 160ms ease;
}

.admin-settings-consultant-manage-link:hover {
  transform: translateY(-1px);
  border-color: rgba(180, 145, 74, 0.4);
  box-shadow: 0 8px 20px rgba(7, 24, 42, 0.06);
}

.admin-settings-consultant-note {
  display: grid;
  grid-template-columns: 26px minmax(0, 1fr);
  gap: 10px;
  align-items: start;
  margin-top: 14px;
  padding: 12px 13px;
  border: 1px solid rgba(180, 145, 74, 0.15);
  border-radius: 12px;
  background: rgba(250, 247, 239, 0.72);
}

.admin-settings-consultant-note > span {
  width: 26px;
  height: 26px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: rgba(214, 166, 59, 0.13);
  color: #73551c;
  font-size: 11px;
  font-weight: 800;
}

.admin-settings-consultant-note p {
  margin: 0;
  color: #766653;
  font-size: 11px;
  line-height: 1.65;
}

.admin-settings-consultant-list {
  display: grid;
  gap: 10px;
  margin-top: 18px;
}

.admin-settings-consultant-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 15px;
  border: 1px solid rgba(164, 91, 80, 0.14);
  border-radius: 14px;
  background: #fffdfb;
}

.admin-settings-consultant-identity {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 12px;
}

.admin-settings-consultant-avatar {
  width: 42px;
  height: 42px;
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
  background: #f5e9d5;
  border: 1px solid rgba(180, 145, 74, 0.18);
  color: #6c511c;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.05em;
}

.admin-settings-consultant-main {
  min-width: 0;
}

.admin-settings-consultant-name-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 7px;
  margin-bottom: 4px;
}

.admin-settings-consultant-name-row strong {
  color: #2d2318;
  font-size: 13px;
  font-weight: 800;
}

.admin-settings-consultant-email {
  display: block;
  color: #887864;
  font-size: 11px;
  overflow-wrap: anywhere;
}

.admin-settings-consultant-meta {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px 12px;
  margin-top: 6px;
  color: #a08f79;
  font-size: 10px;
}

.admin-settings-consultant-meta span + span::before {
  content: "•";
  margin-right: 10px;
  color: #c0ad90;
}

.admin-settings-consultant-actions {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 8px;
}

.admin-settings-consultant-actions .admin-settings-management-button.danger {
  color: #8d4d45;
}

.admin-settings-consultant-empty {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 18px;
  padding: 17px;
  border: 1px dashed rgba(180, 145, 74, 0.25);
  border-radius: 14px;
  background: rgba(250, 247, 239, 0.45);
}

.admin-settings-consultant-empty-icon {
  width: 34px;
  height: 34px;
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  background: rgba(96, 145, 109, 0.1);
  border: 1px solid rgba(96, 145, 109, 0.16);
  color: #46664f;
  font-size: 13px;
  font-weight: 900;
}

.admin-settings-consultant-empty strong {
  display: block;
  color: #2d2318;
  font-size: 12px;
  font-weight: 800;
}

.admin-settings-consultant-empty p {
  margin: 4px 0 0;
  color: #887864;
  font-size: 10px;
  line-height: 1.55;
}

@media (max-width: 900px) {
  .admin-settings-consultant-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .admin-settings-consultant-manage-link {
    grid-column: 1 / -1;
    width: 100%;
  }
}

@media (max-width: 720px) {
  .admin-settings-consultant-row {
    align-items: stretch;
    flex-direction: column;
  }

  .admin-settings-consultant-actions {
    width: 100%;
  }

  .admin-settings-consultant-actions .admin-settings-management-button {
    flex: 1 1 0;
  }
}

@media (max-width: 520px) {
  .admin-settings-consultant-summary {
    grid-template-columns: 1fr;
  }

  .admin-settings-consultant-manage-link {
    grid-column: auto;
  }

  .admin-settings-consultant-identity {
    align-items: flex-start;
  }

  .admin-settings-consultant-actions {
    flex-direction: column;
  }

  .admin-settings-consultant-actions .admin-settings-management-button {
    width: 100%;
  }

  .admin-settings-consultant-meta {
    flex-direction: column;
    align-items: flex-start;
    gap: 4px;
  }

  .admin-settings-consultant-meta span + span::before {
    display: none;
  }
}


/* =========================================================
   MY CONSULTANT PROFILE / ADMIN IDENTITY LINK
   ========================================================= */
.admin-settings-my-consultant-card {
  border-color: #e7dece;
}

.admin-settings-my-consultant-locked {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 16px;
  border: 1px solid #eadfcf;
  border-radius: 14px;
  background: #fbf8f1;
}

.admin-settings-my-consultant-lock {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: #f1e8d7;
}

.admin-settings-my-consultant-locked strong,
.admin-settings-my-consultant-summary strong {
  display: block;
  color: #1d2733;
}

.admin-settings-my-consultant-locked p,
.admin-settings-my-consultant-summary p {
  margin: 5px 0 0;
  color: #767d86;
  line-height: 1.55;
}

.admin-settings-my-consultant-summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 18px;
  border: 1px solid #eee5d8;
  border-radius: 15px;
  background: #fbfaf7;
}

.admin-settings-my-consultant-summary.is-empty {
  background: #fffdf8;
}

@media (max-width: 720px) {
  .admin-settings-my-consultant-summary {
    align-items: stretch;
    flex-direction: column;
  }

  .admin-settings-my-consultant-summary .admin-settings-action-button {
    width: 100%;
    justify-content: center;
  }
}
/* =========================================================
   AKSHAANSHH JYOTISH — LEGAL POLICY PAGES
   Shared stylesheet for Terms, Privacy and Refund pages.
   Import once from src/app/layout.tsx after globals.css.
   ========================================================= */

.legal-standalone-page {
  position: relative;
  overflow: hidden;
  padding: 74px 0 108px;
  background:
    radial-gradient(circle at 10% 0%, rgba(214, 166, 59, 0.13), transparent 30%),
    radial-gradient(circle at 92% 15%, rgba(7, 24, 42, 0.045), transparent 30%),
    linear-gradient(180deg, #fcfaf4 0%, #f7f3e9 100%);
}

.legal-standalone-page::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.22;
  background-image:
    radial-gradient(circle, rgba(154, 107, 19, 0.12) 0.65px, transparent 0.8px);
  background-size: 30px 30px;
  mask-image: linear-gradient(to bottom, rgba(0, 0, 0, 0.55), transparent 72%);
}

.legal-standalone-page .site-container {
  position: relative;
  z-index: 1;
  max-width: 1160px;
}

.legal-standalone-card {
  max-width: 960px;
  margin: 0 auto;
  padding: clamp(28px, 5vw, 60px);
  border: 1px solid rgba(184, 139, 43, 0.28);
  border-radius: 28px;
  background: rgba(255, 253, 247, 0.96);
  box-shadow:
    0 28px 80px rgba(72, 52, 18, 0.09),
    0 3px 14px rgba(72, 52, 18, 0.04);
}

.legal-standalone-header {
  padding-bottom: 31px;
  border-bottom: 1px solid rgba(184, 139, 43, 0.24);
  text-align: center;
}

.legal-standalone-header h1 {
  max-width: 760px;
  margin: 11px auto 15px;
  color: #07182a;
  font-family: var(--font-heading), Georgia, serif;
  font-size: clamp(2.35rem, 5vw, 4.2rem);
  font-weight: 500;
  line-height: 1;
  letter-spacing: -0.035em;
}

.legal-standalone-header > p {
  max-width: 710px;
  margin: 0 auto;
  color: #69717c;
  font-size: 0.93rem;
  line-height: 1.85;
}

.legal-standalone-page .legal-document-meta {
  justify-content: center;
  margin-top: 25px;
}

.legal-standalone-nav {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 7px;
  margin: 29px 0 8px;
  padding: 8px;
  border: 1px solid rgba(184, 139, 43, 0.16);
  border-radius: 17px;
  background: rgba(255, 255, 255, 0.72);
}

.legal-standalone-nav a {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  padding: 10px 11px;
  border-radius: 10px;
  color: #69717c;
  font-size: 0.72rem;
  font-weight: 700;
  line-height: 1.3;
  text-decoration: none;
  transition: color 0.2s ease, background 0.2s ease, transform 0.2s ease;
}

.legal-standalone-nav a span {
  display: inline-flex;
  flex: 0 0 27px;
  width: 27px;
  height: 27px;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(184, 139, 43, 0.28);
  border-radius: 50%;
  background: rgba(214, 166, 59, 0.09);
  color: #9a6b13;
  font-size: 0.62rem;
  font-weight: 800;
}

.legal-standalone-nav a:hover {
  color: #07182a;
  background: rgba(214, 166, 59, 0.08);
  transform: translateY(-1px);
}

.legal-standalone-sections {
  margin-top: 6px;
}

.legal-standalone-section {
  scroll-margin-top: 104px;
  padding: 44px 0;
  border-bottom: 1px solid rgba(184, 139, 43, 0.17);
}

.legal-standalone-section:last-child {
  border-bottom: 0;
}

.legal-standalone-section > p {
  max-width: 800px;
  margin: 0 0 14px;
  color: #69717c;
  font-size: 0.88rem;
  line-height: 1.9;
}

.legal-standalone-section > p:last-of-type {
  margin-bottom: 0;
}

.legal-standalone-page .legal-document-footer {
  align-items: flex-start;
}

.legal-link-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 10px;
  margin-top: 18px;
}

.legal-link-row a {
  display: inline-flex;
  align-items: center;
  padding: 9px 12px;
  border: 1px solid rgba(184, 139, 43, 0.27);
  border-radius: 999px;
  background: rgba(214, 166, 59, 0.08);
  color: #9a6b13;
  font-size: 0.7rem;
  font-weight: 800;
  text-decoration: none;
  transition: background 0.2s ease, transform 0.2s ease;
}

.legal-link-row a:hover {
  background: rgba(214, 166, 59, 0.15);
  transform: translateY(-1px);
}

@media (max-width: 700px) {
  .legal-standalone-page {
    padding: 50px 0 76px;
  }

  .legal-standalone-card {
    padding: 22px 18px;
    border-radius: 22px;
  }

  .legal-standalone-nav {
    grid-template-columns: 1fr;
  }

  .legal-standalone-section {
    padding: 34px 0;
  }

  .legal-standalone-section > p {
    font-size: 0.84rem;
    line-height: 1.82;
  }
}

@media (prefers-reduced-motion: reduce) {
  .legal-standalone-nav a,
  .legal-link-row a {
    transition: none;
  }

  .legal-standalone-nav a:hover,
  .legal-link-row a:hover {
    transform: none;
  }
}
